// cspCountAncestorProbes runs fn with a PATH-front `git` shim that appends
// every argv to a log and then execs the real git, and returns how many
// `merge-base --is-ancestor` processes fn caused. The real binary is
// resolved BEFORE the shim is installed, so the shim can never re-resolve
// itself.
func cspCountAncestorProbes(t *testing.T, fn func()) int {
	t.Helper()
	realGit, err := exec.LookPath("git")
	if err != nil {
		t.Fatalf("a real git must be resolvable before the shim is installed: %v", err)
	}
	dir := t.TempDir()
	log := filepath.Join(dir, "argv.log")
	script := "#!/bin/sh\nprintf '%s\\n' \"$*\" >> " + log + "\nexec " + realGit + " \"$@\"\n"
	if err := os.WriteFile(filepath.Join(dir, "git"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(log, nil, 0o644); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
	fn()
	data, err := os.ReadFile(log)
	if err != nil {
		t.Fatalf("read argv log: %v", err)
	}
	n := 0
	for _, line := range strings.Split(string(data), "\n") {
		if strings.Contains(line, "merge-base --is-ancestor") {
			n++
		}
	}
	return n
}

// ============================================================================
// Group F: finalizeTransaction's §22.13n whole-plan ancestry postcondition —
// proving the re-verification loop that runs once every entry has already
// been individually rebased and validated is a REAL, independent safety net
// rather than a restatement of processBranch's own per-entry check, and that
// a refusal there preserves recoverable state instead of silently completing
// or destroying it (checkout_sync.go's finalizeTransaction).
// ============================================================================

// cspEmptyTreeSHA is git's well-known, universally valid empty-tree object
// ID (the SHA-1 of a tree with zero entries). `git commit-tree
// cspEmptyTreeSHA` builds a brand-new, PARENTLESS commit that shares no
// common ancestor with anything else in the fixture repository, so forcing
// a branch onto it is a genuine ancestry break, never a same-lineage reset
// a real "is-ancestor" check could satisfy by accident.
const cspEmptyTreeSHA = "4b825dc642cb6eb9a060e54bf8d69288fbee4904"

// cspFinalizePostconditionStack is the two-entry stack every test in this
// group shares: "second" depends on "first" by logical Name (D1-a), so
// TopoSort/buildCheckoutPlanFrom always order the plan [first, second] —
// making index 1 (len-1) the LAST plan index, and "first" the EARLIER entry
// a mid-flight hook can move out from under the whole-plan verification loop.
func cspFinalizePostconditionStack() []StackEntry {
	return []StackEntry{
		{Name: "first", Base: "main"},
		{Name: "second", Base: "first"},
	}
}

// cspFinalizePostconditionFixture builds a real two-entry checkout stack —
// "first" based on "main" with one commit of its own, "second" based on
// "first" with one commit of its own — leaves HEAD parked on "main" (which
// is in neither entry's plan row, so RunCheckoutSync's own precondition and
// restoration checks are undisturbed), and returns a real, history-
// disconnected "rogue" commit SHA a later StepHook can force "first" onto.
func cspFinalizePostconditionFixture(t *testing.T) (dir, feature, fp, rogueSHA string) {
	t.Helper()
	var ws Workspace
	dir, ws = cspFixture(t)
	feature = "feat-finalize-postcondition"
	fp = ws.FeaturePath(feature)
	addStackEntries(t, ws, feature, cspFinalizePostconditionStack())

	gitInTest(t, dir, "branch", "first", "main")
	gitInTest(t, dir, "checkout", "first")
	writeFileInTest(t, dir, "first.txt", "first\n")
	gitInTest(t, dir, "add", ".")
	gitInTest(t, dir, "commit", "-m", "first commit")

	gitInTest(t, dir, "branch", "second", "first")
	gitInTest(t, dir, "checkout", "second")
	writeFileInTest(t, dir, "second.txt", "second\n")
	gitInTest(t, dir, "add", ".")
	gitInTest(t, dir, "commit", "-m", "second commit")

	gitInTest(t, dir, "checkout", "main")

	rogueSHA = gitInTest(t, dir, "commit-tree", cspEmptyTreeSHA, "-m", "rogue: unrelated history")
	return dir, feature, fp, rogueSHA
}

// TestCheckoutSyncPlan_FinalizeTransaction_WholePlanAncestryPostcondition now
// pins the stronger transactional boundary that runs before finalization: an
// operator move of an unallowed ref during the second action is refused while
// the action is still intent-only. The old whole-plan ancestry sentence is no
// longer reachable in this fixture because adopting the foreign move would
// destroy rollback ownership evidence.
func TestCheckoutSyncPlan_FinalizeTransaction_WholePlanAncestryPostcondition(t *testing.T) {
	t.Run("EarlierEntryMovedAtLastIndexRefusesAndPreservesState", func(t *testing.T) {
		dir, feature, fp, rogueSHA := cspFinalizePostconditionFixture(t)
		lastIndex := len(cspFinalizePostconditionStack()) - 1 // 1: "second", the last plan row
		firstBefore := gitInTest(t, dir, "rev-parse", "first")
		secondBefore := gitInTest(t, dir, "rev-parse", "second")
		stackBefore, err := os.ReadFile(StackPath(fp))
		if err != nil {
			t.Fatal(err)
		}

		var lastIndexHits int
		StepHook = func(stage CheckoutStage, branchIndex int) error {
			if stage == StageRebased && branchIndex == lastIndex {
				lastIndexHits++
				gitInTest(t, dir, "branch", "-f", "first", rogueSHA)
			}
			return nil
		}
		t.Cleanup(func() { StepHook = nil })

		opts := cspOpts(feature, fp, dir, cspAllPolicy(SyncFetchDisabled))

		err = nil
		stdout, stderr := captureStdoutAndStderr(t, func() {
			err = RunCheckoutSync(opts)
		})

		const wantErr = "branch refs/heads/first moved during sync action 2 outside its attributable ref set; recovery evidence is preserved"
		if err == nil {
			t.Fatal("expected the action ownership check to refuse the operator move")
		}
		if err.Error() != wantErr {
			t.Fatalf("err = %q, want the ownership refusal %q", err.Error(), wantErr)
		}

		// Companion: the mutating hook fired EXACTLY once, at the last plan
		// index — proving this failure comes from ONE genuine, shipped-seam-
		// driven mutation (the shipped StageRebased call site, no new hook
		// site added), not a fixture that was already broken or a hook that
		// over-fired.
		if lastIndexHits != 1 {
			t.Fatalf("lastIndexHits = %d, want exactly 1: the shipped StageRebased call site must fire once for the last plan index", lastIndexHits)
		}

		if got := gitInTest(t, dir, "rev-parse", "first"); got != rogueSHA {
			t.Fatalf("git rev-parse first = %s, want %s (the hook's own target)", got, rogueSHA)
		}
		if got := gitInTest(t, dir, "rev-parse", "second"); got != secondBefore {
			t.Fatalf("second moved from %s to %s; the no-op second rebase must stay unchanged", secondBefore, got)
		}
		if rogueSHA == firstBefore {
			t.Fatal("fixture did not create distinct operator work")
		}

		// (3) Marker-free: this test calls internal.RunCheckoutSync directly
		// and never goes through internal/cli, whose sync_plan_guard.go is
		// the ONLY place "plan-guard: " is ever written (PlanGuardRefusalError
		// itself never carries that prefix). This run is also unguarded
		// (opts.PlanGuard is the zero value), so no guard document, refusal,
		// or marker line is ever produced or has anywhere shipped to print
		// from in the first place.
		if combined := stdout + stderr; strings.Contains(combined, "plan-guard: ") {
			t.Fatalf("captured output = %q, want no %q marker: this run is unguarded", combined, "plan-guard: ")
		}

		if !HasCheckoutTransaction(fp) {
			t.Fatal("the foreign-work refusal must preserve recovery evidence")
		}
		tx, lerr := LoadCheckoutTransaction(fp)
		if lerr != nil {
			t.Fatalf("LoadCheckoutTransaction: %v, want the preserved transaction to still be readable", lerr)
		}
		if len(tx.Plan) != 2 || tx.Plan[0].Name != "first" || tx.Plan[1].Name != "second" {
			t.Fatalf("tx.Plan = %+v, want the two-entry [first second] plan preserved verbatim", tx.Plan)
		}
		if tx.CurrentIndex != 1 {
			t.Fatalf("tx.CurrentIndex = %d, want 1: the second action was not adopted", tx.CurrentIndex)
		}
		if len(tx.CompletedIndices) != 1 || tx.CompletedIndices[0] != 0 {
			t.Fatalf("tx.CompletedIndices = %v, want [0]", tx.CompletedIndices)
		}
		if tx.Stage != StageRebased {
			t.Fatalf("tx.Stage = %q, want %q: Git finished but ownership reconciliation refused", tx.Stage, StageRebased)
		}
		if tx.Transaction == nil || len(tx.Transaction.Actions) != 2 {
			t.Fatalf("transaction actions = %+v, want two journaled actions", tx.Transaction)
		}
		lastAction := tx.Transaction.Actions[1]
		if lastAction.Entry != "second" || lastAction.Status != SyncTxnActionIntent {
			t.Fatalf("last action = %+v, want intent-only second action", lastAction)
		}
		expected := map[string]string{}
		for _, repo := range tx.Transaction.Repositories {
			for _, ref := range repo.Refs {
				expected[ref.Ref] = ref.ExpectedSHA
			}
		}
		if expected["refs/heads/first"] != firstBefore || expected["refs/heads/second"] != secondBefore {
			t.Fatalf("expected ref image adopted foreign work: %v", expected)
		}
		if !HasCheckoutLock(fp) {
			t.Fatal("HasCheckoutLock = false, want true: a preserved, recoverable transaction must still hold its lock against a concurrent run")
		}

		stackAfter, readErr := os.ReadFile(StackPath(fp))
		if readErr != nil {
			t.Fatal(readErr)
		}
		if string(stackAfter) != string(stackBefore) {
			t.Fatal("foreign-work refusal reached metadata finalization")
		}

		// (7) The failure is NATIVE, not a guard refusal: it is not a
		// *PlanGuardRefusalError under errors.As, and it carries neither the
		// plan-guard marker nor the state-preserved prefix, because the
		// refusing party is the shipped finalizer (§13.5 rule F, §6.4).
		var refusal *PlanGuardRefusalError
		if errors.As(err, &refusal) {
			t.Fatalf("err is a *PlanGuardRefusalError (%+v); the shipped finalizer's own postcondition must never be typed as a guard refusal", refusal)
		}
		if strings.Contains(err.Error(), "state-preserved: ") {
			t.Fatalf("err = %q, want no state-preserved prefix", err.Error())
		}
	})

	// (8) The GUARDED twin of the same postcondition. §22.13n binds
	// "executing routes only, guarded and unguarded alike": an armed run
	// must refuse with the IDENTICAL native sentence, leave the identical
	// artefacts, and still not produce a guard-typed error or a marker.
	t.Run("GuardedRunRefusesWithTheIdenticalNativeSentence", func(t *testing.T) {
		dir, feature, fp, rogueSHA := cspFinalizePostconditionFixture(t)
		lastIndex := len(cspFinalizePostconditionStack()) - 1
		secondBefore := gitInTest(t, dir, "rev-parse", "second")
		stackBefore, err := os.ReadFile(StackPath(fp))
		if err != nil {
			t.Fatal(err)
		}

		StepHook = func(stage CheckoutStage, branchIndex int) error {
			if stage == StageRebased && branchIndex == lastIndex {
				gitInTest(t, dir, "branch", "-f", "first", rogueSHA)
			}
			return nil
		}
		t.Cleanup(func() { StepHook = nil })

		limit := 50
		opts := cspOpts(feature, fp, dir, cspAllPolicy(SyncFetchDisabled))
		opts.PlanGuard = CheckoutPlanGuard{MaxTotal: &limit}

		err = nil
		stdout, stderr := captureStdoutAndStderr(t, func() {
			err = RunCheckoutSync(opts)
		})

		const wantErr = "branch refs/heads/first moved during sync action 2 outside its attributable ref set; recovery evidence is preserved"
		if err == nil || err.Error() != wantErr {
			t.Fatalf("guarded err = %v, want ownership refusal %q", err, wantErr)
		}
		var refusal *PlanGuardRefusalError
		if errors.As(err, &refusal) {
			t.Fatalf("guarded err is a *PlanGuardRefusalError (%+v); want native transaction ownership refusal", refusal)
		}
		if combined := stdout + stderr; strings.Contains(combined, "plan-guard: ") {
			t.Fatalf("captured output = %q, want no plan-guard marker even on the guarded route", combined)
		}
		if !HasCheckoutTransaction(fp) || !HasCheckoutLock(fp) {
			t.Fatal("the guarded route must preserve the same two artefacts the unguarded one does")
		}
		if got := gitInTest(t, dir, "rev-parse", "first"); got != rogueSHA {
			t.Fatalf("later operator work was overwritten: got %s want %s", got, rogueSHA)
		}
		if got := gitInTest(t, dir, "rev-parse", "second"); got != secondBefore {
			t.Fatalf("second moved from %s to %s", secondBefore, got)
		}
		stackAfter, readErr := os.ReadFile(StackPath(fp))
		if readErr != nil {
			t.Fatal(readErr)
		}
		if string(stackAfter) != string(stackBefore) {
			t.Fatal("guarded foreign-work refusal reached metadata finalization")
		}
	})

	// (9) The plan route now proves each cutoff as well as evaluating stack
	// ancestry, but still never runs finalizeTransaction. The executing twin
	// therefore issues at least one additional finalization ancestry probe per
	// plan row.
	t.Run("PlanRouteAddsZeroFinalizationMergeBaseProbes", func(t *testing.T) {
		dir, feature, fp, _ := cspFinalizePostconditionFixture(t)
		opts := cspOpts(feature, fp, dir, cspAllPolicy(SyncFetchDisabled))
		entries := len(cspFinalizePostconditionStack())

		planProbes := cspCountAncestorProbes(t, func() {
			plan, err := PlanCheckoutRebase(opts, PlanWriters{Prose: io.Discard})
			if err != nil {
				t.Fatalf("PlanCheckoutRebase: %v", err)
			}
			if !plan.Restore.Applies {
				t.Fatalf("restore.applies = %v, want true on a fresh checkout plan with rows", plan.Restore.Applies)
			}
		})
		if HasCheckoutTransaction(fp) || HasCheckoutLock(fp) {
			t.Fatal("a --plan route must create neither a transaction nor a lock")
		}
		if planProbes < entries {
			t.Fatalf("plan route issued %d `merge-base --is-ancestor` processes, want at least %d stack/cutoff proofs",
				planProbes, entries)
		}

		execProbes := cspCountAncestorProbes(t, func() {
			if err := RunCheckoutSync(opts); err != nil {
				t.Fatalf("the executing control must succeed: %v", err)
			}
		})
		if execProbes < planProbes+entries {
			t.Fatalf("executing route issued %d ancestry probes, want at least %d (the plan's %d plus finalizeTransaction's own one per plan row)",
				execProbes, planProbes+entries, planProbes)
		}
	})

	// (5) Control twin: the identical fixture, but with NO hook installed at
	// all (StepHook stays nil, its production zero value), so nothing ever
	// moves "first". This proves the refusal above is not vacuous: given the
	// SAME plan and the SAME finalizeTransaction whole-plan loop, an
	// undisturbed run completes normally, deletes its transaction, and
	// releases its lock.
	t.Run("ControlWithoutHookCompletesAndCleansUp", func(t *testing.T) {
		dir, feature, fp, _ := cspFinalizePostconditionFixture(t)

		opts := cspOpts(feature, fp, dir, cspAllPolicy(SyncFetchDisabled))
		if err := RunCheckoutSync(opts); err != nil {
			t.Fatalf("RunCheckoutSync = %v, want success: nothing disturbs 'first' in this control run", err)
		}

		if HasCheckoutTransaction(fp) {
			t.Fatal("HasCheckoutTransaction = true, want false: a successful run must delete its transaction")
		}
		if HasCheckoutLock(fp) {
			t.Fatal("HasCheckoutLock = true, want false: a successful run must release its lock")
		}
	})
}

// ===========================================================================
// §22.24i (x), checkout half — the checkout UPGRADE writer is a no-op on an
// already-`3` subject and touches exactly state_version, route and the
// effective limit keys.
//
// It lives here, in package internal, because upgradeGuardedCheckoutTransaction
// is unexported; the source-level five-site enumeration and the external
// upgrade writer's own no-op assertion are owned by
// TestSyncGuardedState_Criterion22_24i_x_VersionWritingSitesHaveOneOwnerEach.
// ===========================================================================

func TestCheckoutSyncPlan_Criterion22_24i_x_CheckoutUpgradeIsANoOpOnAGuardedTransaction(t *testing.T) {
	// Each cell needs its OWN workspace root: the transaction path is derived
	// from the feature path's grandparent `state/` directory, so two feature
	// paths under one root would collide on the same file.
	newFeaturePath := func(t *testing.T) string {
		t.Helper()
		fp := filepath.Join(t.TempDir(), ".tws", "features", "f")
		if err := os.MkdirAll(fp, 0o755); err != nil {
			t.Fatal(err)
		}
		return fp
	}

	t.Run("already_guarded_is_untouched", func(t *testing.T) {
		featurePath := newFeaturePath(t)
		limit := 5
		tx := &CheckoutTransaction{
			StateVersion: CheckoutTransactionGuardedVersion,
			Route:        RouteLegacy,
			Feature:      "f", Stage: StagePlanned,
			MaxReplayTotal: &limit,
		}
		if err := SaveCheckoutTransaction(featurePath, tx); err != nil {
			t.Fatal(err)
		}
		before, err := os.ReadFile(CheckoutTransactionPath(featurePath))
		if err != nil {
			t.Fatal(err)
		}
		other := 99
		if err := upgradeGuardedCheckoutTransaction(featurePath, tx, nil, &other); err != nil {
			t.Fatalf("upgrade: %v", err)
		}
		after, err := os.ReadFile(CheckoutTransactionPath(featurePath))
		if err != nil {
			t.Fatal(err)
		}
		if string(before) != string(after) {
			t.Fatalf("an already-guarded transaction was rewritten:\n before=%q\n after=%q", before, after)
		}
		if tx.MaxReplayTotal == nil || *tx.MaxReplayTotal != limit {
			t.Fatalf("MaxReplayTotal = %v, want the persisted %d untouched", tx.MaxReplayTotal, limit)
		}
		if tx.Route != RouteLegacy {
			t.Fatalf("Route = %q, want the persisted legacy route untouched", tx.Route)
		}
	})

	t.Run("unguarded_upgrade_touches_only_version_route_and_limits", func(t *testing.T) {
		featurePath := newFeaturePath(t)
		tx := &CheckoutTransaction{
			Feature: "f", OriginalBranch: "main", OriginalHEAD: "abc",
			Stage: StageConflict, CurrentIndex: 1,
			CompletedIndices: []int{0},
			Plan:             []CheckoutPlanEntry{{Name: "a", Branch: "a", Base: "main"}},
			TestCommand:      "make check",
		}
		snapshot := *tx
		limit := 3
		if err := upgradeGuardedCheckoutTransaction(featurePath, tx, nil, &limit); err != nil {
			t.Fatalf("upgrade: %v", err)
		}
		if tx.StateVersion != CheckoutTransactionGuardedVersion {
			t.Fatalf("StateVersion = %d, want the guarded version", tx.StateVersion)
		}
		if tx.Route == "" {
			t.Fatal("Route must be inherited, never left empty")
		}
		if tx.MaxReplayTotal == nil || *tx.MaxReplayTotal != limit {
			t.Fatalf("MaxReplayTotal = %v, want %d", tx.MaxReplayTotal, limit)
		}
		if tx.Feature != snapshot.Feature || tx.OriginalBranch != snapshot.OriginalBranch ||
			tx.OriginalHEAD != snapshot.OriginalHEAD || tx.Stage != snapshot.Stage ||
			tx.CurrentIndex != snapshot.CurrentIndex || tx.TestCommand != snapshot.TestCommand ||
			len(tx.Plan) != len(snapshot.Plan) || len(tx.CompletedIndices) != len(snapshot.CompletedIndices) {
			t.Fatalf("the upgrade touched a field outside {state_version, route, limits}:\n before=%+v\n after=%+v", snapshot, *tx)
		}
	})
}

// TestCheckoutSyncPlan_Criterion22_24c_RouteVersionMatrix is the named owner
// of criterion 22.24c's nil-safety and route-vs-version derivation. It drives
// the four production predicates of §13.6 rule 4 — txNewMode, its exported
// wrapper TransactionNewMode, PayloadNewMode and CheckoutTriggersNeedV2 —
// over the full cross product of {nil, absent route, route: new-mode,
// route: legacy, unknown route} x {no version, v1, v2, v3, v4, v5}, so a nil
// dereference or a version-only comparison in any of them fails here.
func TestCheckoutSyncPlan_Criterion22_24c_RouteVersionMatrix(t *testing.T) {
	routes := []struct {
		name  string
		route string
	}{
		{"absent-route", ""},
		{"route-new-mode", RouteNewMode},
		{"route-legacy", RouteLegacy},
		{"unknown-route", "sideways"},
	}
	versions := []int{0, 1, 2, 3, 4, 5}

	// want answers the question the production switch answers: an explicit
	// route decides outright, anything else falls back to the version.
	want := func(route string, version, floor int) bool {
		switch route {
		case RouteNewMode:
			return true
		case RouteLegacy:
			return false
		default:
			return version >= floor
		}
	}

	t.Run("nil-is-never-new-mode", func(t *testing.T) {
		if txNewMode(nil) || TransactionNewMode(nil) || checkoutRecoveryIsNewMode(nil) {
			t.Fatalf("TransactionNewMode(nil) = true, want false")
		}
		if PayloadNewMode(nil) {
			t.Fatalf("PayloadNewMode(nil) = true, want false")
		}
		if !CheckoutTriggersNeedV2(nil, nil) {
			t.Fatalf("CheckoutTriggersNeedV2(nil, nil) = false: an absent transaction must still refuse trigger flags")
		}
		if !CheckoutTriggersNeedV2(nil, errors.New("unreadable")) {
			t.Fatalf("CheckoutTriggersNeedV2(nil, err) = false: an unreadable transaction must still refuse trigger flags")
		}
	})

	for _, r := range routes {
		for _, v := range versions {
			name := fmt.Sprintf("%s/v%d", r.name, v)
			t.Run(name, func(t *testing.T) {
				tx := &CheckoutTransaction{Feature: "f", StateVersion: v, Route: r.route}
				payload := &SyncRunState{Feature: "f", StateVersion: v, Route: r.route}

				wantTx := want(r.route, v, CheckoutTransactionVersion)
				if got := TransactionNewMode(tx); got != wantTx {
					t.Fatalf("TransactionNewMode = %v, want %v", got, wantTx)
				}
				if got := txNewMode(tx); got != wantTx {
					t.Fatalf("txNewMode = %v, want %v: the exported wrapper and its unexported subject must not diverge", got, wantTx)
				}
				if got := checkoutRecoveryIsNewMode(tx); got != wantTx {
					t.Fatalf("checkoutRecoveryIsNewMode = %v, want %v", got, wantTx)
				}
				wantPayload := want(r.route, v, SyncRunStateVersion)
				if got := PayloadNewMode(payload); got != wantPayload {
					t.Fatalf("PayloadNewMode = %v, want %v", got, wantPayload)
				}

				// CheckoutTriggersNeedV2 is exactly !TransactionNewMode once
				// the transaction loaded, and unconditionally true when it
				// did not.
				if got := CheckoutTriggersNeedV2(tx, nil); got != !wantTx {
					t.Fatalf("CheckoutTriggersNeedV2(tx, nil) = %v, want %v", got, !wantTx)
				}
				if got := CheckoutTriggersNeedV2(tx, errors.New("boom")); !got {
					t.Fatalf("CheckoutTriggersNeedV2(tx, err) = %v, want true: a load error always needs v2", got)
				}

				// Guardedness recognizes the genuine legacy v3 and
				// transactional v5 twins. Transactional v4 is not guarded
				// merely because its version is numerically above 3.
				wantGuarded := v == CheckoutTransactionGuardedVersion ||
					v == CheckoutTransactionTransactionalGuardedVersion
				if got := TransactionGuarded(tx); got != wantGuarded {
					t.Fatalf("TransactionGuarded = %v, want %v", got, wantGuarded)
				}
			})
		}
	}
	if !TransactionGuarded(&CheckoutTransaction{
		StateVersion: CheckoutTransactionTransactionalVersion,
		PlanGuarded:  true,
	}) {
		t.Fatal("PlanGuarded must remain an explicit guardedness signal")
	}
}

// ============================================================================
// checkoutBaseTokenFor and ReclaimCheckoutLock — safe-reparent's two
// behaviour-preserving extractions out of this file.
// ============================================================================

// TestCheckoutBaseTokenFor_ReproducesTheShippedInlineRule pins the extraction
// against a literal re-statement of the body it replaced, including the two
// properties that are easy to lose: an empty base is "no base at all" (the
// caller's `continue`), and StackEntry.Repo is deliberately NOT consulted —
// GetBranch matches on logical Name alone, exactly as the shipped arm did.
func TestCheckoutBaseTokenFor_ReproducesTheShippedInlineRule(t *testing.T) {
	stack := Stack{Branches: []StackEntry{
		{Name: "pr1", Branch: "feature/pr1", Base: "main"},
		{Name: "pr2", Base: "pr1"},
		{Name: "pr3", Base: "refs/heads/main"},
		{Name: "elsewhere", Branch: "feature/elsewhere", Base: "main", Repo: "/other"},
		{Name: "pr4", Base: "elsewhere"},
		{Name: "root", Base: ""},
	}}

	shipped := func(entry StackEntry) (string, bool) {
		base := entry.Base
		if base == "" {
			return "", false
		}
		if parent := GetBranch(stack, entry.Base); parent.Name != "" {
			base = parent.GitBranch()
		}
		return base, true
	}

	for _, entry := range stack.Branches {
		wantBase, wantOK := shipped(entry)
		gotBase, gotOK := checkoutBaseTokenFor(stack, entry)
		if gotBase != wantBase || gotOK != wantOK {
			t.Fatalf("checkoutBaseTokenFor(%q) = (%q, %v), want (%q, %v)", entry.Name, gotBase, gotOK, wantBase, wantOK)
		}
	}

	// The three individually meaningful cells, spelled out.
	if base, ok := checkoutBaseTokenFor(stack, GetBranch(stack, "pr2")); !ok || base != "feature/pr1" {
		t.Fatalf("an in-stack parent must resolve through GitBranch(): got (%q, %v)", base, ok)
	}
	if base, ok := checkoutBaseTokenFor(stack, GetBranch(stack, "pr3")); !ok || base != "refs/heads/main" {
		t.Fatalf("a literal base must stay literal: got (%q, %v)", base, ok)
	}
	if base, ok := checkoutBaseTokenFor(stack, GetBranch(stack, "pr4")); !ok || base != "feature/elsewhere" {
		t.Fatalf("Repo must not be consulted by this rule: got (%q, %v)", base, ok)
	}
	if _, ok := checkoutBaseTokenFor(stack, GetBranch(stack, "root")); ok {
		t.Fatal("an empty base must report ok == false, reproducing the caller's continue")
	}
}

// TestReclaimCheckoutLock_ReusesTheShippedLadder walks the four cells the
// recovery routes legitimately meet: absent, already ours, held by a dead
// PID, and held by a LIVE foreign process. The last one must refuse with the
// byte-identical sentence the shipped ladder has always produced, now also
// available as a typed error so a caller can classify it without string
// matching.
func TestReclaimCheckoutLock_ReusesTheShippedLadder(t *testing.T) {
	assertReparentMatrixBehavior(t, "T-069",
		"checkout-lock-reclaim",
		"workspace-orphan-state-scan",
	)
	featurePath := filepath.Join(t.TempDir(), "features", "feat")
	if err := os.MkdirAll(featurePath, 0o755); err != nil {
		t.Fatal(err)
	}

	func(t *testing.T) {
		writeDeadLock := func(t *testing.T, stateDir, statePath string) []byte {
			t.Helper()
			if err := os.MkdirAll(stateDir, 0o700); err != nil {
				t.Fatal(err)
			}
			data := []byte(fmt.Sprintf(
				"pid: %d\ncreated: \"2026-09-23T00:00:00Z\"\ntoken: old-token\nfeature: old\noperation: sync\nstate_path: %q\n",
				reparentSpawnDeadPID(t), statePath))
			if err := os.WriteFile(CheckoutMutationLockPath(stateDir), data, 0o600); err != nil {
				t.Fatal(err)
			}
			return data
		}
		assertUnchanged := func(t *testing.T, stateDir string, before []byte) {
			t.Helper()
			after, err := os.ReadFile(CheckoutMutationLockPath(stateDir))
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(after, before) {
				t.Fatalf("uncertain owner state allowed lock theft:\n--- before ---\n%s\n--- after ---\n%s", before, after)
			}
		}

		t.Run("symlink owner state", func(t *testing.T) {
			stateDir := t.TempDir()
			target := filepath.Join(stateDir, "real-state.yaml")
			if err := os.WriteFile(target, []byte("state\n"), 0o600); err != nil {
				t.Fatal(err)
			}
			statePath := filepath.Join(stateDir, "owner-state.yaml")
			if err := os.Symlink(target, statePath); err != nil {
				t.Fatal(err)
			}
			before := writeDeadLock(t, stateDir, statePath)
			if _, err := AcquireCheckoutMutationLock(stateDir, "new-token", "new", "sync",
				filepath.Join(stateDir, "new-state.yaml")); err == nil || !strings.Contains(err.Error(), "symbolic link") {
				t.Fatalf("symlink owner state = %v", err)
			}
			assertUnchanged(t, stateDir, before)
		})

		t.Run("owner state I/O error", func(t *testing.T) {
			stateDir := t.TempDir()
			blocker := filepath.Join(stateDir, "not-a-directory")
			if err := os.WriteFile(blocker, []byte("file\n"), 0o600); err != nil {
				t.Fatal(err)
			}
			statePath := filepath.Join(blocker, "state.yaml")
			before := writeDeadLock(t, stateDir, statePath)
			if _, err := AcquireCheckoutMutationLock(stateDir, "new-token", "new", "sync",
				filepath.Join(stateDir, "new-state.yaml")); err == nil {
				t.Fatal("ENOTDIR owner-state probe must refuse")
			}
			assertUnchanged(t, stateDir, before)
		})

		t.Run("owner state permission error", func(t *testing.T) {
			stateDir := t.TempDir()
			statePath := filepath.Join(stateDir, "owner-state.yaml")
			before := writeDeadLock(t, stateDir, statePath)
			previous := checkoutMutationLstat
			checkoutMutationLstat = func(path string) (os.FileInfo, error) {
				if path == statePath {
					return nil, os.ErrPermission
				}
				return os.Lstat(path)
			}
			t.Cleanup(func() { checkoutMutationLstat = previous })
			if _, err := AcquireCheckoutMutationLock(stateDir, "new-token", "new", "sync",
				filepath.Join(stateDir, "new-state.yaml")); err == nil || !errors.Is(err, os.ErrPermission) {
				t.Fatalf("permission owner-state probe = %v", err)
			}
			assertUnchanged(t, stateDir, before)
		})
	}(t)

	t.Run("workspace-global mutation lock", func(t *testing.T) {
		stateDir := t.TempDir()
		syncState := filepath.Join(stateDir, "alpha-checkout-sync.yaml")
		reparentState := filepath.Join(stateDir, "beta-reparent.v1.yaml")
		tokenA := strings.Repeat("a", 32)
		tokenB := strings.Repeat("b", 32)

		if _, err := AcquireCheckoutMutationLock(stateDir, tokenA, "alpha", "sync", syncState); err != nil {
			t.Fatal(err)
		}
		if _, err := AcquireCheckoutMutationLock(stateDir, tokenB, "beta", "reparent", reparentState); err == nil ||
			!strings.Contains(err.Error(), "live sync") {
			t.Fatalf("a second feature must not mutate the physical checkout: %v", err)
		}
		if _, err := ReclaimCheckoutMutationLock(stateDir, tokenB, "beta", "reparent", reparentState); err == nil ||
			!strings.Contains(err.Error(), "foreign sync") {
			t.Fatalf("recovery must not steal another feature's lock: %v", err)
		}
		if err := ReleaseCheckoutMutationLock(stateDir, tokenB); err == nil {
			t.Fatal("a foreign token must not release the workspace lock")
		}
		if err := ReleaseCheckoutMutationLock(stateDir, tokenA); err != nil {
			t.Fatal(err)
		}

		if _, err := AcquireCheckoutMutationLock(stateDir, tokenB, "beta", "reparent", reparentState); err != nil {
			t.Fatalf("the next feature may acquire after release: %v", err)
		}
		if err := ReleaseCheckoutMutationLock(stateDir, tokenB); err != nil {
			t.Fatal(err)
		}
	})

	t.Run("absent global lock scans workspace recovery state", func(t *testing.T) {
		for _, name := range []string{
			"alpha-checkout-sync.yaml",
			"alpha-reparent.v1.yaml",
		} {
			t.Run(name, func(t *testing.T) {
				stateDir := t.TempDir()
				statePath := filepath.Join(stateDir, name)
				stateBytes := []byte("recoverable: true\n")
				if err := os.WriteFile(statePath, stateBytes, 0o600); err != nil {
					t.Fatal(err)
				}
				if _, err := AcquireCheckoutMutationLock(
					stateDir, "beta-token", "beta", "sync",
					filepath.Join(stateDir, "beta-checkout-sync.yaml"),
				); err == nil || !strings.Contains(err.Error(), statePath) {
					t.Fatalf("fresh acquisition with orphan %s = %v", name, err)
				}
				if _, err := os.Lstat(CheckoutMutationLockPath(stateDir)); !os.IsNotExist(err) {
					t.Fatalf("refused fresh acquisition left a global lock: %v", err)
				}
				if after, err := os.ReadFile(statePath); err != nil || !bytes.Equal(after, stateBytes) {
					t.Fatalf("refused fresh acquisition changed %s: %q (%v)", name, after, err)
				}
			})
		}
		t.Run("legacy compatibility directory", func(t *testing.T) {
			stateDir := t.TempDir()
			legacyStateDir := t.TempDir()
			statePath := filepath.Join(legacyStateDir, "alpha-checkout-sync.yaml")
			stateBytes := []byte("recoverable: true\n")
			if err := os.WriteFile(statePath, stateBytes, 0o600); err != nil {
				t.Fatal(err)
			}
			if _, err := AcquireCheckoutMutationLock(
				stateDir, "beta-token", "beta", "reparent",
				filepath.Join(stateDir, "beta-reparent.v1.yaml"), legacyStateDir,
			); err == nil || !strings.Contains(err.Error(), statePath) {
				t.Fatalf("fresh acquisition with legacy-layout orphan = %v", err)
			}
			if _, err := os.Lstat(CheckoutMutationLockPath(stateDir)); !os.IsNotExist(err) {
				t.Fatalf("refused legacy-layout acquisition left a global lock: %v", err)
			}
		})

		t.Run("mixed current and pre-upgrade directories", func(t *testing.T) {
			for _, tc := range []struct {
				name        string
				lockDir     string
				recoverable string
				stateName   string
			}{
				{
					name:        "current lock sees legacy transaction",
					lockDir:     filepath.Join(t.TempDir(), ".tws", "state"),
					recoverable: "legacy",
					stateName:   "alpha-checkout-sync.yaml",
				},
				{
					name:        "legacy lock sees current reparent",
					lockDir:     filepath.Join(t.TempDir(), "state"),
					recoverable: "current",
					stateName:   "alpha-reparent.v1.yaml",
				},
			} {
				t.Run(tc.name, func(t *testing.T) {
					var otherDir string
					if tc.recoverable == "legacy" {
						repoRoot := filepath.Dir(filepath.Dir(tc.lockDir))
						otherDir = filepath.Join(repoRoot, "state")
					} else {
						repoRoot := filepath.Dir(tc.lockDir)
						otherDir = filepath.Join(repoRoot, ".tws", "state")
					}
					if err := os.MkdirAll(otherDir, 0o700); err != nil {
						t.Fatal(err)
					}
					statePath := filepath.Join(otherDir, tc.stateName)
					if err := os.WriteFile(statePath, []byte("recoverable: true\n"), 0o600); err != nil {
						t.Fatal(err)
					}
					owner := filepath.Join(tc.lockDir, "beta-reparent.v1.yaml")
					if _, err := AcquireCheckoutMutationLock(
						tc.lockDir, "beta-token", "beta", "reparent", owner,
					); err == nil || !strings.Contains(err.Error(), statePath) {
						t.Fatalf("mixed-layout recoverable state = %v", err)
					}
					if _, err := os.Lstat(CheckoutMutationLockPath(tc.lockDir)); !os.IsNotExist(err) {
						t.Fatalf("refused mixed-layout acquisition left a global lock: %v", err)
					}
				})
			}
		})
	})

	t.Run("recovery reconstructs only its own reservation", func(t *testing.T) {
		stateDir := t.TempDir()
		ownState := filepath.Join(stateDir, "alpha-reparent.v1.yaml")
		if err := os.WriteFile(ownState, []byte("state\n"), 0o600); err != nil {
			t.Fatal(err)
		}
		token := strings.Repeat("a", 32)
		if _, err := ReclaimCheckoutMutationLock(stateDir, token, "alpha", "reparent", ownState); err != nil {
			t.Fatalf("reconstruct matching reservation: %v", err)
		}
		if err := ReleaseCheckoutMutationLock(stateDir, token); err != nil {
			t.Fatal(err)
		}

		foreignState := filepath.Join(stateDir, "beta-checkout-sync.yaml")
		if err := os.WriteFile(foreignState, []byte("state\n"), 0o600); err != nil {
			t.Fatal(err)
		}
		if _, err := ReclaimCheckoutMutationLock(stateDir, token, "alpha", "reparent", ownState); err == nil ||
			!strings.Contains(err.Error(), foreignState) {
			t.Fatalf("recovery with another feature's state = %v", err)
		}
		if _, err := os.Lstat(CheckoutMutationLockPath(stateDir)); !os.IsNotExist(err) {
			t.Fatalf("refused reconstructed reservation left a global lock: %v", err)
		}
	})
	lockPath := CheckoutLockPath(featurePath)

	// Absent.
	if err := ReclaimCheckoutLock(featurePath); err != nil {
		t.Fatalf("absent lock: %v", err)
	}
	info, err := ReadCheckoutLock(featurePath)
	if err != nil {
		t.Fatal(err)
	}
	if info.PID != os.Getpid() {
		t.Fatalf("lock owner = %d, want this process %d", info.PID, os.Getpid())
	}

	// Already ours.
	if err := ReclaimCheckoutLock(featurePath); err != nil {
		t.Fatalf("own lock: %v", err)
	}

	// Dead foreign PID.
	dead := reparentSpawnDeadPID(t)
	if err := os.WriteFile(lockPath, []byte(fmt.Sprintf("pid: %d\ncreated: \"2020-01-01T00:00:00Z\"\n", dead)), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := ReclaimCheckoutLock(featurePath); err != nil {
		t.Fatalf("dead foreign lock: %v", err)
	}

	// Live foreign PID.
	live := reparentSpawnLivePID(t)
	if err := os.WriteFile(lockPath, []byte(fmt.Sprintf("pid: %d\ncreated: \"2020-01-01T00:00:00Z\"\n", live)), 0o600); err != nil {
		t.Fatal(err)
	}
	err = ReclaimCheckoutLock(featurePath)
	if err == nil {
		t.Fatal("a live foreign lock must never be stolen")
	}
	want := fmt.Sprintf("lock held by live process %d; cannot reclaim", live)
	if err.Error() != want {
		t.Fatalf("message = %q, want the byte-identical shipped sentence %q", err.Error(), want)
	}
	var typed *CheckoutLockLiveError
	if !errors.As(err, &typed) {
		t.Fatal("a live foreign holder must be classifiable without string matching")
	}
	if typed.PID != live {
		t.Fatalf("typed error pid = %d, want %d", typed.PID, live)
	}

	// The lock file itself is untouched by the refusal.
	current, err := os.ReadFile(lockPath)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(current), fmt.Sprintf("pid: %d", live)) {
		t.Fatalf("the live holder's lock was modified: %q", current)
	}

	// forceAcquireCheckoutLock keeps its behaviour and its message: the
	// exported wrapper is the same ladder, not a second one.
	if err := forceAcquireCheckoutLock(featurePath); err == nil || err.Error() != want {
		t.Fatalf("forceAcquireCheckoutLock message = %v, want %q", err, want)
	}
	testReparentCheckoutRecoveryLockTransferCrash(t)
}

