func newModeOpts(dir, featurePath string, policy internal.SyncRunPolicy, changed ...string) internal.CheckoutSyncOpts {
	m := make(map[string]bool, len(changed))
	for _, k := range changed {
		m[k] = true
	}

	return internal.CheckoutSyncOpts{
		Feature:     "test-feature",
		FeaturePath: featurePath,
		RepoDir:     dir,
		Policy:      policy,
		NewMode:     true,
		Changed:     m,
	}
}

func saveCurrentCheckoutRecovery(t *testing.T, dir, featurePath string, tx *internal.CheckoutTransaction) {
	t.Helper()
	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		t.Fatal(err)
	}
	selected := make([]string, 0, len(tx.Plan))
	entryRepos := make(map[string]string, len(tx.Plan))
	inputs := make([]internal.SyncCutoffFreezeInput, 0, len(tx.Plan))
	for i := range tx.Plan {
		row := &tx.Plan[i]
		entry := internal.GetBranch(stack, row.Name)
		if entry.Name == "" {
			t.Fatalf("plan entry %q is absent from stack", row.Name)
		}
		if row.PreSHA == "" {
			row.PreSHA = gitSHA(t, dir, row.Branch)
		}
		if row.LastBaseSHA == "" {
			row.LastBaseSHA = entry.LastBaseSHA
		}
		for j := range stack.Branches {
			if stack.Branches[j].Name == row.Name {
				stack.Branches[j].LastBaseSHA = row.LastBaseSHA
			}
		}
		selected = append(selected, row.Name)
		entryRepos[row.Name] = dir
		inputs = append(inputs, internal.SyncCutoffFreezeInput{
			Entry: row.Name, RepoDir: dir, ParentRef: row.Base,
			ParentSHA: row.NewBaseSHA, Applicable: true,
		})
	}
	if err := internal.SaveStack(featurePath, stack); err != nil {
		t.Fatal(err)
	}
	evidence, err := internal.CaptureSyncTransaction(internal.SyncTransactionBeginInput{
		FeaturePath: featurePath, Feature: tx.Feature, Mode: internal.ModeCheckout,
		WorkspaceRepoRoot: dir, Stack: stack, Selected: selected, EntryRepoDirs: entryRepos,
	})
	if err != nil {
		t.Fatal(err)
	}
	if err := internal.FreezeSyncCutoffs(evidence, stack, inputs, nil); err != nil {
		t.Fatal(err)
	}
	if err := internal.PreflightSyncTransactionBirth(evidence); err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC().Format(time.RFC3339)
	tx.StateVersion = internal.CheckoutTransactionTransactionalVersion
	tx.StartedAt = now
	tx.LockPID = os.Getpid()
	tx.LockCreated = now
	tx.Route = internal.RouteLegacy
	tx.FetchPolicy = string(internal.SyncFetchDisabled)
	tx.PropagationPolicy = string(internal.SyncPropagationFull)
	tx.ScopeKind = string(internal.SyncScopeAll)
	tx.Selected = selected
	tx.ValidationSource = "none"
	tx.Transaction = evidence
	if err := internal.SaveCheckoutTransaction(featurePath, tx); err != nil {
		t.Fatal(err)
	}
	if err := internal.PinSyncTransaction(evidence, func() error {
		return internal.SaveCheckoutTransaction(featurePath, tx)
	}); err != nil {
		t.Fatal(err)
	}
}

func TestReparentCheckoutSyncMutationLockCoversFreshContinueAbort(t *testing.T) {
	reparentCountCLIGitLeaf(t)
	dir, fp := checkoutModeFixture(t)
	opts := newModeOpts(dir, fp, internal.SyncRunPolicy{
		Fetch: internal.SyncFetchDisabled, Propagation: internal.SyncPropagationFull, ScopeKind: internal.SyncScopeAll,
	})
	stateDir := filepath.Join(dir, ".tws", "state")
	seenFresh := false
	internal.StepHook = func(stage internal.CheckoutStage, index int) error {
		if stage == internal.StageRebasing {
			info, _, err := internal.ReadCheckoutMutationLock(stateDir)
			if err != nil || info.Operation != "sync" || info.Feature != opts.Feature {
				t.Fatalf("fresh global lock = %+v (%v)", info, err)
			}
			seenFresh = true
			return fmt.Errorf("pause fresh sync")
		}
		return nil
	}
	if err := internal.RunCheckoutSync(opts); err == nil {
		t.Fatal("fresh sync must pause")
	}
	internal.StepHook = nil
	if !seenFresh {
		t.Fatal("fresh sync never held the workspace-global mutation lock")
	}
	tx, err := internal.LoadCheckoutTransaction(fp)
	if err != nil {
		t.Fatalf("transaction = %+v (%v)", tx, err)
	}
	lock, _, err := internal.ReadCheckoutMutationLock(stateDir)
	if err != nil || lock.Token == "" {
		t.Fatalf("global mutation ownership = %+v (%v)", lock, err)
	}
	mutationToken := lock.Token

	seenContinue := false
	internal.StepHook = func(stage internal.CheckoutStage, index int) error {
		info, _, err := internal.ReadCheckoutMutationLock(stateDir)
		if err == nil && info.Token == mutationToken {
			seenContinue = true
		}
		return nil
	}
	if err := internal.ContinueCheckoutSync(opts); err != nil {
		t.Fatalf("continue: %v", err)
	}
	internal.StepHook = nil
	if !seenContinue {
		t.Fatal("continue did not reclaim the workspace-global mutation lock")
	}
	if _, _, err := internal.ReadCheckoutMutationLock(stateDir); !os.IsNotExist(err) {
		t.Fatalf("successful continue left the global lock: %v", err)
	}

	internal.StepHook = func(stage internal.CheckoutStage, index int) error {
		if stage == internal.StageRebasing {
			return fmt.Errorf("pause for abort")
		}
		return nil
	}
	if err := internal.RunCheckoutSync(opts); err == nil {
		t.Fatal("second sync must pause")
	}
	internal.StepHook = nil
	if err := internal.AbortCheckoutSync(opts); err != nil {
		t.Fatalf("abort: %v", err)
	}
	if _, _, err := internal.ReadCheckoutMutationLock(stateDir); !os.IsNotExist(err) {
		t.Fatalf("abort left the global lock: %v", err)
	}
}

func captureRun(t *testing.T, fn func() error) (string, error) {
	t.Helper()
	var err error
	out := captureStdout(t, func() { err = fn() })
	return out, err
}

func TestCheckoutSyncModes_ScopedPlanExcludesUnselected(t *testing.T) {
	dir, fp := checkoutModeFixture(t)
	bBefore := gitSHA(t, dir, "feat-b")

	// Advance main so feat-root has real work under `full`.
	gitRunCS(t, dir, "checkout", "main")
	writeFileCS(t, dir, "main2.txt", "main2\n")
	gitRunCS(t, dir, "add", ".")
	gitRunCS(t, dir, "commit", "-m", "main advance")

	policy := internal.SyncRunPolicy{Fetch: internal.SyncFetchDisabled, Propagation: internal.SyncPropagationFull, ScopeKind: internal.SyncScopeOne, Selector: "feat-root"}
	out, err := captureRun(t, func() error {
		return internal.RunCheckoutSync(newModeOpts(dir, fp, policy, "only"))
	})
	if err != nil {
		t.Fatalf("scoped checkout sync: %v\n%s", err, out)
	}
	if !strings.Contains(out, "Sync mode: fetch=no-fetch propagation=full scope=only:feat-root") {
		t.Fatalf("missing header:\n%s", out)
