	if !strings.Contains(cycle, "Warning: cycle detected in stack.yaml\n") {
		t.Fatalf("cycle warning missing: %q", cycle)
	}

	if err := os.MkdirAll(filepath.Join(fx.metaRoot, "nostack"), 0o755); err != nil {
		t.Fatal(err)
