		t.Fatalf("an arity error keeps its usage block: %q / %q", usageOut, errOut)
	}
	if !strings.Contains(errOut, "accepts 1 arg(s), received 2") {
		t.Fatalf("the error line must reach the err writer: %q", errOut)
	}
}

