				return nil
			}
			t.Cleanup(func() { internal.SyncTransactionStepHook = nil })
			_, _, exit := runSync(t, "customer", "--full", "--no-fetch")
			if exit == 0 || !reached {
				t.Fatalf("did not retain %s recovery window: exit=%d reached=%v", window, exit, reached)
