func TestSyncGuardedState_Criterion22_29_ContinuationRefusalIsByteIdentical(t *testing.T) {
	t.Run("external_guarded_scoped_arm", func(t *testing.T) {
		f := newScopedFixture(t)
		f.advanceRoot(t)
		f.makeConflict(t)
		if _, _, exit := runSync(t, f.feature, "--only", "child"); exit == 0 {
			t.Fatal("expected a conflict")
		}
		f.detachGuard(t)
		resolveRebase(t, f.wt("child"))

		before := hashArtefacts(t, f.featurePath)
		if _, ok := before["payload"]; !ok {
			t.Fatalf("the scoped fixture must persist a payload, got %v", before)
		}
		if _, ok := before["run_guard"]; !ok {
			t.Fatalf("the scoped fixture must leave its guard behind, got %v", before)
		}
		_, stderr, exit := runSyncExecute(t, f.feature, "--continue", "--max-replay-total", "0")
		if exit != 1 {
			t.Fatalf("the guarded continuation must refuse: exit=%d stderr=%q", exit, stderr)
		}
		assertArtefactsUnchanged(t, "external scoped", before, hashArtefacts(t, f.featurePath))
	})

	t.Run("checkout_guarded_arm", func(t *testing.T) {
		dir, fp := checkoutModeFixture(t)
		writeCheckoutModeMarker(t, dir)
		withUnifiedWorkspaceEnv(t, dir)
		// A conflict-stage guarded transaction whose remaining work exceeds
		// the limit it carries.
		limit := 0
		tx := &internal.CheckoutTransaction{
			StateVersion: internal.CheckoutTransactionGuardedVersion,
			Route:        internal.RouteNewMode,
			Feature:      "test-feature", OriginalBranch: "main", OriginalHEAD: gitSHA(t, dir, "main"),
			Stage: internal.StageSwitched, CurrentIndex: 0,
			MaxReplayTotal: &limit,
			Plan: []internal.CheckoutPlanEntry{
				{Name: "feat-a", Branch: "feat-a", Base: "feat-root",
					NewBaseSHA: gitSHA(t, dir, "feat-root"), LastBaseSHA: gitSHA(t, dir, "main")},
			},
		}
		if err := internal.SaveCheckoutTransaction(fp, tx); err != nil {
			t.Fatal(err)
		}
		t.Cleanup(func() { internal.DeleteCheckoutTransaction(fp) })
		gitRunCS(t, dir, "checkout", "feat-a")

		before := hashArtefacts(t, fp)
		if _, ok := before["transaction"]; !ok {
			t.Fatalf("the checkout fixture must persist a transaction, got %v", before)
		}
		_, stderr, exit := runSyncExecute(t, "test-feature", "--continue")
		if exit != 1 {
			t.Fatalf("the guarded checkout continuation must refuse over its persisted 0: exit=%d stderr=%q", exit, stderr)
		}
		if n := len(planGuardMarkerRe.FindAllString(stderr, -1)); n != 0 ||
			!strings.Contains(stderr, "predates frozen cutoff evidence") {
			t.Fatalf("stderr carried %d plan-guard markers, want marker-free legacy cutoff refusal:\n%s", n, stderr)
		}
		assertArtefactsUnchanged(t, "checkout guarded", before, hashArtefacts(t, fp))
	})
}

package cli

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

type syncResult struct {
	Complete  bool
	Failed    string
	Completed []string
	Err       error
	// Refusal is non-nil exactly when a guarded route's mid-run replay-limit
	// revalidation refused this invocation: the executor prints its marker
	// through planGuardRefusal and never treats it as an ordinary failure.
	Refusal *internal.PlanGuardRefusalError
}

// syncProgressPersistedHook is a test-only crash seam after one observed
// action's primary and selected collateral completions are durable.
var syncProgressPersistedHook func(primary string) error

// syncRunContext carries the frozen decision of a new-mode external run through
// the executor. It is nil on every no-flag run, which is what structurally
// keeps the frozen path frozen.
type syncRunContext struct {
	Policy  internal.SyncRunPolicy
	Sel     internal.SyncSelection
	Payload *internal.SyncRunState

	// Route is "" on every shipped scoped run; a guarded legacy (full-stack)
	// run sets it to internal.RouteLegacy so scoped()/selects()/skipsAnchor()
	// answer exactly as the nil-guard, no-flag path answers today, even
	// though this context is non-nil (it still carries Payload/guard state).
	Route string
	// Validation is the frozen validation identity a guarded run measured at
	// birth (§15). Its zero value (Applies: false) defers to Payload's own
	// TestCommand exactly as before, so an unguarded run observes no change.
	Validation    internal.PlanValidationIdentity
	WorkspaceRoot string
}

func (r *syncRunContext) scoped() bool {
	return r != nil && r.Route != internal.RouteLegacy && r.Policy.ScopeKind != internal.SyncScopeAll
}

func (r *syncRunContext) selects(name string) bool {
	if r == nil || r.Route == internal.RouteLegacy {
		return true
	}
	return r.Sel.Names[name]
}

func (r *syncRunContext) skipsAnchor(name string) bool {
	if r == nil || r.Route == internal.RouteLegacy || r.Policy.Propagation != internal.SyncPropagationLocalOnly {
		return false
	}
	return r.Sel.Role(name) == internal.SyncRoleAnchor
}

// validate runs the run's post-rebase validation. A no-flag run resolves
// today's config on every entry, exactly as it does now. A new-mode run uses
// the command frozen in its payload at start-up — including the empty command,
// which means the run was started with no validation configured and must not
// acquire one mid-run — so a --continue from another shell, or after a config
// edit, can never validate with a different command (§7.7). A guarded run's
// own frozen Validation identity, when present, is the command of record
// instead of Payload.TestCommand, so a guard born with --test never silently
// re-reads config either.
func (r *syncRunContext) validate(layout externalSyncLayout, worktreePath, name string) (bool, error) {
	if r == nil || r.Payload == nil {
		return runValidation(worktreePath, name), nil
	}
	command := r.Payload.TestCommand
	if r.Validation.Applies {
		command = r.Validation.Command
	}
	if command == "" {
		return true, nil
	}
	resume := r.Payload.Stage
	r.Payload.Stage = internal.SyncStageValidating
	if err := internal.SaveSyncRunState(layout.FeaturePath, r.Payload); err != nil {
		return false, fmt.Errorf("record validation intent: %w", err)
	}
	if r.transactional() {
		if err := internal.BeginSyncValidation(r.Payload.Transaction, worktreePath, name, worktreePath, func() error {
			return internal.SaveSyncRunState(layout.FeaturePath, r.Payload)
		}); err != nil {
			return false, err
		}
	}
	ok := runValidationCommand(command, worktreePath, name)
	var commandErr error
	if !ok {
		commandErr = fmt.Errorf("validation command failed")
	}
	if r.transactional() {
		if err := internal.CompleteSyncValidation(r.Payload.Transaction, commandErr, func() error {
			return internal.SaveSyncRunState(layout.FeaturePath, r.Payload)
		}); err != nil {
			return false, err
		}
	}
	if !ok {
		return false, nil
	}
	r.Payload.Stage = resume
	if err := internal.SaveSyncRunState(layout.FeaturePath, r.Payload); err != nil {
		return false, fmt.Errorf("record validation completion: %w", err)
	}
	return true, nil
}

func (r *syncRunContext) transactional() bool {
	return r != nil && r.Payload != nil && r.Payload.Transaction != nil
}

func (r *syncRunContext) save(layout externalSyncLayout) error {
	if r == nil || r.Payload == nil {
		return nil
	}
	return internal.SaveSyncRunState(layout.FeaturePath, r.Payload)
}

func (r *syncRunContext) repoDir(layout externalSyncLayout, entry internal.StackEntry) string {
	if entry.Repo != "" {
		return entry.Repo
	}
	if path := layout.WorktreePath(entry.Name); path != "" {
		if _, err := os.Stat(path); err == nil {
			return path
		}
	}
	return r.WorkspaceRoot
}

func syncWithStackFiltered(feature string, layout externalSyncLayout, stack internal.Stack, sorted []internal.StackEntry, alreadyDone map[string]bool, guard *planGuardRun) syncResult {
	return syncWithStackScoped(feature, layout, stack, sorted, alreadyDone, nil, guard)
}

// syncWithStackScoped is the one executor both the no-flag and every new-mode
// route call. guard is nil on every shipped call site: a nil guard leaves
// every byte and every process this function runs untouched, since both new
// JIT seams below are themselves gated on guard != nil.
func syncWithStackScoped(feature string, layout externalSyncLayout, stack internal.Stack, sorted []internal.StackEntry, alreadyDone map[string]bool, run *syncRunContext, guard *planGuardRun) syncResult {
	if !run.transactional() {
		return syncResult{Err: errors.New("sync recovery predates frozen cutoff evidence; preserve the state and use --abort or inspect it manually — continuation will not guess a replay boundary")}
	}
	updatedByRef := make(map[string]bool)
	completed := completedNames(alreadyDone)
	if alreadyDone == nil {
		alreadyDone = make(map[string]bool)
	}
	needsCutoff := false
	for _, entry := range sorted {
		if !alreadyDone[entry.Name] && run.selects(entry.Name) && !run.skipsAnchor(entry.Name) {
			needsCutoff = true
			break
		}
	}
	if needsCutoff {
		if err := internal.RevalidateSyncCutoffs(run.Payload.Transaction); err != nil {
			return syncResult{Err: err}
		}
	} else if run.Payload.Transaction.CutoffsReady {
		if err := internal.RevalidateSyncCutoffs(run.Payload.Transaction); err != nil {
			return syncResult{Err: err}
		}
	}
	scoped := run.scoped()
	rebased := 0
	anchorsSkipped := 0
	firstRevalidation := true

	if run != nil && run.Payload != nil {
		run.Payload.Stage = internal.SyncStageRebasing
		if err := internal.SaveSyncRunState(layout.FeaturePath, run.Payload); err != nil {
			return syncResult{Err: fmt.Errorf("record rebase stage: %w", err)}
		}
	}

	for _, entry := range sorted {
		if alreadyDone[entry.Name] {
			continue
		}
		if !run.selects(entry.Name) {
			continue
		}
		if run.skipsAnchor(entry.Name) {
			fmt.Println(syncAnchorNoOpLine(entry.Name))
			alreadyDone[entry.Name] = true
			anchorsSkipped++
			continue
		}
		path := layout.WorktreePath(entry.Name)
		if updatedByRef[entry.Name] {
			mode := "active"
			if _, err := os.Stat(path); err != nil {
				mode = "archived"
			}
			fmt.Println(formatSyncStatus(entry.Name, mode, "synced"))
			if !slices.Contains(completed, entry.Name) {
				completed = append(completed, entry.Name)
			}
			alreadyDone[entry.Name] = true
			continue
		}
		if _, err := os.Stat(path); err != nil {
			if internal.IsPrunableWorktree(entry.GitBranch()) {
				fmt.Printf("  [?] %s (missing — run: tws archive %s %s or tws new %s %s)\n", entry.Name, feature, entry.Name, feature, entry.Name)
				return syncFailure(layout, sorted, completed, entry.Name, run)
			}

			rebaseDir := run.repoDir(layout, entry)
			base := resolveEntryBase(stack, entry, rebaseDir)
			currentBaseSHA := internal.GetBranchSHA(rebaseDir, base)
			if currentBaseSHA == "" {
				return syncResult{Err: fmt.Errorf("destination parent %q for %s does not resolve", base, entry.Name)}
			}
			cutoff, cutoffErr := internal.RevalidateSyncCutoffEntry(run.Payload.Transaction, rebaseDir, entry.Name)
			if cutoffErr != nil {
				return syncResult{Err: cutoffErr}
			}

			if guard != nil {
				if rerr := guard.revalidate(entry.Name); rerr != nil {
					return syncGuardFailure(layout, sorted, completed, entry.Name, run, rerr)
				}
			}

			allowed, allowedErr := internal.SyncAllowedRebaseRefs(run.Payload.Transaction, rebaseDir,
				"refs/heads/"+entry.GitBranch(), cutoff.EffectiveSHA, false)
			if allowedErr != nil {
				result := syncFailure(layout, sorted, completed, entry.Name, run)
				result.Err = allowedErr
				return result
			}
			if err := internal.BeginSyncRebaseAction(run.Payload.Transaction, rebaseDir, entry.Name, rebaseDir,
				"refs/heads/"+entry.GitBranch(), allowed, currentBaseSHA, cutoff.EffectiveSHA,
				func() error { return run.save(layout) }); err != nil {
				result := syncFailure(layout, sorted, completed, entry.Name, run)
				result.Err = err
				return result
			}
			if err := internal.PrepareSyncCheckoutContextRestore(run.Payload.Transaction, rebaseDir,
				func() error { return run.save(layout) }); err != nil {
				result := syncFailure(layout, sorted, completed, entry.Name, run)
				result.Err = err
				return result
			}

			rebaseErr := internal.RunSyncRebaseSilent(run.Payload.Transaction, rebaseDir,
				internal.SyncNoUpdateRefsRebaseArgs("--onto", currentBaseSHA, cutoff.EffectiveSHA, entry.GitBranch())...)
			if rebaseErr != nil {
				_ = internal.RunSilentDir(rebaseDir, "git", "rebase", "--abort")
			}
			if err := internal.CompleteSyncGitAction(run.Payload.Transaction, rebaseErr, func() error { return run.save(layout) }); err != nil {
				result := syncFailure(layout, sorted, completed, entry.Name, run)
				result.Err = err
				return result
			}
			if _, _, active := internal.SyncTransactionActiveRebase(run.Payload.Transaction); !active {
				if restoreErr := internal.ResumeSyncForwardRestorations(run.Payload.Transaction,
					func() error { return run.save(layout) }); restoreErr != nil {
					result := syncFailure(layout, sorted, completed, entry.Name, run)
					result.Err = restoreErr
					return result
				}
			}
			if rebaseErr != nil {
				fmt.Println(formatSyncStatus(entry.Name, "archived", "conflict"))
				fmt.Printf("    Restore with: tws new %s %s\n", feature, entry.Name)
				return syncFailure(layout, sorted, completed, entry.Name, run)
			}
			affected, finalizeErr := finalizeExternalSuccessfulAction(layout, &stack, run, entry.Name)
			if finalizeErr != nil {
				result := syncFailure(layout, sorted, completed, entry.Name, run)
				result.Err = finalizeErr
				return result
			}
			fmt.Println(formatSyncStatus(entry.Name, "archived", "synced"))
			for name := range affected {
				if name != entry.Name {
					updatedByRef[name] = true
				}
			}
			completed = appendAffectedCompletion(completed, run.Payload.Selected, affected, entry.Name)
			alreadyDone[entry.Name] = true
			rebased++
			if err := persistExternalSyncProgress(layout.FeaturePath, run.Payload, completed); err != nil {
				return syncResult{Failed: entry.Name, Completed: completed, Err: err}
			}
			if syncProgressPersistedHook != nil {
				if err := syncProgressPersistedHook(entry.Name); err != nil {
					return syncResult{Failed: entry.Name, Completed: completed, Err: err}
				}
			}
			continue
		}

		if issue := checkSyncWorktreeBranch(path, entry); issue != nil {
			fmt.Println(formatSyncStatus(entry.Name, "active", "wrong-branch"))
			fmt.Printf("    %s\n    %s\n", issue.Problem, issue.Hint)
			return syncFailure(layout, sorted, completed, entry.Name, run)
		}

		gitContext := run.repoDir(layout, entry)
		base := resolveEntryBase(stack, entry, gitContext)
		currentBaseSHA := internal.GetBranchSHA(gitContext, base)
		if currentBaseSHA == "" {
			return syncResult{Err: fmt.Errorf("destination parent %q for %s does not resolve", base, entry.Name)}
		}
		cutoff, cutoffErr := internal.RevalidateSyncCutoffEntry(run.Payload.Transaction, gitContext, entry.Name)
		if cutoffErr != nil {
			return syncResult{Err: cutoffErr}
		}
		useUpdateRefs := !scoped && run.Policy.Propagation != internal.SyncPropagationLocalOnly
		rebaseArgs := []string{"rebase", "--update-refs", "--onto", currentBaseSHA, cutoff.EffectiveSHA}
		if !useUpdateRefs {
			// --update-refs rewrites refs outside the selection, which is
			// exactly the unrelated ref movement a scoped run must not cause.
			rebaseArgs = internal.SyncNoUpdateRefsRebaseArgs("--onto", currentBaseSHA, cutoff.EffectiveSHA)
		}

		if guard != nil {
			if firstRevalidation {
				firstRevalidation = false
				if err := syncStepHook(internal.SyncStageRebasing, -1); err != nil {
					return syncFailure(layout, sorted, completed, entry.Name, run)
				}
			}
			if rerr := guard.revalidate(entry.Name); rerr != nil {
				return syncGuardFailure(layout, sorted, completed, entry.Name, run, rerr)
			}
			// §10.5 destination pinning: a guarded execution path passes the
			// planned and JIT-revalidated full SHA in the --onto operand
			// instead of the ref name Git would re-resolve. Only that operand
			// changes; the flag set, the recorded-cutoff operand, the branch
			// operand and the plain-rebase arm are untouched, and no unguarded
			// (golden-covered) invocation can reach this branch.
			rebaseArgs = pinGuardedOnto(rebaseArgs, currentBaseSHA)
		}

		if err := syncStepHook(internal.SyncStageRebasing, rebased); err != nil {
			result := syncFailure(layout, sorted, completed, entry.Name, run)
			result.Err = err
			return result
		}

		if run.transactional() {
			repoDir := run.repoDir(layout, entry)
			allowed, err := internal.SyncAllowedRebaseRefs(run.Payload.Transaction, repoDir,
				"refs/heads/"+entry.GitBranch(), cutoff.EffectiveSHA, useUpdateRefs)
			if err != nil {
				result := syncFailure(layout, sorted, completed, entry.Name, run)
				result.Err = err
				return result
			}
			if err := internal.BeginSyncRebaseAction(run.Payload.Transaction, repoDir, entry.Name, path, "",
				allowed, currentBaseSHA, cutoff.EffectiveSHA, func() error { return run.save(layout) }); err != nil {
				result := syncFailure(layout, sorted, completed, entry.Name, run)
				result.Err = err
				return result
			}
		}

		var rebaseErr error
		if run.transactional() {
			rebaseErr = internal.RunSyncRebaseClean(run.Payload.Transaction, path, rebaseArgs...)
		} else {
			rebaseErr = internal.RunDirClean(path, "git", rebaseArgs...)
		}
		if run.transactional() {
			if err := internal.CompleteSyncGitAction(run.Payload.Transaction, rebaseErr, func() error { return run.save(layout) }); err != nil {
				result := syncFailure(layout, sorted, completed, entry.Name, run)
				result.Err = err
				return result
			}
		}
		if rebaseErr != nil {
			fmt.Println(formatSyncStatus(entry.Name, "active", "conflict"))
			fmt.Printf("    Resolve conflicts in: %s\n", path)
			fmt.Println("    Then run: git add . && git rebase --continue")
			fmt.Printf("    Resume with: tws sync %s --continue\n", feature)
			return syncFailure(layout, sorted, completed, entry.Name, run)
		}
		ok, validationErr := run.validate(layout, path, entry.Name)
		if validationErr != nil {
			result := syncFailure(layout, sorted, completed, entry.Name, run)
			result.Err = validationErr
			return result
		}
		if !ok {
			return syncFailure(layout, sorted, completed, entry.Name, run)
		}

		affected, finalizeErr := finalizeExternalSuccessfulAction(layout, &stack, run, entry.Name)
		if finalizeErr != nil {
			result := syncFailure(layout, sorted, completed, entry.Name, run)
			result.Err = finalizeErr
			return result
		}
		fmt.Println(formatSyncStatus(entry.Name, "active", "synced"))
		for name := range affected {
			if name != entry.Name {
				updatedByRef[name] = true
			}
		}
		completed = appendAffectedCompletion(completed, run.Payload.Selected, affected, entry.Name)
		alreadyDone[entry.Name] = true
		rebased++
		if run != nil && run.Payload != nil {
			if err := persistExternalSyncProgress(layout.FeaturePath, run.Payload, completed); err != nil {
				return syncResult{Failed: entry.Name, Completed: completed, Err: err}
			}
			if syncProgressPersistedHook != nil {
				if err := syncProgressPersistedHook(entry.Name); err != nil {
					return syncResult{Failed: entry.Name, Completed: completed, Err: err}
				}
			}
		}
	}

	var selected map[string]bool
	if scoped {
		selected = run.Sel.Names
	}
	if stale := staleStackEdgesFiltered(layout.WorktreesRoot, stack, selected); len(stale) > 0 {
		fmt.Println("Sync incomplete; stale stack edges remain:")
		for _, edge := range stale {
			fmt.Printf("  [!] %s\n", edge)
		}
		return syncFailure(layout, sorted, completed, "", run)
	}
	if scoped {
		if outside := staleStackEdgesComplement(layout.WorktreesRoot, stack, run.Sel.Names); len(outside) > 0 {
			fmt.Println("Stale stack edges outside this scope (unchanged by this run):")
			for _, edge := range outside {
				fmt.Printf("  [i] %s\n", edge)
			}
		}
	}
	if anchorsSkipped > 0 && rebased == 0 {
		fmt.Println("Nothing to propagate.")
	}
	if run != nil && run.Payload != nil {
		// Teardown is deferred to the caller so the selected push can still
		// record progress in the payload (§8.5 steps 5-7). The stage stays
		// where the executor left it: `finalizing` is recorded by the caller
		// immediately before teardown, never before the push.
		run.Payload.Completed = append([]string(nil), completed...)
		run.Payload.Pending = nil
		run.Payload.FailedBranch = ""
		if err := internal.SaveSyncRunState(layout.FeaturePath, run.Payload); err != nil {
			return syncResult{Completed: completed, Err: fmt.Errorf("persist sync completion: %w", err)}
		}
		return syncResult{Complete: true, Completed: completed}
	}
	_ = clearSyncRunState(layout.FeaturePath, false)
	return syncResult{Complete: true, Completed: completed}
}

func finalizeExternalSuccessfulAction(layout externalSyncLayout, stack *internal.Stack, run *syncRunContext, primary string) (map[string]bool, error) {
	if !run.transactional() {
		return nil, errors.New("successful sync action has no transactional cutoff evidence")
	}
	tx := run.Payload.Transaction
	if len(tx.Actions) == 0 {
		return nil, errors.New("successful sync action has no durable action record")
	}
	action := tx.Actions[len(tx.Actions)-1]
	if action.Entry != primary || action.Kind != "rebase" || action.Status != internal.SyncTxnActionObserved {
		return nil, fmt.Errorf("latest sync action does not verify successful entry %q", primary)
	}

	affected := map[string]bool{primary: true}
	changes := internal.SyncLatestObservedRefChanges(tx)
	for _, change := range changes {
		for _, decision := range tx.Cutoffs {
			if decision.RepoCommonDir == change.RepoCommonDir && decision.ChildRef == change.Ref {
				affected[decision.Entry] = true
			}
		}
	}

	decisions := make(map[string]internal.SyncCutoffDecision, len(tx.Cutoffs))
	for _, decision := range tx.Cutoffs {
		decisions[decision.Entry] = decision
	}
	repos := make(map[string]string, len(tx.Repositories))
	for _, repo := range tx.Repositories {
		repos[repo.CommonDir] = repo.Root
	}
	afterRefs := make(map[string]string, len(action.AfterRefs))
	for _, ref := range action.AfterRefs {
		afterRefs[ref.Ref] = ref.SHA
	}
	parentDestinations := make(map[string]string, len(action.ParentDestinations))
	for _, parent := range action.ParentDestinations {
		parentDestinations[parent.Entry] = parent.DestinationSHA
	}
	for name := range affected {
		decision, ok := decisions[name]
		if !ok || decision.Validity != internal.SyncCutoffValid {
			return nil, fmt.Errorf("successful sync entry %q has no valid frozen cutoff decision", name)
		}
		repoDir := repos[decision.RepoCommonDir]
		if repoDir == "" {
			return nil, fmt.Errorf("successful sync entry %q has no frozen repository", name)
		}
		destination := ""
		if name == primary {
			destination = action.DestinationSHA
		} else if action.ParentDestinationsReady {
			destination = parentDestinations[name]
		} else if decision.ParentEntry != "" {
			parentDecision, parentOK := decisions[decision.ParentEntry]
			if !parentOK {
				return nil, fmt.Errorf("collateral sync entry %q has no frozen parent decision", name)
			}
			destination = afterRefs[parentDecision.ChildRef]
		} else {
			parentRef := decision.ParentRef
			if !strings.HasPrefix(parentRef, "refs/") {
				parentRef = "refs/heads/" + parentRef
			}
			destination = afterRefs[parentRef]
		}
		if destination == "" {
			return nil, fmt.Errorf("successful sync entry %q has no immutable executed destination evidence", name)
		}
		destinationSHA, err := internal.VerifySyncDestinationSHA(repoDir, destination, decision.ChildRef)
		if err != nil {
			return nil, fmt.Errorf("verify destination cutoff for %s: %w", name, err)
		}
		internal.UpdateBaseSHA(stack, name, destinationSHA)
	}
	if err := internal.SyncWriteStackValue(layout.FeaturePath, tx, *stack, func() error {
		return run.save(layout)
	}); err != nil {
		return nil, fmt.Errorf("persist stack metadata: %w", err)
	}
	return affected, nil
}

func persistExternalSyncProgress(featurePath string, payload *internal.SyncRunState, completed []string) error {
	payload.Completed = append([]string(nil), completed...)
	done := make(map[string]bool, len(completed))
	for _, name := range completed {
		done[name] = true
	}
	payload.Pending = payload.Pending[:0]
	for _, name := range payload.Selected {
		if !done[name] {
			payload.Pending = append(payload.Pending, name)
		}
	}
	payload.FailedBranch = ""
	return internal.SaveSyncRunState(featurePath, payload)
}

func appendAffectedCompletion(completed, selected []string, affected map[string]bool, primary string) []string {
	if !slices.Contains(completed, primary) {
		completed = append(completed, primary)
	}
	for _, name := range selected {
		if name != primary && affected[name] && !slices.Contains(completed, name) {
			completed = append(completed, name)
		}
	}
	return completed
}

// syncFailure persists an incomplete run. New-mode runs write the payload only:
// saveIncompleteSync would overwrite the sentinel with a resolvable name and
// hand an old --continue exactly the broad resume the sentinel prevents.
func syncFailure(layout externalSyncLayout, sorted []internal.StackEntry, completed []string, failed string, run *syncRunContext) syncResult {
	if run != nil && run.Payload != nil {
		if err := saveScopedSyncFailure(layout.FeaturePath, run.Payload, failed, completed); err != nil {
			return syncResult{Failed: failed, Completed: completed, Err: fmt.Errorf("persist sync failure: %w", err)}
		}
		return syncResult{Failed: failed, Completed: completed}
	}
	return saveIncompleteSync(layout.FeaturePath, sorted, completed, failed)
}

// syncGuardFailure is syncFailure's guard-refusal twin: a mid-run replay-limit
// revalidation refused entry, so the result carries the *PlanGuardRefusalError
// the executor must hand to planGuardRefusal instead of an ordinary failure
// sentence. State is persisted exactly as syncFailure persists it, since a
// refusal this late still leaves the run resumable at the same failed entry.
func syncGuardFailure(layout externalSyncLayout, sorted []internal.StackEntry, completed []string, failed string, run *syncRunContext, rerr error) syncResult {
	result := syncFailure(layout, sorted, completed, failed, run)
	var refusal *internal.PlanGuardRefusalError
	if errors.As(rerr, &refusal) {
		result.Refusal = refusal
	}
	return result
}

func saveIncompleteSync(featurePath string, sorted []internal.StackEntry, completed []string, failed string) syncResult {
	completedSet := make(map[string]bool, len(completed))
	for _, name := range completed {
		completedSet[name] = true
	}
	pending := make([]string, 0)
	for _, entry := range sorted {
		if entry.Name != failed && !completedSet[entry.Name] {
			pending = append(pending, entry.Name)
		}
	}
	state := internal.NewSyncState()
	state.FailedBranch = failed
	state.Pending = pending
	state.Completed = append([]string(nil), completed...)
	_ = internal.SaveSyncState(featurePath, state)
	return syncResult{Failed: failed, Completed: completed}
}

func completedNames(done map[string]bool) []string {
	var names []string
	for name, ok := range done {
		if ok {
			names = append(names, name)
		}
	}
	return names
}

// staleStackEdgesFiltered is the single completion-gate predicate. A nil
// selection means "the whole stack", which is the frozen full-scope behaviour.
func staleStackEdgesFiltered(worktreesRoot string, stack internal.Stack, selected map[string]bool) []string {
	var stale []string
	for _, child := range stack.Branches {
		if selected != nil && !selected[child.Name] {
			continue
		}
		parent := internal.GetBranch(stack, child.Base)
		if parent.Name == "" || !sameStackRepo(parent.Repo, child.Repo) {
			continue
		}
		childPath := filepath.Join(worktreesRoot, child.Name)
		if _, err := os.Stat(childPath); err != nil {
			continue
		}
		if internal.RunSilentDir(childPath, "git", "merge-base", "--is-ancestor", parent.GitBranch(), child.GitBranch()) != nil {
			stale = append(stale, fmt.Sprintf("%s does not contain parent %s", child.Name, parent.Name))
		}
	}
	return stale
}

// staleStackEdgesComplement reports the stale edges outside the selection. It
// is informational only and never changes the exit code.
func staleStackEdgesComplement(worktreesRoot string, stack internal.Stack, selected map[string]bool) []string {
	complement := make(map[string]bool, len(stack.Branches))
	for _, child := range stack.Branches {
		if !selected[child.Name] {
			complement[child.Name] = true
		}
	}
	if len(complement) == 0 {
		return nil
	}
	return staleStackEdgesFiltered(worktreesRoot, stack, complement)
}

func checkSyncWorktreeBranch(worktreePath string, entry internal.StackEntry) *internal.HealthIssue {
	return internal.CheckWorktreeBranch(worktreePath, entry.GitBranch())
}

func resolveEntryBase(stack internal.Stack, entry internal.StackEntry, repoCtx string) string {
	if parent := internal.GetBranch(stack, entry.Base); parent.Name != "" && sameStackRepo(parent.Repo, entry.Repo) {
		return parent.GitBranch()
	}
	return resolveBase(entry.Base, repoCtx)
}

// resolveBase rewrites a base that names the repository's default branch to its
// remote-tracking form. repoCtx == "" keeps today's cwd-scoped resolution
// exactly; a non-empty repoCtx runs the same resolution inside the repository.
func resolveBase(base, repoCtx string) string {
	var defaultBranch string
	if repoCtx == "" {
		defaultBranch = internal.DefaultBranch()
	} else {
		defaultBranch, _ = internal.DefaultBranchIn(repoCtx)
	}
	if base == defaultBranch {
		return "origin/" + defaultBranch
	}
	return base
}

func formatSyncStatus(name, mode, status string) string {
	symbols := map[string]string{"synced": "+", "failed": "x", "skipped": "-", "conflict": "!", "resolved": "~", "wrong-branch": "?", "validation-failed": "x"}
	sym := symbols[status]
	if sym == "" {
		sym = "?"
	}
	return fmt.Sprintf("  [%s] %s (%s)", sym, name, mode)
}

func syncFallback(layout externalSyncLayout) error {
	entries, err := os.ReadDir(layout.WorktreesRoot)
	if err != nil {
		return fmt.Errorf("read compatibility worktrees: %w", err)
	}
	for _, e := range entries {
		if e.IsDir() {
			path := filepath.Join(layout.WorktreesRoot, e.Name())
			fmt.Printf("Syncing worktree: %s\n", path)
			if err := internal.RunDirClean(path, "git", "rebase", "--update-refs", "origin/main"); err != nil {
				return fmt.Errorf("nontransactional sync failed in %s; earlier worktrees may remain changed: %w", path, err)
			}
		}
	}
	return nil
}

func runValidation(worktreePath, branchName string) bool {
	return runValidationCommand(internal.LoadConfig().TestCommand, worktreePath, branchName)
}

// runValidationCommand runs one already-resolved validation command. An empty
// command means "no validation": it is a real, frozen decision, not a signal to
// go looking for one.
func runValidationCommand(command, worktreePath, branchName string) bool {
	if command == "" {
		return true
	}
	fmt.Printf("    validating %s: %s... ", branchName, command)
	parts := strings.Fields(command)
	if err := internal.RunSilentDir(worktreePath, parts[0], parts[1:]...); err != nil {
		fmt.Println("FAILED")
		fmt.Println(formatSyncStatus(branchName, "active", "validation-failed"))
		return false
	}
	fmt.Println("ok")
	return true
}

// pinGuardedOnto applies §10.5 destination pinning to one already-built rebase
// argv. It rewrites exactly the operand that follows `--onto` — and only when
// the arm really has one and the destination resolved — leaving a plain
// `git rebase [--update-refs] <base>` arm, the recorded-cutoff operand and the
// branch operand exactly as the unguarded twin builds them.
func pinGuardedOnto(argv []string, destinationSHA string) []string {
	if destinationSHA == "" {
		return argv
	}
	for i, tok := range argv {
		if tok != "--onto" || i+1 >= len(argv) {
			continue
		}
		pinned := append([]string(nil), argv...)
		pinned[i+1] = destinationSHA
		return pinned
	}
	return argv
}

package cli

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync/atomic"
	"time"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

// ---------------------------------------------------------------------------
// sync-modes — the package-cli half of the feature (spec §3).
//
// This file owns: flag presence and axis resolution (I1-I8), the one external
// sync layout resolver (§3.11), marker generation (§8.2), the thin classifier
// wrapper that applies I18/deferred I7/I20 and the §8.7 message table, scoped
// failure persistence, the header, and the `--only`/`--from` completion.
// ---------------------------------------------------------------------------

// errSyncModeFlagsNeedV2 is the single I20 literal. It is used verbatim and
// identically by both workspace modes (spec §3.5).
const errSyncModeFlagsNeedV2 = "cannot use sync mode flags on --continue without v2 state; continue without them or abort and start a new run"

// syncTriggerFlags is the new-mode trigger set (spec §3.3), in the source order
// of §3.1. `--push`, `--test`, `--verbose`, `--continue`, and `--abort` are not
// triggers.
var syncTriggerFlags = []string{"fetch", "no-fetch", "full", "local-only", "only", "from"}

// The three shared validation sentences this file owns. They are hoisted to
// package constants, with no byte changed, so a sibling command that tests
// the identical condition reuses the exact sentence instead of re-typing a
// literal that can drift. The `--full` / `--local-only` rows of the I4 table
// stay inline: they are not shared with any other command.
const (
	errMsgFetchNoFetchExclusive = "--fetch and --no-fetch are mutually exclusive"
	errMsgFetchExplicitValue    = "--fetch does not take an explicit value; use --no-fetch to disable automatic fetch"
	errMsgNoFetchExplicitValue  = "--no-fetch does not take an explicit value; use --fetch to enable automatic fetch"
)

// syncPresenceFlags is the closed key set of the presence map.
var syncPresenceFlags = []string{"fetch", "no-fetch", "full", "local-only", "only", "from", "push"}

// resolveSyncPolicy reads the six axis/scope flags plus `--push` through
// cmd.Flags().Changed and produces the frozen decision of one run. It performs
// the pure command-line checks I1-I6, then I7 (only when a trigger flag is
// present), then I8 — in that exact order, and it is called before the mode
// dispatch so both modes reject identically (spec §3.6 step 3).
func resolveSyncPolicy(cmd *cobra.Command, mode internal.WorkspaceMode) (internal.SyncRunPolicy, bool, map[string]bool, error) {
	changed := make(map[string]bool, len(syncPresenceFlags))
	for _, name := range syncPresenceFlags {
		changed[name] = cmd.Flags().Changed(name)
	}

	newMode := false
	for _, name := range syncTriggerFlags {
		if changed[name] {
			newMode = true
			break
		}
	}

	var policy internal.SyncRunPolicy

	// I1-I3 — mutual exclusion.
	if changed["fetch"] && changed["no-fetch"] {
		return policy, newMode, changed, fmt.Errorf("%s", errMsgFetchNoFetchExclusive)
	}
	if changed["full"] && changed["local-only"] {
		return policy, newMode, changed, fmt.Errorf("--full and --local-only are mutually exclusive")
	}
	if changed["only"] && changed["from"] {
		return policy, newMode, changed, fmt.Errorf("--only and --from are mutually exclusive")
	}

	// I4 — axis selectors are presence-only; an explicit false is refused.
	for _, rule := range []struct {
		name string
		msg  string
	}{
		{"fetch", errMsgFetchExplicitValue},
		{"no-fetch", errMsgNoFetchExplicitValue},
		{"full", "--full does not take an explicit value; use --local-only to restrict propagation"},
		{"local-only", "--local-only does not take an explicit value; use --full to advance anchors"},
	} {
		if changed[rule.name] && !syncBoolFlag(cmd, rule.name) {
			return policy, newMode, changed, fmt.Errorf("%s", rule.msg)
		}
	}

	only := syncStringFlag(cmd, "only")
	from := syncStringFlag(cmd, "from")

	// I5/I6 — an explicitly supplied empty selector is refused.
	if changed["only"] && only == "" {
		return policy, newMode, changed, fmt.Errorf("--only requires a stack entry name")
	}
	if changed["from"] && from == "" {
		return policy, newMode, changed, fmt.Errorf("--from requires a stack entry name")
	}

	cont := syncBoolFlag(cmd, "continue")
	abort := syncBoolFlag(cmd, "abort")

	// I7 before I8 (spec §3.5). Without a trigger flag I7 is deferred to the
	// state-discrimination step, where legacy and new-mode state can be told
	// apart.
	if cont && abort && newMode {
		return policy, newMode, changed, errSyncContinueAbort()
	}
	if abort && newMode && !cont {
		return policy, newMode, changed, fmt.Errorf("--abort cannot be combined with %s; abort is defined by the persisted run", syncChangedTriggerList(changed))
	}

	policy.Fetch = internal.SyncFetchEnabled
	if mode == internal.ModeCheckout {
		policy.Fetch = internal.SyncFetchDisabled
	}
	if changed["fetch"] {
		policy.Fetch = internal.SyncFetchEnabled
	}
	if changed["no-fetch"] {
		policy.Fetch = internal.SyncFetchDisabled
	}

	policy.Propagation = internal.SyncPropagationFull
	if changed["local-only"] {
		policy.Propagation = internal.SyncPropagationLocalOnly
	}

	policy.ScopeKind = internal.SyncScopeAll
	switch {
	case changed["only"]:
		policy.ScopeKind = internal.SyncScopeOne
		policy.Selector = only
	case changed["from"]:
		policy.ScopeKind = internal.SyncScopeSubtree
		policy.Selector = from
	}

	return policy, newMode, changed, nil
}

// errSyncContinueAbort is the single I7 literal.
func errSyncContinueAbort() error {
	return fmt.Errorf("--continue and --abort are mutually exclusive")
}

// syncTriggerFlagSupplied answers "did THIS invocation supply any of the six
// mode-trigger flags?" over the one owned `changed` map — the same predicate
// resolveSyncPolicy derives newMode from, extracted so the §12.8b cell-4
// interception can ask it directly. The interception sits ABOVE I20, so it
// composes I20's own sentence itself; syncTriggersNeedV2 keeps no cell-4 arm
// and takes no sentinel view (§13.6 rule 4a, §25.82).
func syncTriggerFlagSupplied(changed map[string]bool) bool {
	for _, name := range syncTriggerFlags {
		if changed[name] {
			return true
		}
	}
	return false
}

// syncChangedTriggerList renders the I8 `%s` operand: the changed trigger flag
// names, sorted, comma-joined, each with the `--` prefix.
func syncChangedTriggerList(changed map[string]bool) string {
	var names []string
	for _, name := range syncTriggerFlags {
		if changed[name] {
			names = append(names, "--"+name)
		}
	}
	sort.Strings(names)
	return strings.Join(names, ", ")
}

func syncBoolFlag(cmd *cobra.Command, name string) bool {
	v, err := cmd.Flags().GetBool(name)
	if err != nil {
		return false
	}
	return v
}

func syncStringFlag(cmd *cobra.Command, name string) string {
	v, err := cmd.Flags().GetString(name)
	if err != nil {
		return ""
	}
	return v
}

// ---------------------------------------------------------------------------
// External sync layout (spec §3.11)
// ---------------------------------------------------------------------------

// externalSyncLayout is the one physical layout of one external sync run.
// Every path the run touches is derived from these two fields and nothing else.
type externalSyncLayout struct {
	FeaturePath   string // <root>/<feature>
	WorktreesRoot string // <root>/<feature>/worktrees
}

// WorktreePath is the only worktree derivation on the external path.
func (l externalSyncLayout) WorktreePath(name string) string {
	return filepath.Join(l.WorktreesRoot, name)
}

// resolveExternalSyncLayout resolves the single root of one external sync run.
//
// It issues no Git command and calls no workspace or root resolver of its own:
// twsRoot is always the value of the caller's own single internal.TwsRoot()
// call. Its only probes are at most two ordinary `<path>/stack.yaml` reads, and
// there are zero of them whenever the two candidates agree.
func resolveExternalSyncLayout(ws internal.Workspace, twsRoot, feature string) (externalSyncLayout, error) {
	b := filepath.Join(twsRoot, feature)
	a, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return externalSyncLayout{}, err
	}
	if filepath.Clean(a) == filepath.Clean(b) {
		return newExternalSyncLayout(a), nil
	}
	if _, loadErr := internal.LoadStack(b); loadErr == nil {
		return newExternalSyncLayout(b), nil
	}
	if _, loadErr := internal.LoadStack(a); loadErr == nil {
		return newExternalSyncLayout(a), nil
	}
	return newExternalSyncLayout(b), nil
}

func newExternalSyncLayout(featurePath string) externalSyncLayout {
	return externalSyncLayout{
		FeaturePath:   featurePath,
		WorktreesRoot: filepath.Join(featurePath, "worktrees"),
	}
}

// ---------------------------------------------------------------------------
// Marker generation (spec §8.2)
// ---------------------------------------------------------------------------

// newSyncMarker generates a per-run sentinel marker. Recognition lives in
// package internal (isSyncMarker); this is the generation half.
func newSyncMarker() (string, error) {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		return "", fmt.Errorf("generate sync marker: %w", err)
	}
	return "tws-scoped-sync-" + hex.EncodeToString(buf) + ".lock", nil
}

// syncMarkerFn is the package-private generation seam. Package-cli tests
// override it; nothing exported ever does.
var syncMarkerFn = newSyncMarker

// newSyncOwnerToken generates the run ownership token recorded in both the
// guard and the payload.
func newSyncOwnerToken() (string, error) {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		return "", fmt.Errorf("generate sync owner token: %w", err)
	}
	return hex.EncodeToString(buf), nil
}

// ExternalSyncMutationGuardHook is a test-only seam after a mutating external
// sync route owns the shared feature guard and before it rechecks authoritative
// reparent state.
var ExternalSyncMutationGuardHook func(featurePath string) error

func externalSyncPostClaimRecheck(feature string, layout externalSyncLayout, token string) error {
	releaseOnError := func(cause error) error {
		if releaseErr := internal.ReleaseOwnedSyncRunGuard(layout.FeaturePath, token); releaseErr != nil {
			return errors.Join(cause, releaseErr)
		}
		return cause
	}
	if ExternalSyncMutationGuardHook != nil {
		if err := ExternalSyncMutationGuardHook(layout.FeaturePath); err != nil {
			return releaseOnError(err)
		}
	}
	if err := internal.RefuseSyncIfReparentActive(externalReparentLocation(feature, layout)); err != nil {
		return releaseOnError(err)
	}
	return nil
}

func acquireExternalSyncMutationGuard(feature string, layout externalSyncLayout, token string, reclaim bool) error {
	var err error
	if reclaim {
		err = internal.ReclaimSyncRunGuard(layout.FeaturePath, token)
	} else {
		err = internal.ClaimSyncRunGuard(layout.FeaturePath, token)
	}
	if err != nil {
		return err
	}
	return externalSyncPostClaimRecheck(feature, layout, token)
}

func withExternalSyncMutationGuard(feature string, layout externalSyncLayout, token string, reclaim bool, mutate func() error) (err error) {
	if token == "" {
		token, err = newSyncOwnerToken()
		if err != nil {
			return err
		}
	}
	if err := acquireExternalSyncMutationGuard(feature, layout, token, reclaim); err != nil {
		return err
	}
	defer func() {
		err = errors.Join(err, internal.ReleaseOwnedSyncRunGuard(layout.FeaturePath, token))
	}()
	return mutate()
}

func verifyFreshExternalSyncAdmission(layout externalSyncLayout, token string) error {
	state := internal.ClassifyExternalSyncState(layout.FeaturePath, internal.SyncClassifyOpts{AlwaysReadGuard: true})
	if state.GuardSymlink || state.GuardErr != nil || state.Guard == nil || state.Guard.Token != token {
		return fmt.Errorf("sync guard changed after claim; refusing to create recovery state")
	}
	if state.Cell != 1 {
		return fmt.Errorf("sync recovery evidence appeared after the mutation guard was claimed; preserve and inspect %s and %s",
			state.LegacyPath, state.PayloadPath)
	}
	return nil
}

func removeOwnedSyncSentinel(featurePath, marker string) error {
	state, err := internal.LoadSyncState(featurePath)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil || state == nil || state.FailedBranch != marker {
		return fmt.Errorf("sync sentinel changed during setup; preserve and inspect %s", internal.SyncStatePath(featurePath))
	}
	return internal.RemoveSyncState(featurePath)
}

func loadAuthoritativeExternalRecovery(layout externalSyncLayout, expected *internal.SyncRunState, requireSentinel bool) (*internal.SyncRunState, error) {
	if expected == nil {
		return nil, errors.New("transactional sync recovery payload is absent")
	}
	fresh, err := internal.LoadSyncRunState(layout.FeaturePath)
	if err != nil {
		return nil, fmt.Errorf("reload authoritative sync recovery payload: %w", err)
	}
	if fresh.OwnerToken != expected.OwnerToken || fresh.Marker != expected.Marker ||
		fresh.Feature != expected.Feature || fresh.StateVersion != expected.StateVersion {
		return nil, errors.New("sync recovery payload changed identity while its guard was being reclaimed; preserve all evidence and inspect it manually")
	}
	expectedRunID, freshRunID := "", ""
	if expected.Transaction != nil {
		expectedRunID = expected.Transaction.RunID
	}
	if fresh.Transaction != nil {
		freshRunID = fresh.Transaction.RunID
	}
	if expectedRunID != freshRunID {
		return nil, errors.New("sync recovery transaction changed identity while its guard was being reclaimed; preserve all evidence and inspect it manually")
	}
	var sentinel *internal.SyncState
	if fresh.Transaction != nil {
		sentinel, err = internal.LoadTransactionalSyncSentinel(layout.FeaturePath)
	} else {
		sentinel, err = internal.LoadSyncState(layout.FeaturePath)
	}
	if !requireSentinel && errors.Is(err, os.ErrNotExist) {
		if fresh.Transaction != nil && !internal.SyncTransactionCleanupOnly(fresh.Transaction) {
			if err := internal.RestoreTransactionalSyncSentinel(layout.FeaturePath, fresh); err != nil {
				return nil, err
			}
		}
		return fresh, nil
	}
	if err != nil || sentinel == nil || sentinel.FailedBranch != fresh.Marker {
		return nil, fmt.Errorf("sync recovery sentinel no longer matches payload marker %q; preserve and inspect %s and %s",
			fresh.Marker, internal.SyncStatePath(layout.FeaturePath), internal.SyncRunStatePath(layout.FeaturePath))
	}
	return fresh, nil
}

// syncMarkerCollision is the mandatory I17 pre-flight: the generated marker may
// equal neither a StackEntry.Name nor an entry.GitBranch().
func syncMarkerCollision(stack internal.Stack, marker string) error {
	for _, entry := range stack.Branches {
		if entry.Name == marker || entry.GitBranch() == marker {
			return fmt.Errorf("refusing to start: generated sync marker %q collides with stack entry %q; re-run", marker, entry.Name)
		}
	}
	return nil
}

// ---------------------------------------------------------------------------
// State discrimination (spec §3.6 steps 7-9, §8.6, §8.7)
// ---------------------------------------------------------------------------

type syncVerb string

const (
	syncVerbPlain    syncVerb = "plain"
	syncVerbContinue syncVerb = "continue"
	syncVerbAbort    syncVerb = "abort"
)

// classifySyncState is the thin wrapper over internal.ClassifyExternalSyncState.
// It passes AlwaysReadGuard: newMode and the package default liveness
// predicate, and it applies the I18 symlink refusals from the recorded facts —
// never a second Lstat.
func classifySyncState(featurePath string, newMode bool) (internal.SyncExternalState, error) {
	st := internal.ClassifyExternalSyncState(featurePath, internal.SyncClassifyOpts{AlwaysReadGuard: newMode})
	if err := syncSymlinkRefusal(st, newMode); err != nil {
		return st, err
	}
	return st, nil
}

// syncSymlinkRefusal applies I18 over the classifier's recorded symlink facts.
func syncSymlinkRefusal(st internal.SyncExternalState, newMode bool) error {
	handlingV2 := st.Marker != "" || st.Payload != nil || st.PayloadErr != nil || st.HasGuardFile()
	if st.LegacySymlink && (newMode || handlingV2) {
		return syncSymlinkError(st.LegacyPath)
	}
	if st.PayloadSymlink {
		return syncSymlinkError(st.PayloadPath)
	}
	if st.GuardSymlink {
		return syncSymlinkError(st.GuardPath)
	}
	return nil
}

// syncStateSymlinkOnly reports whether err is exactly the I18 symlink
// refusal — the one classifier error the plan route describes instead of
// propagating (§12.5, §22.13m (i)).
func syncStateSymlinkOnly(err error) bool {
	return err != nil && strings.Contains(err.Error(), "runtime state path is a symlink")
}

func syncSymlinkError(path string) error {
	return fmt.Errorf("refusing to use %s: runtime state path is a symlink", path)
}

// syncCellLiveGuardRefusal is the pure extraction of syncCellRefusal's own
// first switch: the guard-precedence check applied on top of cells 2, 4, and
// 5, independent of each cell's own message. It is called both by
// syncCellRefusal, as its own first statement, and by the cell-4 guarded-
// sentinel interception (sync.go), which must apply the identical
// live-guard precedence before it ever consults the sentinel.
func syncCellLiveGuardRefusal(feature string, st internal.SyncExternalState, verb syncVerb) error {
	switch st.Cell {
	case 2, 4, 5:
		if st.GuardLive && st.Guard != nil {
			if st.Payload != nil && st.Payload.Transaction != nil {
				tx := st.Payload.Transaction
				validatorEntry, validatorMutated := internal.SyncTransactionValidatorMutated(tx)
				recovery := ""
				switch {
				case validatorMutated:
					recovery = fmt.Sprintf("validator changed refs or checkout state while validating %s; preserve the sync journal and working tree and recover manually", validatorEntry)
				case internal.SyncTransactionCleanupOnly(tx):
					recovery = fmt.Sprintf("only cleanup remains; run: tws sync %s --continue (no completed work will be rolled back)", feature)
				case internal.SyncTransactionPublished(tx):
					recovery = fmt.Sprintf("publication has started and local rollback is disabled; run: tws sync %s --continue", feature)
				case internal.SyncTransactionRollingBack(tx):
					recovery = fmt.Sprintf("rollback has started and forward continuation is disabled; run: tws sync %s --abort", feature)
				}
				if recovery != "" {
					return fmt.Errorf("a scoped sync is running for %q (pid %d); wait for it to exit; %s", feature, st.Guard.PID, recovery)
				}
			}
			if verb == syncVerbAbort {
				return fmt.Errorf("a scoped sync is running for %q (pid %d); wait for it to exit before --abort", feature, st.Guard.PID)
			}
			return fmt.Errorf("a scoped sync is already running for %q (pid %d, started %s); wait for it or use --continue/--abort after it exits", feature, st.Guard.PID, st.Guard.Created)
		}
	}
	return nil
}

// syncCellRefusal returns the §8.7 message for a cell/verb pair, or nil when
// the verb may proceed in that cell. Guard precedence is applied on top of the
// cell for rows 2, 4, and 5 only.
func syncCellRefusal(verb syncVerb, feature string, layout externalSyncLayout, st internal.SyncExternalState) error {
	if err := syncCellLiveGuardRefusal(feature, st, verb); err != nil {
		return err
	}

	switch st.Cell {
	case 1, 7:
		return nil
	case 2:
		if st.Payload != nil && st.Payload.Transaction != nil {
			tx := st.Payload.Transaction
			_, mutated := internal.SyncTransactionValidatorMutated(tx)
			if verb == syncVerbPlain || mutated ||
				verb == syncVerbContinue && internal.SyncTransactionRollingBack(tx) ||
				verb == syncVerbAbort && internal.SyncTransactionPublished(tx) && !internal.SyncTransactionCleanupOnly(tx) {
				if err := transactionalSyncRecoveryRefusal(feature, tx); err != nil {
					return err
				}
				return fmt.Errorf("a transactional sync record survives without its compatibility marker for %q; preserve the evidence and run: tws sync %s --continue or --abort", feature, feature)
			}
			return nil
		}
		if verb == syncVerbAbort {
			return nil
		}
		failed := syncPayloadFailed(st)
		return fmt.Errorf("a scoped sync record survives without its state file for %q: it failed on %s (worktree %s) and that rebase was never aborted. Resolve or abort it there, then run: tws sync %s --abort",
			feature, failed, layout.WorktreePath(failed), feature)
	case 4:
		if verb == syncVerbAbort {
			return nil
		}
		return fmt.Errorf("a scoped sync left partial state for %q: it was interrupted either while starting up or while finishing, and this cannot be distinguished on disk; work may or may not have been done. Inspect the worktrees, then run: tws sync %s --abort",
			feature, feature)
	case 5:
		if verb == syncVerbPlain {
			if st.Payload != nil && st.Payload.Transaction != nil {
				if err := transactionalSyncRecoveryRefusal(feature, st.Payload.Transaction); err != nil {
					return err
				}
			}
			return fmt.Errorf("a scoped sync is incomplete (failed on: %s); use --continue or --abort", syncPayloadFailed(st))
		}
		return nil
	case 3, 6, 9, 12:
		return fmt.Errorf("scoped sync state at %s is unreadable or uses an unsupported version (%s); preserve and inspect it — do not delete it or run recovery blindly",
			st.PayloadPath, syncErrText(st.PayloadErr))
	case 8:
		legacyFailed := ""
		if st.Legacy != nil {
			legacyFailed = st.Legacy.FailedBranch
		}
		if verb == syncVerbAbort {
			return fmt.Errorf("refusing to clear two unfinished syncs at once for %q: a legacy sync failed on %s and a scoped sync failed on %s; preserve and inspect %s and %s for manual recovery",
				feature, legacyFailed, syncPayloadFailed(st), st.LegacyPath, st.PayloadPath)
		}
		return fmt.Errorf("two unfinished syncs are recorded for %q: a legacy sync failed on %s and a scoped sync failed on %s; preserve and inspect both before manual recovery (%s and %s)",
			feature, legacyFailed, syncPayloadFailed(st), st.LegacyPath, st.PayloadPath)
	case 10:
		return fmt.Errorf("sync state at %s is unreadable: %v; preserve and inspect it — tws will not guess whether recovery is safe", st.LegacyPath, syncErrText(st.LegacyErr))
	case 11:
		failed := syncPayloadFailed(st)
		if verb == syncVerbAbort {
			return fmt.Errorf("refusing to clear unreadable sync state at %s while a scoped sync record beside it is still unfinished: it failed on %s (worktree %s); preserve and inspect both, including %s",
				st.LegacyPath, failed, layout.WorktreePath(failed), st.PayloadPath)
		}
		return fmt.Errorf("sync state at %s is unreadable, and a scoped sync record beside it failed on %s (worktree %s); preserve and inspect both, including %s — tws will not guess",
			st.LegacyPath, failed, layout.WorktreePath(failed), st.PayloadPath)
	}
	return nil
}

func transactionalSyncRecoveryRefusal(feature string, tx *internal.SyncTransaction) error {
	validatorEntry, validatorMutated := internal.SyncTransactionValidatorMutated(tx)
	switch {
	case validatorMutated:
		return fmt.Errorf("a transactional sync validator changed refs or checkout state while validating %s; preserve the sync journal and working tree and recover manually", validatorEntry)
	case internal.SyncTransactionCleanupOnly(tx):
		return fmt.Errorf("a transactional sync has only cleanup remaining; run: tws sync %s --continue or --abort (neither will roll back completed work)", feature)
	case internal.SyncTransactionPublished(tx):
		return fmt.Errorf("a transactional sync has crossed the publication boundary; local rollback is disabled — run: tws sync %s --continue", feature)
	case internal.SyncTransactionRollingBack(tx):
		return fmt.Errorf("a transactional sync rollback is in progress; forward continuation is disabled — run: tws sync %s --abort", feature)
	default:
		return nil
	}
}

func syncPayloadFailed(st internal.SyncExternalState) string {
	if st.Payload == nil {
		return ""
	}
	return st.Payload.FailedBranch
}

func syncErrText(err error) string {
	if err == nil {
		return "unknown"
	}
	return err.Error()
}

// syncTriggersNeedV2 is I20's cell-aware predicate (spec §3.5): a resumable
// cell whose subject cannot satisfy a --continue that also supplies a
// sync-mode trigger flag. Cell 1/7 (no v2 state at all, or a real legacy-only
// state) always need v2; cell 5 needs it exactly when the persisted payload
// is not itself a new-mode run. The caller retains its own `newMode &&`
// prefix, exactly mirroring internal.CheckoutTriggersNeedV2's own external
// `opts.NewMode &&` wrapping. This predicate is never reached on cell 4: the
// guarded-sentinel interception fully owns that cell's own flag-conflict
// check before I20 is ever consulted.
func syncTriggersNeedV2(state internal.SyncExternalState) bool {
	switch state.Cell {
	case 1, 7:
		return true
	case 2:
		return state.Payload != nil && state.Payload.Transaction != nil && !internal.PayloadNewMode(state.Payload)
	case 5:
		return !internal.PayloadNewMode(state.Payload)
	default:
		return false
	}
}

// syncStateRefusesContinueAbort is the pure extraction of the deferred-I7
// state predicate: a --continue --abort invocation that supplied no trigger
// flag is refused whenever the subject carries any new-mode-recognizable
// state at all — a marker or a payload — exactly as today. The caller
// retains its own `cont && abort &&` prefix.
func syncStateRefusesContinueAbort(state internal.SyncExternalState) bool {
	return state.Marker != "" || state.Payload != nil
}

// ---------------------------------------------------------------------------
// New-mode setup, teardown, and failure persistence (spec §8.5)
// ---------------------------------------------------------------------------

// syncRunStateBirth carries the guarded envelope's birth-time overrides for
// setupSyncRunState (§13.1, §13.6 rule 2). Its zero value changes nothing —
// every shipped (unguarded) call site passes it unchanged and the payload it
// produces is byte-identical to today's. StateVersion is applied only when
// non-zero: the birth decision of §13.6 rule 2 is made once by the caller,
// exactly as SaveSyncRunState's own doc comment requires, and is never
// silently defaulted here. Route/MaxPerEntry/MaxTotal are applied
// unconditionally, because their own Go zero values ("" and nil) are already
// what NewSyncRunState leaves them at, so an unguarded caller's zero-value
// birth is a true no-op for those three fields too.
type syncRunStateBirth struct {
	StateVersion int
	Route        string
	MaxPerEntry  *int
	MaxTotal     *int
}

// setupSyncRunState performs §8.5 setup: guard, sentinel, payload — in that
// exact order, and it is the run's first side effect.
func setupSyncRunState(layout externalSyncLayout, feature, marker, token string, sel internal.SyncSelection, push bool, testCommand, validationSource string, birth syncRunStateBirth) (*internal.SyncRunState, error) {
	if err := internal.ClaimSyncRunGuard(layout.FeaturePath, token); err != nil {
		return nil, err
	}
	if err := externalSyncPostClaimRecheck(feature, layout, token); err != nil {
		return nil, err
	}
	if err := syncStepHook(internal.SyncStageInitializing, 0); err != nil {
		return nil, err
	}

	sentinel := internal.NewSyncState()
	sentinel.FailedBranch = marker
	sentinel.Pending = []string{}
	sentinel.Completed = []string{}
	sentinel.Skipped = []string{}
	if err := internal.SaveSyncState(layout.FeaturePath, sentinel); err != nil {
		internal.ReleaseSyncRunGuard(layout.FeaturePath)
		return nil, fmt.Errorf("write sync sentinel: %w", err)
	}
	if err := syncStepHook(internal.SyncStageInitializing, 1); err != nil {
		return nil, err
	}

	payload := internal.NewSyncRunState(feature, marker, token, sel.Policy)
	payload.Selected = sel.SelectedNames()
	payload.Pending = append([]string(nil), payload.Selected...)
	payload.Push = push
	payload.TestCommand = testCommand
	payload.ValidationSource = validationSource
	payload.Repos = append([]string(nil), sel.Repos...)
	if birth.StateVersion != 0 {
		payload.StateVersion = birth.StateVersion
	}
	payload.Route = birth.Route
	payload.MaxReplayPerEntry = birth.MaxPerEntry
	payload.MaxReplayTotal = birth.MaxTotal
	if err := internal.SaveSyncRunState(layout.FeaturePath, payload); err != nil {
		internal.DeleteSyncState(layout.FeaturePath)
		internal.ReleaseSyncRunGuard(layout.FeaturePath)
		return nil, fmt.Errorf("write scoped sync state: %w", err)
	}
	if err := syncStepHook(internal.SyncStageInitializing, 2); err != nil {
		return nil, err
	}
	return payload, nil
}

func setupTransactionalSyncRunState(layout externalSyncLayout, ws internal.Workspace, feature, marker, token string, stack internal.Stack, sel internal.SyncSelection, push bool, testCommand, validationSource, route string, guarded bool, maxPerEntry, maxTotal *int) (*internal.SyncRunState, error) {
	if err := internal.ClaimSyncRunGuard(layout.FeaturePath, token); err != nil {
		return nil, err
	}
	if err := externalSyncPostClaimRecheck(feature, layout, token); err != nil {
		return nil, err
	}
	if err := verifyFreshExternalSyncAdmission(layout, token); err != nil {
		return nil, errors.Join(err, internal.ReleaseOwnedSyncRunGuard(layout.FeaturePath, token))
	}
	sentinelOwned := false
	cleanupSetup := func(cause error) error {
		var sentinelErr error
		if sentinelOwned {
			sentinelErr = removeOwnedSyncSentinel(layout.FeaturePath, marker)
		}
		return errors.Join(cause, sentinelErr, internal.ReleaseOwnedSyncRunGuard(layout.FeaturePath, token))
	}
	if err := syncStepHook(internal.SyncStageInitializing, 0); err != nil {
		return nil, err
	}

	sentinel := internal.NewSyncState()
	sentinel.FailedBranch = marker
	sentinel.Pending = []string{}
	sentinel.Completed = []string{}
	sentinel.Skipped = []string{}
	if err := internal.SaveSyncState(layout.FeaturePath, sentinel); err != nil {
		return nil, cleanupSetup(fmt.Errorf("write sync sentinel: %w", err))
	}
	sentinelOwned = true
	if err := syncStepHook(internal.SyncStageInitializing, 1); err != nil {
		return nil, err
	}

	entryRepos := make(map[string]string, len(sel.Entries))
	for _, selected := range sel.Entries {
		entry := internal.GetBranch(stack, selected.Name)
		ctx := entry.Repo
		if ctx == "" {
			if path := layout.WorktreePath(entry.Name); path != "" {
				if _, statErr := os.Stat(path); statErr == nil {
					ctx = path
				}
			}
		}
		if ctx == "" {
			ctx = ws.RepoRoot
		}
		entryRepos[entry.Name] = ctx
	}
	tx, err := internal.CaptureSyncTransaction(internal.SyncTransactionBeginInput{
		FeaturePath: layout.FeaturePath, Feature: feature, Mode: internal.ModeExternal,
		WorkspaceRepoRoot: ws.RepoRoot, Stack: stack, Selected: sel.SelectedNames(), EntryRepoDirs: entryRepos,
	})
	if err != nil {
		return nil, cleanupSetup(fmt.Errorf("capture sync rollback preimage: %w", err))
	}
	if err := internal.PreflightSyncTransactionBirth(tx); err != nil {
		return nil, cleanupSetup(fmt.Errorf("preflight sync rollback holders: %w", err))
	}
	if sel.Policy.Fetch == internal.SyncFetchDisabled || guarded {
		cutoffRun := &syncRunContext{Policy: sel.Policy, Sel: sel, WorkspaceRoot: ws.RepoRoot}
		inputs, inputErr := externalSyncCutoffInputs(layout, stack, cutoffRun)
		if inputErr != nil {
			return nil, cleanupSetup(inputErr)
		}
		if freezeErr := internal.FreezeSyncCutoffs(tx, stack, inputs, nil); freezeErr != nil {
			return nil, cleanupSetup(freezeErr)
		}
	}

	payload := internal.NewSyncRunState(feature, marker, token, sel.Policy)
	payload.StateVersion = internal.SyncRunStateTransactionalVersion
	if guarded {
		payload.StateVersion = internal.SyncRunStateTransactionalGuardedVersion
		payload.PlanGuarded = true
	}
	payload.Route = route
	payload.MaxReplayPerEntry = maxPerEntry
	payload.MaxReplayTotal = maxTotal
	payload.Selected = sel.SelectedNames()
	payload.Pending = append([]string(nil), payload.Selected...)
	payload.Push = push
	payload.TestCommand = testCommand
	payload.ValidationSource = validationSource
	payload.Repos = append([]string(nil), sel.Repos...)
	payload.Transaction = tx
	if err := internal.SaveSyncRunState(layout.FeaturePath, payload); err != nil {
		return nil, cleanupSetup(fmt.Errorf("write transactional sync state: %w", err))
	}
	if err := syncStepHook(internal.SyncStageInitializing, 2); err != nil {
		return nil, err
	}
	savePayload := func() error {
		return internal.SaveSyncRunState(layout.FeaturePath, payload)
	}
	if err := internal.PinSyncTransactionPreimages(tx, savePayload); err != nil {
		return nil, err
	}
	if tx.CutoffsReady {
		if err := internal.FinalizeSyncTransactionSnapshot(tx, savePayload); err != nil {
			return nil, err
		}
	}
	return payload, nil
}

// clearSyncRunState performs §8.5 teardown in the exact reverse order:
// payload, sentinel, guard. A no-flag run keeps today's literal sentinel-free
// DeleteSyncState and can never fail.
//
// A new-mode teardown stops at the first failing step hook and returns that
// error, so an interruption between two teardown steps leaves exactly the
// residue that step ordering implies: {sentinel, guard} after step 0 and
// {guard} after step 1. Callers must propagate the error and must not clear
// any later artifact themselves.
func clearSyncRunState(featurePath string, newMode bool) error {
	if !newMode {
		return internal.RemoveSyncState(featurePath)
	}
	if err := internal.RemoveSyncRunState(featurePath); err != nil {
		return err
	}
	if err := syncStepHook(internal.SyncStageFinalizing, 0); err != nil {
		return err
	}
	if err := internal.RemoveSyncState(featurePath); err != nil {
		return err
	}
	if err := syncStepHook(internal.SyncStageFinalizing, 1); err != nil {
		return err
	}
	return internal.RemoveSyncRunGuard(featurePath)
}

// ---------------------------------------------------------------------------
// Guarded-legacy setup, teardown, and upgrade (spec §12, §13.7a)
// ---------------------------------------------------------------------------

// guardedLegacyCarry is the continuation-only provenance a cell-7 guarded
// legacy setup must not lose (§13.6 rule 2a): the prior legacy state's
// Completed list verbatim in its persisted order, its FailedBranch, and its
// persisted pending COUNT — the number the shipped resume prose prints. The
// zero value is the fresh route, which carries nothing. The prior document's
// BYTES are deliberately absent: §13.2a step 1 makes the capture
// setupGuardedLegacyRunState's own responsibility, so no caller can hand it
// a stale or re-marshalled snapshot of a file the setup is about to replace.
type guardedLegacyCarry struct {
	Completed         []string
	FailedBranch      string
	PriorPendingCount int
}

// carriedGuardedLegacyState projects an already-loaded legacy state into the
// carry the cell-7 continuation arm supplies. It reads no file: the caller
// has already decoded the state for its own gates, and the bytes the
// rollback needs are captured by the setup itself.
func carriedGuardedLegacyState(legacy *internal.SyncState) guardedLegacyCarry {
	if legacy == nil {
		return guardedLegacyCarry{}
	}
	return guardedLegacyCarry{
		Completed:         append([]string(nil), legacy.Completed...),
		FailedBranch:      legacy.FailedBranch,
		PriorPendingCount: len(legacy.Pending),
	}
}

// captureGuardedLegacySyncState is §13.2a step 1: one os.ReadFile of
// .sync-state.yaml into the bytes the rollback will restore. The bytes the
// classifier already decoded are NOT reused — restoration needs the file's
// bytes, not a re-marshalled struct. fs.ErrNotExist is the FRESH cell and
// yields (nil, nil); every other error is returned wrapped, marker-free, so
// the arm refuses before it has written or claimed anything.
func captureGuardedLegacySyncState(featurePath string) ([]byte, error) {
	data, err := os.ReadFile(internal.SyncStatePath(featurePath))
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read sync state: %w", err)
	}
	return data, nil
}

// guardedLegacySetupProgress records exactly what setupGuardedLegacyRunState
// created, so the rollback undoes what happened rather than what it assumes
// from a step index (§13.2a).
type guardedLegacySetupProgress struct {
	Guard    bool // step 2 claimed the run guard
	Sentinel bool // step 3 installed the backup sentinel
	Payload  bool // step 4 wrote the v3 payload
}

// guardedLegacySetupPending computes a guarded legacy sentinel's and
// payload's initial pending set: every entry of universe on a fresh run, or
// every entry of universe not already in carry.Completed on a cell-7
// upgrade — the carried FailedBranch is deliberately NOT excluded, since its
// own rebase is not yet known-good at the moment of the upgrade.
func guardedLegacySetupPending(universe []string, carry guardedLegacyCarry) []string {
	done := make(map[string]bool, len(carry.Completed))
	for _, name := range carry.Completed {
		done[name] = true
	}
	pending := make([]string, 0, len(universe))
	for _, name := range universe {
		if !done[name] {
			pending = append(pending, name)
		}
	}
	return pending
}

// newGuardedLegacySentinel assembles the one document §13.2a step 3 writes.
// The embedded SyncState carries the marker exactly as an unguarded sentinel
// does, so InspectGuardedLegacySentinel's own marker-shape check passes
// identically; the guarded envelope fields record this invocation's own
// identity, limits, and validation provenance, plus — on an upgrade — the
// captured prior document byte-for-byte with its SHA-256, which is what
// makes every crash window of §13.2a recoverable.
func newGuardedLegacySentinel(feature, marker, token string, universe, pending []string, birth syncRunStateBirth, push bool, testCommand, validationSource string, carry guardedLegacyCarry, prior []byte) *internal.GuardedLegacySentinel {
	s := &internal.GuardedLegacySentinel{
		SyncState:           *internal.NewSyncState(),
		GuardedStateVersion: internal.GuardedLegacySentinelVersion,
		Route:               internal.RouteLegacy,
		Feature:             feature,
		Marker:              marker,
		OwnerToken:          token,
		CreatedAt:           time.Now().UTC().Format(time.RFC3339),
		WriterPID:           os.Getpid(),
		MaxReplayPerEntry:   birth.MaxPerEntry,
		MaxReplayTotal:      birth.MaxTotal,
		Push:                push,
		TestCommand:         testCommand,
		ValidationSource:    validationSource,
		Universe:            append([]string(nil), universe...),
		PendingIntent:       append([]string(nil), pending...),
		CarriedCompleted:    append([]string(nil), carry.Completed...),
		CarriedFailed:       carry.FailedBranch,
		PriorPendingCount:   carry.PriorPendingCount,
		PriorLegacyPresent:  len(prior) > 0,
	}
	s.FailedBranch = marker
	s.Pending = []string{}
	s.Completed = []string{}
	s.Skipped = []string{}
	if len(prior) > 0 {
		sum := sha256.Sum256(prior)
		s.PriorLegacySHA256 = hex.EncodeToString(sum[:])
		s.PriorLegacyBase64 = base64.StdEncoding.EncodeToString(prior)
	}
	return s
}

// newGuardedLegacyPayload assembles the state_version: 3, route: legacy
// envelope §13.2a step 4 writes. Its policy members are the legacy route's
// own defaults — a legacy run has no sync-mode policy of its own — and its
// resume-bearing members are the four carried values of §13.2a: Selected is
// the full-stack legacy universe in this invocation's one TopoSort order,
// Pending the remaining set of §13.3 in that order, Completed the legacy
// state's Completed verbatim and FailedBranch its FailedBranch verbatim. The
// legacy state's Skipped list has no payload counterpart and is deliberately
// not carried: the shipped resume builds `done` from Completed ∪
// {FailedBranch} alone, and the list nevertheless survives verbatim inside
// the sentinel's byte-exact backup.
func newGuardedLegacyPayload(feature, marker, token string, universe, pending []string, birth syncRunStateBirth, push bool, testCommand, validationSource string, carry guardedLegacyCarry) *internal.SyncRunState {
	payload := internal.NewSyncRunState(feature, marker, token, internal.SyncRunPolicy{})
	payload.StateVersion = internal.SyncRunStateGuardedVersion
	payload.Route = internal.RouteLegacy
	payload.MaxReplayPerEntry = birth.MaxPerEntry
	payload.MaxReplayTotal = birth.MaxTotal
	payload.Push = push
	payload.TestCommand = testCommand
	payload.ValidationSource = validationSource
	payload.Selected = append([]string{}, universe...)
	payload.Pending = append([]string{}, pending...)
	payload.Completed = append([]string{}, carry.Completed...)
	payload.FailedBranch = carry.FailedBranch
	return payload
}

// syncStateResidue is what a rollback actually left on disk, measured rather
// than inferred from the step it stopped at (§12.2c rule 4a).
type syncStateResidue struct{ Payload, Sentinel, Guard bool }

// Empty reports a rollback that undid everything it created.
func (r syncStateResidue) Empty() bool { return !r.Payload && !r.Sentinel && !r.Guard }

// String renders the PRESENT members in the fixed order payload, sentinel,
// guard: "{payload, sentinel, guard}" | "{sentinel, guard}" | "{guard}" |
// "{sentinel}" | "{}" — any subset, always that order.
func (r syncStateResidue) String() string {
	parts := make([]string, 0, 3)
	if r.Payload {
		parts = append(parts, "payload")
	}
	if r.Sentinel {
		parts = append(parts, "sentinel")
	}
	if r.Guard {
		parts = append(parts, "guard")
	}
	return "{" + strings.Join(parts, ", ") + "}"
}

// syncResidueError composes the one sentence §12.2c rule 4 and §13.2a
// require when a rollback itself fails: the failing writer's own shipped
// sentence, the measured residue, and the exact recovery command. It is
// marker-free — the guard did not refuse, a write failed.
func syncResidueError(cause error, residue syncStateResidue, feature string) error {
	return fmt.Errorf("%s; recovery state preserved: %s — clear it with: tws sync %s --abort", cause.Error(), residue.String(), feature)
}

// rollbackGuardedRunState removes exactly the three artefacts a guarded
// fresh claim created, in the shipped teardown order, propagating the first
// failure (§12.2c rule 2). It stops at the first failing step — remover or
// injected hook alike — and returns the residue actually left on disk: the
// failing step's own artefact where the remover failed, plus every artefact
// of the steps it never attempted. It touches no pre-existing artefact,
// aborts no rebase and runs no restoration.
func rollbackGuardedRunState(featurePath string) (syncStateResidue, error) {
	residue := syncStateResidue{Payload: true, Sentinel: true, Guard: true}
	if err := internal.RemoveSyncRunState(featurePath); err != nil {
		return residue, err
	}
	residue.Payload = false
	if err := syncStepHook(internal.SyncStageFinalizing, 0); err != nil {
		return residue, err
	}
	if err := internal.RemoveSyncState(featurePath); err != nil {
		return residue, err
	}
	residue.Sentinel = false
	if err := syncStepHook(internal.SyncStageFinalizing, 1); err != nil {
		return residue, err
	}
	if err := internal.RemoveSyncRunGuard(featurePath); err != nil {
		return residue, err
	}
	residue.Guard = false
	return residue, nil
}

// rollbackGuardedLegacyRunState undoes steps 4, 3 and 2 of §13.2a in REVERSE
// CREATION ORDER — payload, then the sentinel replacement, then the guard —
// stopping at the first failure and returning the residue actually left on
// disk. Releasing the guard LAST is load-bearing: the prior document is put
// back while this invocation still holds the run guard, so no other new
// binary can claim it and start writing over a half-undone directory. The
// sentinel step is ALWAYS conditional and never an unconditional removal:
// RestoreSyncStateBytes(featurePath, prior, sentinel) where prior bytes were
// captured, and RemoveSyncStateIfUnchanged(featurePath, sentinel) where
// there were none (the fresh route), so it can only ever undo the exact
// bytes THIS invocation installed. It never aborts a rebase, never touches a
// pre-existing artefact it did not create, and never re-attempts a step it
// has already failed.
func rollbackGuardedLegacyRunState(featurePath string, prior, sentinel []byte, made guardedLegacySetupProgress) (syncStateResidue, error) {
	residue := syncStateResidue{Payload: made.Payload, Sentinel: made.Sentinel, Guard: made.Guard}
	if made.Payload {
		if err := internal.RemoveSyncRunState(featurePath); err != nil {
			return residue, err
		}
		residue.Payload = false
	}
	if made.Sentinel {
		var err error
		if len(prior) > 0 {
			err = internal.RestoreSyncStateBytes(featurePath, prior, sentinel)
		} else {
			err = internal.RemoveSyncStateIfUnchanged(featurePath, sentinel)
		}
		if err != nil {
			return residue, err
		}
		residue.Sentinel = false
	}
	if made.Guard {
		if err := internal.RemoveSyncRunGuard(featurePath); err != nil {
			return residue, err
		}
		residue.Guard = false
	}
	return residue, nil
}

// guardedLegacyUndo is the exact undo token §13.2a's rollback needs: the
// bytes captured at step 1, the bytes step 3 installed, and what was really
// created. setupGuardedLegacyRunState returns it so a refusal raised AFTER a
// successful setup — the guarded legacy continuation's own pre-mutation
// guard/JIT seam — can perform the same CONDITIONAL undo the setup would
// have performed for its own failure, rather than falling back on
// rollbackGuardedRunState's unconditional RemoveSyncState, which would
// destroy the operator's captured legacy document instead of restoring it
// (§13.2a, §22.24i (ix-a)).
type guardedLegacyUndo struct {
	prior    []byte
	sentinel []byte
	made     guardedLegacySetupProgress
}

// rollback performs the conditional reverse-order undo of §13.2a for a
// refusal raised above the first Git mutation but below a successful setup.
func (u guardedLegacyUndo) rollback(featurePath, feature string, refusal *internal.PlanGuardRefusalError) error {
	residue, err := rollbackGuardedLegacyRunState(featurePath, u.prior, u.sentinel, u.made)
	if err != nil {
		preserved := *refusal
		preserved.StatePreserved = true
		preserved.Detail = fmt.Sprintf("%s; recovery state preserved: %s — clear it with: tws sync %s --abort", refusal.Detail, residue.String(), feature)
		return &preserved
	}
	return refusal
}

// setupGuardedLegacyRunState writes the guarded LEGACY envelope over the
// exact four-step, crash-safe order of §13.2a: capture the CURRENT
// .sync-state.yaml bytes (absent ⇒ nil, which is every fresh run, since a
// plain run over a real legacy state is refused above this point) →
// ClaimSyncRunGuard (the shipped O_EXCL claim, FIRST, exactly as
// setupSyncRunState orders it, so two new binaries racing over one feature
// cannot both reach the replacement) → the CONDITIONAL atomic write of the
// BACKUP SENTINEL over that same path (an exclusive create where nothing was
// captured, a compare-and-swap over the captured bytes where something was)
// → the atomic state_version: 3, route: legacy payload write → return the
// payload. The steps fire the shipped SyncStageInitializing hooks, which
// name ARTEFACTS (0 = guard, 1 = sentinel, 2 = payload) and are therefore
// fired here in the order 3 → 0 → 1 → 2; the capture adds index 3.
//
// The captured bytes are owned by this function, not by its caller: on any
// failure at or below the claim — a writer error, a claim refusal or a
// boundary hook that RETURNS an error — it rolls back through
// rollbackGuardedLegacyRunState, so a failed setup leaves a byte-identical
// legacy state and no payload, sentinel or guard, and a failed ROLLBACK
// returns the measured residue instead of pretending. Residue is reachable
// only from a process that died, never from a returned error.
func setupGuardedLegacyRunState(layout externalSyncLayout, feature, marker, token string, universe, pending []string, push bool, testCommand, validationSource string, birth syncRunStateBirth, carry guardedLegacyCarry) (*internal.SyncRunState, guardedLegacyUndo, error) {
	featurePath := layout.FeaturePath

	// Step 1 — capture. Nothing has been written or claimed yet, so a
	// failure here leaves the run exactly as found.
	prior, err := captureGuardedLegacySyncState(featurePath)
	if err != nil {
		return nil, guardedLegacyUndo{}, err
	}
	if err := syncStepHook(internal.SyncStageInitializing, 3); err != nil {
		return nil, guardedLegacyUndo{}, err
	}

	sentinel := newGuardedLegacySentinel(feature, marker, token, universe, pending, birth, push, testCommand, validationSource, carry, prior)
	sentinelBytes, err := internal.MarshalGuardedLegacySentinel(sentinel)
	if err != nil {
		return nil, guardedLegacyUndo{}, err
	}

	made := guardedLegacySetupProgress{}
	fail := func(cause error) (*internal.SyncRunState, guardedLegacyUndo, error) {
		residue, rollbackErr := rollbackGuardedLegacyRunState(featurePath, prior, sentinelBytes, made)
		if rollbackErr != nil {
			return nil, guardedLegacyUndo{}, syncResidueError(rollbackErr, residue, feature)
		}
		return nil, guardedLegacyUndo{}, cause
	}

	// Step 2 — claim. This arm's first write and its mutual-exclusion point;
	// nothing else exists yet, so its own failure rolls nothing back.
	if err := internal.ClaimSyncRunGuard(featurePath, token); err != nil {
		return nil, guardedLegacyUndo{}, err
	}
	made.Guard = true
	if err := externalSyncPostClaimRecheck(feature, layout, token); err != nil {
		return nil, guardedLegacyUndo{}, err
	}
	if err := syncStepHook(internal.SyncStageInitializing, 0); err != nil {
		return fail(err)
	}

	// Step 3 — the conditional backup sentinel.
	if err := internal.SaveGuardedLegacySentinel(featurePath, sentinel, prior); err != nil {
		if errors.Is(err, internal.ErrSyncStateChanged) {
			return fail(fmt.Errorf("sync state at %s changed while starting a guarded resume; re-run: tws sync %s --continue", internal.SyncStatePath(featurePath), feature))
		}
		return fail(fmt.Errorf("write sync sentinel: %w", err))
	}
	made.Sentinel = true
	if err := syncStepHook(internal.SyncStageInitializing, 1); err != nil {
		return fail(err)
	}

	// Step 4 — the v3 payload.
	payload := newGuardedLegacyPayload(feature, marker, token, universe, pending, birth, push, testCommand, validationSource, carry)
	if err := internal.SaveSyncRunState(featurePath, payload); err != nil {
		return fail(fmt.Errorf("write scoped sync state: %w", err))
	}
	made.Payload = true
	if err := syncStepHook(internal.SyncStageInitializing, 2); err != nil {
		return fail(err)
	}
	return payload, guardedLegacyUndo{prior: prior, sentinel: sentinelBytes, made: made}, nil
}

// claimOrReclaimGuardedLegacyGuard performs §13.2a step 2 for the cell-4
// recovery arm, where the sentinel already exists. The choice follows the
// SNAPSHOT the classifier took — whether a `.sync-run.lock` was there at all
// — and never the provenance of the residue: crash window 2 and the
// `{sentinel, guard}` rollback residue reach the same cell and must answer
// identically. A present guard is RECLAIMED through the shipped
// compare-and-swap ladder (which refuses a live owner, foreign or
// self-recorded alike); an absent one — an operator removed the lock by hand
// — is CLAIMED through the shipped O_EXCL ladder.
func claimOrReclaimGuardedLegacyGuard(featurePath, token string, guardPresent bool) error {
	if guardPresent {
		return internal.ReclaimSyncRunGuard(featurePath, token)
	}
	return internal.ClaimSyncRunGuard(featurePath, token)
}

// writeGuardedLegacyRecoveryPayload performs §13.2a step 4 alone for the
// cell-4 recovery arm: the state_version: 3, route: legacy payload built
// from the sentinel's own verified intent block. It writes no sentinel — the
// backup sentinel is already on disk and is exactly what this arm is
// recovering — and it re-plans nothing.
func writeGuardedLegacyRecoveryPayload(featurePath string, sentinel *internal.GuardedLegacySentinel) (*internal.SyncRunState, error) {
	birth := syncRunStateBirth{
		StateVersion: internal.SyncRunStateGuardedVersion,
		Route:        internal.RouteLegacy,
		MaxPerEntry:  sentinel.MaxReplayPerEntry,
		MaxTotal:     sentinel.MaxReplayTotal,
	}
	carry := guardedLegacyCarry{
		Completed:         append([]string(nil), sentinel.CarriedCompleted...),
		FailedBranch:      sentinel.CarriedFailed,
		PriorPendingCount: sentinel.PriorPendingCount,
	}
	payload := newGuardedLegacyPayload(sentinel.Feature, sentinel.Marker, sentinel.OwnerToken,
		sentinel.Universe, sentinel.PendingIntent, birth, sentinel.Push,
		sentinel.TestCommand, sentinel.ValidationSource, carry)
	if err := syncStepHook(internal.SyncStageInitializing, 2); err != nil {
		return nil, err
	}
	if err := internal.SaveSyncRunState(featurePath, payload); err != nil {
		return nil, fmt.Errorf("write scoped sync state: %w", err)
	}
	return payload, nil
}

// rollbackGuardedFreshRefusal is §12.2c rule 2/3/4 applied to a guarded
// fresh route's own pre-mutation refusal: the rollback runs FIRST, so the
// marker line describes the state the operator will actually find, and a
// cleanup failure is reported honestly with the measured residue instead of
// being swallowed.
func rollbackGuardedFreshRefusal(featurePath, feature string, refusal *internal.PlanGuardRefusalError) error {
	residue, err := rollbackGuardedRunState(featurePath)
	if err != nil {
		preserved := *refusal
		preserved.StatePreserved = true
		preserved.Detail = fmt.Sprintf("%s; recovery state preserved: %s — clear it with: tws sync %s --abort", refusal.Detail, residue.String(), feature)
		return &preserved
	}
	return refusal
}

// upgradeGuardedSyncRunState upgrades an existing, unguarded new-mode payload
// (cell 5, arm b) to the guarded envelope in place: it records
// StateVersion/Route/the newly supplied limits and otherwise leaves
// Selected/Completed/Pending/FailedBranch/Stage untouched, so the resumed run
// continues at exactly the point it was interrupted. It never touches the
// sentinel beside the payload: GuardedLegacySentinelResumable's own
// cell-4-only dispatch never consults a new-mode run's sentinel, so an
// upgraded payload's crash-orphan recovery is unchanged from today's plain
// cell-4 handling.
func upgradeGuardedSyncRunState(featurePath string, payload *internal.SyncRunState, birth syncRunStateBirth) error {
	if payload.Transaction != nil {
		payload.StateVersion = internal.SyncRunStateTransactionalGuardedVersion
		payload.PlanGuarded = true
	} else {
		payload.StateVersion = birth.StateVersion
		payload.Route = internal.RouteNewMode
	}
	payload.MaxReplayPerEntry = birth.MaxPerEntry
	payload.MaxReplayTotal = birth.MaxTotal
	return internal.SaveSyncRunState(featurePath, payload)
}

// saveScopedSyncFailure is the new-mode failure persistence path. It writes the
// payload only: saveIncompleteSync is never called by a new-mode run, because
// it would overwrite the sentinel with a resolvable name.
func saveScopedSyncFailure(featurePath string, payload *internal.SyncRunState, failed string, completed []string) error {
	if payload == nil {
		return nil
	}
	payload.Stage = internal.SyncStageFailed
	payload.FailedBranch = failed
	payload.Completed = append([]string(nil), completed...)
	done := make(map[string]bool, len(completed))
	for _, name := range completed {
		done[name] = true
	}
	pending := make([]string, 0, len(payload.Selected))
	for _, name := range payload.Selected {
		if name != failed && !done[name] {
			pending = append(pending, name)
		}
	}
	payload.Pending = pending
	if payload.Transaction != nil {
		payload.Transaction.Phase = internal.SyncTxnFailed
	}
	return internal.SaveSyncRunState(featurePath, payload)
}

// saveScopedPushFailure is the new-mode push failure persistence path. Unlike
// saveScopedSyncFailure it never recomputes `pending` or `completed`: the
// rebases already succeeded and only the push of `failed` is outstanding, so
// the payload keeps everything --continue needs to retry exactly the unpushed
// entries.
func saveScopedPushFailure(featurePath string, payload *internal.SyncRunState, failed string) error {
	if payload == nil {
		return nil
	}
	payload.Stage = internal.SyncStageFailed
	payload.FailedBranch = failed
	if payload.Transaction != nil {
		payload.Transaction.Phase = internal.SyncTxnPublished
	}
	return internal.SaveSyncRunState(featurePath, payload)
}

// ---------------------------------------------------------------------------
// Test-only seams (§23.1 items 2 and 2a). Both are nil in production, inject
// no verdict, and exist so a second process can really mutate the feature
// directory inside a window this command otherwise closes instantly.
// ---------------------------------------------------------------------------

// syncClassifierBarrierHook is §23.1 seam 2a: the window between
// classifySyncState and the cell-4 guarded-sentinel interception, so a test
// can create, remove or replace .sync-state.yaml between the two reads.
var syncClassifierBarrierHook func(featurePath string) error

func syncClassifierBarrier(featurePath string) error {
	if syncClassifierBarrierHook != nil {
		return syncClassifierBarrierHook(featurePath)
	}
	return nil
}

// syncSnapshotBarrierHook is §23.1 seam 2: the window between the run's one
// state snapshot (InspectExternalPlanState, inside InspectExternalPlan) and
// the guard seam that judges the document built from it.
var syncSnapshotBarrierHook func(featurePath string) error

func syncSnapshotBarrier(featurePath string) error {
	if syncSnapshotBarrierHook != nil {
		return syncSnapshotBarrierHook(featurePath)
	}
	return nil
}

// syncReclassifyCount counts §12.8b vanished-state re-classifications. The
// contract is "at most once per invocation", and this counter is what makes
// that assertion executable rather than aspirational.
var syncReclassifyCount atomic.Int64

// syncStepHook is the package-cli side of the external crash-injection seam.
func syncStepHook(stage internal.SyncRunStage, index int) error {
	if internal.SyncStepHook != nil {
		return internal.SyncStepHook(stage, index)
	}
	return nil
}

// ---------------------------------------------------------------------------
// Header and no-op output (spec §3.7)
// ---------------------------------------------------------------------------

// printSyncModeHeaderTo is the writer-taking twin of printSyncModeHeader —
// the single body this feature's plan route and every executing route share.
// Its bytes are identical to internal.printSyncModeHeaderTo's, which serves
// the checkout half.
func printSyncModeHeaderTo(w io.Writer, p internal.SyncRunPolicy) {
	_, _ = fmt.Fprintf(w, "Sync mode: fetch=%s propagation=%s scope=%s\n", p.Fetch, p.Propagation, p.ScopeLabel())
}

// printSyncModeHeader prints the §3.7 header to stdout. It is now a one-line
// wrapper over printSyncModeHeaderTo, byte-identical to the pre-change body.
func printSyncModeHeader(p internal.SyncRunPolicy) {
	printSyncModeHeaderTo(os.Stdout, p)
}

// syncAnchorNoOpLine is the `[-]` line of the local-only no-op block. It reuses
// formatSyncStatus with the sentence in the mode slot; package internal repeats
// the same literal and the two must stay byte-identical.
func syncAnchorNoOpLine(name string) string {
	return formatSyncStatus(name, "no in-stack parent edge to propagate", "skipped")
}

// ---------------------------------------------------------------------------
// Completion (spec §3.8)
// ---------------------------------------------------------------------------

// syncEntryCompletion offers the non-archived logical entry names of the
// feature named by args[0]. Every error degrades to "no candidates": it never
// errors, never prints, and never exits.
func syncEntryCompletion(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
	if len(args) == 0 {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	ws, err := internal.RequireWorkspace()
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	layout, err := resolveExternalSyncLayout(ws, internal.TwsRoot(), args[0])
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		return nil, cobra.ShellCompDirectiveNoFileComp
	}
	var names []string
	for _, entry := range stack.Branches {
		if entry.Archived {
			continue
		}
		names = append(names, entry.Name)
	}
	return names, cobra.ShellCompDirectiveNoFileComp
}

package cli

import (
	"errors"
	"fmt"
	"io"
	"os"
	"regexp"
	"sort"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

// ---------------------------------------------------------------------------
// sync-plan-guard — the package-cli half of the rebase-plan-guard feature
// (spec §3): the five control flags, their §3.4 validation ladder, the
// external plan-only route (§13.7a), the guarded execution routes, and the
// writer-taking render/marker plumbing (§3.6) shared by both workspace
// modes.
// ---------------------------------------------------------------------------

// planGuardControlFlags is the closed key set of planGuardOptions.Present, in
// the source order of spec §3.1.
var planGuardControlFlags = []string{"plan", "json", "max-replay-per-entry", "max-replay-total", "approve-plan"}

// The six shared validation sentences this file owns. They are hoisted to
// package constants, with no byte changed, so a sibling command that tests
// the identical condition reuses the exact sentence rather than re-typing a
// literal that can drift. Every fmt.Errorf below now formats the constant
// with %s, which produces the same bytes as the literal it replaced and
// leaves every `tws sync` message, help string and golden untouched.
const (
	errMsgJSONRequiresPlan       = "--json requires --plan"
	errMsgPlanWithAbort          = "--plan cannot be combined with --abort"
	errMsgMaxPerEntryNonNegative = "--max-replay-per-entry must be zero or greater"
	errMsgMaxTotalNonNegative    = "--max-replay-total must be zero or greater"
	errMsgApproveTokenShape      = "--approve-plan requires a 64-character lowercase hex fingerprint"
	errMsgApproveRequiresLimits  = "--approve-plan requires --max-replay-per-entry or --max-replay-total"
)

// planGuardOptions is the control-flag envelope resolvePlanGuardOptions
// produces. It is a strict cli-side mirror of internal.CheckoutPlanGuard,
// minus the runtime-only PersistedGuarded field.
type planGuardOptions struct {
	Plan        bool
	JSON        bool
	MaxPerEntry *int // nil == absent; *v == 0 is a real limit
	MaxTotal    *int
	Approve     string
	Present     map[string]bool // "plan","json","max-replay-per-entry","max-replay-total","approve-plan"
}

// Armed reports whether this invocation armed something: at least one limit
// is present, or a token was supplied. It mirrors
// internal.CheckoutPlanGuard.Armed() exactly.
func (o planGuardOptions) Armed() bool {
	return o.MaxPerEntry != nil || o.MaxTotal != nil || o.Approve != ""
}

// checkoutGuard converts to the internal-owned type both executors and the
// plan builder require, so no cli type ever crosses the package boundary
// (§19.1, §19.2). PersistedGuarded always starts false here: only the
// checkout --continue dispatch (checkout_sync.go) and the external guarded
// continuation handlers set it, each from its own persisted-guarded fact.
func (o planGuardOptions) checkoutGuard() internal.CheckoutPlanGuard {
	return internal.CheckoutPlanGuard{
		Plan:        o.Plan,
		JSON:        o.JSON,
		MaxPerEntry: o.MaxPerEntry,
		MaxTotal:    o.MaxTotal,
		Approve:     o.Approve,
		Present:     o.Present,
	}
}

// checkoutGuardPersisted is checkoutGuard with PersistedGuarded set from the
// caller's own persisted-guarded fact — the external continuation handlers'
// own analogue of checkout_sync.go's opts.PlanGuard.PersistedGuarded
// assignment. Without it, EvaluatePlanGuard's own Guarded() gate would be a
// silent no-op on a --continue that re-supplies no limit flag of its own,
// even though the persisted run is already guarded.
func (o planGuardOptions) checkoutGuardPersisted(persisted bool) internal.CheckoutPlanGuard {
	g := o.checkoutGuard()
	g.PersistedGuarded = persisted
	return g
}

// resolvePlanGuardOptions performs the §3.4 incompatibility matrix in its
// exact evaluation order and returns byte-exact messages. It is called once,
// immediately after resolveSyncPolicy and before mode dispatch (§3.3 step 3),
// so both workspace modes reject identically. It reads only the five control
// flags plus cmd.Flags().Changed("continue")/("abort"): no state, no stack,
// no repository.
func resolvePlanGuardOptions(cmd *cobra.Command) (planGuardOptions, error) {
	present := make(map[string]bool, len(planGuardControlFlags))
	for _, name := range planGuardControlFlags {
		present[name] = cmd.Flags().Changed(name)
	}

	opts := planGuardOptions{Present: present}
	opts.Plan, _ = cmd.Flags().GetBool("plan")
	opts.JSON, _ = cmd.Flags().GetBool("json")
	opts.Approve, _ = cmd.Flags().GetString("approve-plan")

	// Row 1: --json requires --plan. Checked unconditionally, first, so a
	// --json --abort invocation (row 6 of the matrix) is refused with this
	// same message rather than the --abort combination message below.
	if present["json"] && !opts.Plan {
		return planGuardOptions{}, fmt.Errorf("%s", errMsgJSONRequiresPlan)
	}

	cont := syncBoolFlag(cmd, "continue")
	abort := syncBoolFlag(cmd, "abort")

	// Rows 2-5: every other control flag is incompatible with --abort.
	if abort {
		switch {
		case present["plan"]:
			return planGuardOptions{}, fmt.Errorf("%s", errMsgPlanWithAbort)
		case present["max-replay-per-entry"]:
			return planGuardOptions{}, fmt.Errorf("--max-replay-per-entry cannot be combined with --abort")
		case present["max-replay-total"]:
			return planGuardOptions{}, fmt.Errorf("--max-replay-total cannot be combined with --abort")
		case present["approve-plan"]:
			return planGuardOptions{}, fmt.Errorf("--approve-plan cannot be combined with --abort")
		}
	}

	// Rows 7-8: a supplied limit must be zero or greater. Row 9 (a
	// non-integer value) is pflag's own parse error and never reaches RunE.
	if present["max-replay-per-entry"] {
		v, _ := cmd.Flags().GetInt("max-replay-per-entry")
		if v < 0 {
			return planGuardOptions{}, fmt.Errorf("%s", errMsgMaxPerEntryNonNegative)
		}
		opts.MaxPerEntry = &v
	}
	if present["max-replay-total"] {
		v, _ := cmd.Flags().GetInt("max-replay-total")
		if v < 0 {
			return planGuardOptions{}, fmt.Errorf("%s", errMsgMaxTotalNonNegative)
		}
		opts.MaxTotal = &v
	}

	// Rows 10-11: --approve-plan's syntactic shape, then its presence-
	// requires-limits rule (never enforced on --continue, regardless of
	// --plan).
	if present["approve-plan"] {
		token := strings.TrimSpace(opts.Approve)
		if !planApproveTokenShape.MatchString(token) {
			return planGuardOptions{}, fmt.Errorf("%s", errMsgApproveTokenShape)
		}
		opts.Approve = token
		if !cont && opts.MaxPerEntry == nil && opts.MaxTotal == nil {
			return planGuardOptions{}, fmt.Errorf("%s", errMsgApproveRequiresLimits)
		}
	}

	return opts, nil
}

// planApproveTokenShape is --approve-plan's exact syntactic domain,
// ^[0-9a-f]{64}$ (spec §3.1 rule 2). BuildRebasePlan itself performs the
// bytewise comparison against the computed fingerprint; this shape check is
// the only validation resolvePlanGuardOptions performs on the token.
var planApproveTokenShape = regexp.MustCompile(`^[0-9a-f]{64}$`)

// ---------------------------------------------------------------------------
// Render/marker/refusal plumbing (spec §3.6)
// ---------------------------------------------------------------------------

// renderPlanDocument is a one-line wrapper passing cmd.OutOrStdout() and
// cmd.ErrOrStderr() to renderPlanDocumentTo.
func renderPlanDocument(cmd *cobra.Command, plan internal.RebasePlan, jsonMode bool) error {
	return renderPlanDocumentTo(cmd.OutOrStdout(), cmd.ErrOrStderr(), plan, jsonMode)
}

// renderPlanDocumentTo is the writer-taking render dispatch: the sole caller
// of FormatRebasePlan/MarshalRebasePlan and the sole binder of document bytes
// to a stream anywhere in the tree. It performs exactly one stdout.Write of
// the complete buffer — no retry, no fallback stream — and returns the
// renderer's error without writing anything when encoding/formatting failed
// (§3.6 row 6). stderr is accepted for signature symmetry with this
// feature's other two-writer helpers; neither renderer emits an operational
// byte for this function to forward, so it is otherwise unused here.
func renderPlanDocumentTo(stdout, stderr io.Writer, plan internal.RebasePlan, jsonMode bool) error {
	_ = stderr
	var buf []byte
	var err error
	if jsonMode {
		buf, err = internal.MarshalRebasePlan(plan)
	} else {
		buf, err = internal.FormatRebasePlan(plan)
	}
	if err != nil {
		return err
	}
	_, err = stdout.Write(buf)
	return err
}

// writePlanGuardMarker prints the anchored guard marker line (§6.4) — the
// ONE format string `plan-guard: %s\n` of e.Error() — and nothing else.
func writePlanGuardMarker(w io.Writer, e *internal.PlanGuardRefusalError) {
	_, _ = fmt.Fprintf(w, "plan-guard: %s\n", e.Error())
}

// planGuardRefusal prints the anchored marker for a guard-owned refusal and
// returns err unchanged. Every other error passes through untouched and
// marker-free, exactly as spec §3.6 rows 4-7, 10 require. It is the single
// wrap point both the external and the checkout RunE dispatch apply to their
// own executing-route return.
func planGuardRefusal(cmd *cobra.Command, err error) error {
	var refusal *internal.PlanGuardRefusalError
	if errors.As(err, &refusal) {
		writePlanGuardMarker(cmd.ErrOrStderr(), refusal)
	}
	return err
}

// ---------------------------------------------------------------------------
// planGuardRun — the executor-side guard carrier (spec §12.2b, §12.3)
// ---------------------------------------------------------------------------

// planGuardRun is the guarded executor's own JIT revalidation state: the
// approved plan's per-entry rows (keyed by name), the effective limits, the
// running replay total THIS invocation has accumulated, and whether state
// has already been preserved by an earlier invocation's own progress. A nil
// *planGuardRun is the unguarded path throughout syncWithStackScoped: every
// JIT seam is itself gated on guard != nil, so a nil guard leaves every
// shipped byte and process untouched.
type planGuardRun struct {
	req            internal.RebasePlanRequest
	approved       map[string]internal.PlanEntry
	limits         internal.PlanGuardLimits
	replayedTotal  int
	statePreserved bool
}

// newPlanGuardRun builds the carrier from the already-built, already-
// evaluated plan. Its limits are the document's OWN plan.Guard.Limits — the
// same reconciled per-entry/total values RevalidatePlanGuardEntry must
// enforce against — never re-resolved a second time from opts/payload.
// statePreserved starts true only for a --continue that reclaimed an
// existing, already-guarded run: a branch may already have moved in a PRIOR
// invocation before this one's own first revalidation ever runs. It starts
// false for a fresh run and flips true after this invocation's own first
// successful revalidate (spec's Long text: "before any branch has moved
// unless that line says state-preserved:").
func newPlanGuardRun(req internal.RebasePlanRequest, plan internal.RebasePlan, statePreserved bool) *planGuardRun {
	approved := make(map[string]internal.PlanEntry, len(plan.Entries))
	for _, e := range plan.Entries {
		approved[e.Name] = e
	}
	limits := internal.PlanGuardLimits{PerEntry: plan.Guard.Limits.MaxReplayPerEntry, Total: plan.Guard.Limits.MaxReplayTotal}
	return &planGuardRun{req: req, approved: approved, limits: limits, statePreserved: statePreserved}
}

// revalidate re-verifies one entry immediately before its rebase runs
// (spec §12.2b/§12.3's JIT seam), through internal.RevalidatePlanGuardEntry
// alone — never internal.RevalidatePlanEntry directly. A name absent from
// the approved plan (never expected on a guarded route, since Remaining is
// always a subset of the approved entries) never blocks: there is nothing
// approved to compare against, so revalidation has nothing to say about it.
// The running replay total accumulates the count the seam FRESHLY resolved,
// never the approved row's own recorded value: an `upstream-deferred` row is
// approved with a null count, so accumulating the approved value would add
// zero for exactly the rows §10.4's deferral policy exists to re-measure and
// would let a run walk past max_replay_total unrefused.
func (g *planGuardRun) revalidate(name string) error {
	if g == nil {
		return nil
	}
	approved, ok := g.approved[name]
	if !ok {
		return nil
	}
	res, err := internal.RevalidatePlanGuardEntry(internal.RevalidatePlanGuardEntryRequest{
		Request:        g.req,
		Approved:       approved,
		Limits:         g.limits,
		ReplayedTotal:  g.replayedTotal,
		StatePreserved: g.statePreserved,
	})
	if err != nil {
		return err
	}
	g.replayedTotal += res.CandidateCount
	g.statePreserved = true
	return nil
}

// planLayout converts the external layout to the internal-owned
func planLayout(l externalSyncLayout, repoRoot string) internal.RebasePlanLayout {
	return internal.RebasePlanLayout{FeaturePath: l.FeaturePath, WorktreesRoot: l.WorktreesRoot, RepoRoot: repoRoot}
}

// externalWorkspace projects internal.Workspace into the plan's display-only
// PlanWorkspace (§8.3). It re-derives no identity: ws is already this
// invocation's own single RequireWorkspace() result.
func externalWorkspace(ws internal.Workspace) internal.PlanWorkspace {
	var stableID *string
	if ws.StableID != "" {
		id := ws.StableID
		stableID = &id
	}
	return internal.PlanWorkspace{Mode: string(internal.ModeExternal), StableID: stableID, RepoRoot: ws.RepoRoot}
}

// ---------------------------------------------------------------------------
// External plan inspection (spec §13.7a) — the read-only measurement pass
// mirroring internal.InspectCheckoutPlan/CheckoutPlanInspectionRequest
// field-for-field, substituting the external state/selection/stage types.
// ---------------------------------------------------------------------------

// ExternalPlanInspectionRequest bundles InspectExternalPlan's inputs.
type ExternalPlanInspectionRequest struct {
	Feature string
	Layout  externalSyncLayout
	Ws      internal.Workspace
	Opts    planGuardOptions
	Policy  internal.SyncRunPolicy
	NewMode bool
	Push    bool
	Verbose bool
	Changed map[string]bool

	// Continue is this invocation's own --continue flag. It is supplied by
	// the caller (runExternalPlan), which already resolved it identically to
	// the executing dispatch.
	Continue bool

	// PersistedGuarded is the caller's own persisted-guarded fact (§13.6 rule
	// 4d): true whenever a --continue is resuming an already-guarded
	// persisted run (a scoped payload at state_version >= 3, or a guarded
	// legacy sentinel), independent of whether this invocation re-supplies
	// any limit flag of its own. It is never true on a fresh run.
	PersistedGuarded bool

	// Classified is classifySyncState's own already-produced verdict —
	// required, exactly mirroring InspectExternalPlanState's own contract:
	// never recomputed here.
	Classified internal.SyncExternalState

	// Sentinel is the ONE guarded-legacy sentinel view of §13.6 rule 2c,
	// evaluated by the §19.2 dispatch on cell 4 alone and threaded in. It is
	// the zero value (verdict "", i.e. not applicable) on every other cell,
	// which never consults it, and this pipeline never decodes a sentinel of
	// its own. On the cell-4 RECOVERY arm it is the resumed subject: its
	// intent block supplies the universe, the pending set, the effective
	// limits and the frozen validation command (§19.2, §12.8b).
	Sentinel internal.GuardedLegacySentinelView
}

// resumableSentinel is the cell-4 recovery arm's own subject, or nil on
// every other cell: the sentinel this invocation may resume, exactly as
// GuardedLegacySentinelResumable decided it.
func (req ExternalPlanInspectionRequest) resumableSentinel() *internal.GuardedLegacySentinel {
	if req.Classified.Cell != 4 || req.Sentinel.Verdict != internal.SentinelValid {
		return nil
	}
	return req.Sentinel.Sentinel
}

// checkoutGuard combines req.Opts' own control-flag mirror with req's own
// persisted-guarded fact, exactly as planGuardOptions.checkoutGuardPersisted
// does — the single conversion both externalPlanRequest's Guard field and
// buildGuardedExternalPlan's EvaluatePlanGuard call must use, so neither one
// can drift from the other.
func (req ExternalPlanInspectionRequest) checkoutGuard() internal.CheckoutPlanGuard {
	return req.Opts.checkoutGuardPersisted(req.PersistedGuarded)
}

// ExternalPlanInspection is InspectExternalPlan's own result: every fact
// externalPlanRequest needs to construct a RebasePlanRequest without
// re-probing Git state a second time.
type ExternalPlanInspection struct {
	Continue     bool
	Version      internal.GitVersion
	Capabilities internal.GitCapabilities

	State internal.ExternalPlanState

	Stack    internal.Stack
	StackErr error
	Order    []internal.StackEntry
	SortErr  error

	Selection         internal.SyncSelection
	SelectionResolved bool
	SelectionErr      error

	Remaining  []string
	StageFacts []internal.PlanStageFact

	BasePreflight internal.PlanBasePreflight
	FetchPlan     internal.PlanFetchPlan
	Gates         []internal.PlanGateResult

	Limits         internal.PlanGuardLimits
	LimitConflicts []internal.PlanGuardLimitConflict
}

// InspectExternalPlan is the external route's own read-only inspection,
// mirroring internal.InspectCheckoutPlan's ordered pass: version/
// capabilities, state, the fresh-run precondition gates, the reconciled
// guard limits, the stack/order/selection triple, and — continue route only
// — the remaining-entries projection, or — fresh route only — the I14 base
// preflight and the pre-fetch context enumeration.
func InspectExternalPlan(req ExternalPlanInspectionRequest) ExternalPlanInspection {
	var insp ExternalPlanInspection
	insp.Continue = req.Continue
	insp.Capabilities, insp.Version, _ = internal.ProbeGitCapabilities()
	insp.State = internal.InspectExternalPlanState(req.Layout.FeaturePath, internal.ExternalPlanStateOpts{Classified: req.Classified})
	// Rule 3a is fixed immediately after the version probe, above fetch and
	// config reads. Rule 3b is appended after selection/materialization can
	// prove this invocation has an actual positive --update-refs row.
	insp.Gates = append(
		internal.CapabilityGates(insp.Version, insp.Capabilities, false),
		externalPreconditionGates(req)...)

	payload := req.Classified.Payload
	sentinel := req.resumableSentinel()
	insp.Limits = resolveExternalGuardLimits(req.Opts, payload, sentinel)
	insp.LimitConflicts = resolveExternalLimitConflicts(payload, sentinel, req.Opts)

	stack, stackErr := internal.LoadStack(req.Layout.FeaturePath)
	if stackErr != nil {
		insp.StackErr = stackErr
		return insp
	}
	insp.Stack = stack

	order, sortErr := internal.TopoSort(stack)
	if sortErr != nil {
		insp.SortErr = sortErr
		return insp
	}
	insp.Order = order

	// A --continue with an existing scoped payload reflects the run's frozen
	// `selected` list (scopedSelectionFromPayloadOrder), exactly as the
	// executing continue routes do, rather than re-deriving scope from this
	// invocation's own flags: syncContinueMismatches only refuses an
	// *explicit* re-specification that disagrees with the payload, so an
	// unspecified flag's default must never silently re-scope the described
	// plan away from what execution will actually select.
	var sel internal.SyncSelection
	var selErr error
	switch {
	case req.Continue && payload != nil:
		sel, selErr = scopedSelectionFromPayloadOrder(stack, order, payload, req.Feature, req.Ws.Mode)
	case req.Continue && sentinel != nil:
		// §19.2's recovery arm: the resumed universe is the sentinel's own
		// intent block — the full-stack legacy selection the interrupted run
		// froze — never this invocation's flags, which the interception has
		// already refused if they carried a trigger.
		sel, selErr = legacySelectionFromOrder(stack, order, req.Policy, req.Feature, req.Ws.Mode)
	default:
		sel, selErr = internal.ResolveSyncSelectionFromOrder(stack, order, req.Policy, internal.SyncSelectionOpts{
			Mode:    internal.ModeExternal,
			NewMode: req.NewMode,
			Feature: req.Feature,
		})
	}
	if selErr != nil {
		insp.SelectionErr = selErr
		return insp
	}
	insp.Selection = sel
	insp.SelectionResolved = true

	route := externalEffectiveRoute(req, payload)
	if sentinel != nil {
		// The recovery arm's remaining set is the sentinel's OWN pending
		// intent (§12.8b, §19.2 step 4), narrowed to the entries the current
		// stack still has: the backup sentinel's `.sync-state.yaml` carries
		// empty pending/completed lists by construction, so the shipped
		// legacy projection would otherwise read "nothing is done" and
		// republish the entire universe.
		insp.Remaining = sentinelRemaining(sentinel, sel)
	} else {
		insp.Remaining = internal.RemainingRebaseEntries(
			route,
			planLayout(req.Layout, req.Ws.RepoRoot),
			internal.RemainingEntriesState{Mode: internal.ModeExternal, External: insp.State},
			order, sel,
		)
	}
	insp.Gates = append(insp.Gates, internal.RebaseUpdateRefsCapabilityGates(
		insp.Version, insp.Capabilities,
		externalSelectionNeedsUpdateRefs(req.Layout, sel, insp.Remaining),
	)...)

	if req.Continue {
		insp.StageFacts = externalStageFacts(insp.Remaining)
		return insp
	}

	insp.BasePreflight = externalBasePreflight(req.Layout, stack, sel)

	if req.Policy.Fetch == internal.SyncFetchEnabled {
		insp.FetchPlan = externalFetchPlan(req.Layout, stack, sel, req.NewMode, insp.Capabilities)
	}

	return insp
}

// externalSelectionNeedsUpdateRefs is §16 rule 3b's precise argv predicate.
// Only remaining, selected, materialized pass-1 rows in a full scope=all
// external run carry the positive option. Local-only, scoped, all-archived,
// and publication/cleanup-only continuation routes remain supported on
// Git 2.26-2.37.
func externalSelectionNeedsUpdateRefs(layout externalSyncLayout, sel internal.SyncSelection, remaining []string) bool {
	if sel.Policy.Scoped() || sel.Policy.Propagation != internal.SyncPropagationFull {
		return false
	}
	pending := make(map[string]bool, len(remaining))
	for _, name := range remaining {
		pending[name] = true
	}
	for _, entry := range sel.Entries {
		if !pending[entry.Name] {
			continue
		}
		if _, err := os.Stat(layout.WorktreePath(entry.Name)); err == nil {
			return true
		}
	}
	return false
}

// externalEffectiveRoute derives this invocation's own effective route
// (§13.6 rule 4), mirroring internal's own checkout twin: a --continue of an
// already-persisted payload inherits ITS OWN route (PayloadNewMode, never
// re-derived from req.NewMode, which a continuation invocation need not even
// repeat); a fresh run's route is req.NewMode directly.
func externalEffectiveRoute(req ExternalPlanInspectionRequest, payload *internal.SyncRunState) string {
	if req.Continue && payload != nil {
		if internal.PayloadNewMode(payload) {
			return internal.RouteNewMode
		}
		return internal.RouteLegacy
	}
	if req.NewMode {
		return internal.RouteNewMode
	}
	return internal.RouteLegacy
}

// externalRequestedRoute is RebasePlanRequest.RequestedRoute: "" when the
// command line's own requested route equals the effective route, the
// requested route string otherwise.
func externalRequestedRoute(newMode bool, effective string) string {
	requested := internal.RouteLegacy
	if newMode {
		requested = internal.RouteNewMode
	}
	if requested == effective {
		return ""
	}
	return requested
}

// externalRouteTriggers is RebasePlanRequest.RouteTriggers: sorted Changed
// trigger names, mirroring internal's checkoutRouteTriggers exactly.
func externalRouteTriggers(changed map[string]bool) []string {
	names := make([]string, 0, len(changed))
	for _, name := range syncTriggerFlags {
		if changed[name] {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	return names
}

// externalPreconditionGates evaluates the fresh-run, pre-lock precondition
// this invocation's own shipped executor would check before ever touching
// the filesystem for a run guard (spec §13.7a): syncCellRefusal's own
// verdict for this cell/verb is the single source of it, so this gate is a
// PROJECTION of that shipped ladder, never a second implementation of it. It
// is a silent no-op on --continue, which has already passed it by
// definition.
func externalPreconditionGates(req ExternalPlanInspectionRequest) []internal.PlanGateResult {
	if sentinel := req.resumableSentinel(); sentinel != nil {
		// §12.8b: a VALID guarded backup sentinel never reaches
		// syncCellRefusal, so the gate publishes the sentence the executing
		// twin raises for THIS verb instead of the shipped cell-4 one: the
		// plain-verb preservation sentence, and nothing at all on a
		// continuation, whose own flag validation the continuation gate
		// projects.
		if req.Continue {
			return nil
		}
		return []internal.PlanGateResult{{
			ID: "external-state-refused", Applies: true, Failed: true,
			Kind: internal.RefusalStateRefused,
			Detail: fmt.Sprintf(
				"a guarded sync was interrupted while recording state for %q; the previous sync state is preserved inside %s — use --continue to resume it, or --abort to discard it",
				req.Feature, req.Sentinel.Path),
		}}
	}
	if req.Continue {
		return nil
	}
	err := syncCellRefusal(syncVerbPlain, req.Feature, req.Layout, req.Classified)
	return []internal.PlanGateResult{{
		ID: "external-state-refused", Applies: true, Failed: err != nil,
		Kind:   internal.RefusalStateRefused,
		Detail: syncErrTextOrEmpty(err),
	}}
}

func syncErrTextOrEmpty(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

func externalGatesFailed(gates []internal.PlanGateResult) bool {
	for _, g := range gates {
		if g.Applies && g.Failed {
			return true
		}
	}
	return false
}

// externalBasePreflight is I14, projected: it calls firstUnresolvedSelectedBase
// (sync.go), the shipped verifySelectedBasesLocally's own locator, so the
// document publishes the identical verdict the executing route itself would
// reach — never a second implementation of the locator.
func externalBasePreflight(layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection) internal.PlanBasePreflight {
	if sel.Policy.Fetch != internal.SyncFetchDisabled {
		return internal.PlanBasePreflight{}
	}
	entry, ref, found := firstUnresolvedSelectedBase(layout, stack, sel)
	if !found {
		return internal.PlanBasePreflight{Applies: true}
	}
	return internal.PlanBasePreflight{
		Applies: true, Failed: true, Entry: entry, Ref: ref,
		Detail: fmt.Sprintf("base %q for stack entry %q does not resolve locally; drop --no-fetch or fetch manually first", ref, entry),
	}
}

// externalStageFacts derives StageFacts for the --continue route: one
// disclosure row per Remaining entry. External's continuation model has no
// per-entry Git-level "stage" the way a checkout transaction does — every
// remaining entry's own next command is always a rebase, since external
// never pauses mid-entry between a completed rebase and a still-pending
// validation/push the way a checkout transaction's Stage can.
func externalStageFacts(remaining []string) []internal.PlanStageFact {
	facts := make([]internal.PlanStageFact, 0, len(remaining))
	for _, name := range remaining {
		autostash := false
		facts = append(facts, internal.PlanStageFact{
			Entry: name, Stage: "planned", NextCommand: "git rebase",
			RebaseIsNext: true, AutostashApplies: &autostash,
		})
	}
	return facts
}

// ---------------------------------------------------------------------------
// Guard-limit reconciliation (external analogue of internal's
// resolveCheckoutGuardLimits/resolveCheckoutLimitConflicts)
// ---------------------------------------------------------------------------

// originLimit mirrors internal's own unexported helper of the same name: the
// unarmed value ({nil, "none"}) whenever v is nil, the supplied origin
// otherwise.
func originLimit(v *int, origin string) internal.PlanGuardLimit {
	if v == nil {
		return internal.PlanGuardLimit{Value: nil, Origin: "none"}
	}
	return internal.PlanGuardLimit{Value: v, Origin: origin}
}

// externalPersistedGuarded mirrors internal's checkoutRecoveryIsGuarded for
// the external payload: guarded exactly at state_version 3.
func externalPersistedGuarded(payload *internal.SyncRunState) bool {
	return payload != nil && (payload.StateVersion == internal.SyncRunStateGuardedVersion ||
		payload.StateVersion == internal.SyncRunStateTransactionalGuardedVersion || payload.PlanGuarded)
}

// resolveExternalLimit mirrors internal.resolveCheckoutLimit for the
// external route's own persisted carrier, a *internal.SyncRunState rather
// than a *internal.CheckoutTransaction.
func resolveExternalLimit(payload *internal.SyncRunState, guarded bool, persisted, supplied *int) internal.PlanGuardLimit {
	switch {
	case payload == nil:
		return originLimit(supplied, "flags")
	case guarded && persisted != nil:
		return originLimit(persisted, "persisted-transaction")
	case guarded:
		return originLimit(supplied, "flags-persisted-continuation")
	default:
		return originLimit(supplied, "flags-legacy-continuation")
	}
}

func resolveExternalGuardLimits(opts planGuardOptions, payload *internal.SyncRunState, sentinel *internal.GuardedLegacySentinel) internal.PlanGuardLimits {
	if payload == nil && sentinel != nil {
		// §12.8b/§13.2: the cell-4 recovery arm inherits or confirms the
		// sentinel's persisted effective limits, published with the SAME
		// origin an envelope publishes, because the intent block IS the
		// payload the interrupted setup had already committed to. A
		// different supplied value never re-arms the run: it becomes a rank
		// 7 conflict row below, with the persisted value still effective.
		return internal.PlanGuardLimits{
			PerEntry: sentinelLimit(sentinel.MaxReplayPerEntry, opts.MaxPerEntry),
			Total:    sentinelLimit(sentinel.MaxReplayTotal, opts.MaxTotal),
		}
	}
	guarded := externalPersistedGuarded(payload)
	var perEntryPersisted, totalPersisted *int
	if payload != nil {
		perEntryPersisted, totalPersisted = payload.MaxReplayPerEntry, payload.MaxReplayTotal
	}
	return internal.PlanGuardLimits{
		PerEntry: resolveExternalLimit(payload, guarded, perEntryPersisted, opts.MaxPerEntry),
		Total:    resolveExternalLimit(payload, guarded, totalPersisted, opts.MaxTotal),
	}
}

// sentinelLimit is §13.2's per-key table over a sentinel's intent block: a
// persisted value is effective with origin persisted-payload whether this
// invocation confirmed it, supplied a different one (a conflict row, decided
// below) or supplied none at all; an unpersisted key falls back to this
// invocation's own flag.
func sentinelLimit(persisted, supplied *int) internal.PlanGuardLimit {
	if persisted != nil {
		return originLimit(persisted, "persisted-payload")
	}
	return originLimit(supplied, "flags")
}

func externalLimitConflict(key string, persisted *int, persistedOrigin string, supplied *int) *internal.PlanGuardLimitConflict {
	if supplied == nil || persisted == nil || *supplied == *persisted {
		return nil
	}
	return &internal.PlanGuardLimitConflict{Key: key, EffectiveValue: persisted, EffectiveOrigin: persistedOrigin, SuppliedValue: supplied}
}

func resolveExternalLimitConflicts(payload *internal.SyncRunState, sentinel *internal.GuardedLegacySentinel, opts planGuardOptions) []internal.PlanGuardLimitConflict {
	if payload == nil && sentinel != nil {
		var out []internal.PlanGuardLimitConflict
		if c := externalLimitConflict("max_replay_per_entry", sentinel.MaxReplayPerEntry, "persisted-payload", opts.MaxPerEntry); c != nil {
			out = append(out, *c)
		}
		if c := externalLimitConflict("max_replay_total", sentinel.MaxReplayTotal, "persisted-payload", opts.MaxTotal); c != nil {
			out = append(out, *c)
		}
		return out
	}
	if !externalPersistedGuarded(payload) {
		return nil
	}
	var out []internal.PlanGuardLimitConflict
	if c := externalLimitConflict("max_replay_per_entry", payload.MaxReplayPerEntry, "persisted-transaction", opts.MaxPerEntry); c != nil {
		out = append(out, *c)
	}
	if c := externalLimitConflict("max_replay_total", payload.MaxReplayTotal, "persisted-transaction", opts.MaxTotal); c != nil {
		out = append(out, *c)
	}
	return out
}

// externalValidationIdentity is RebasePlanRequest.Validation for the
// external route (§15): external never accepts a --test flag (that flag is
// checkout-only), so its effective command is always config's own
// TestCommand — the fresh route's own frozen-at-birth value, or the
// persisted payload's TestCommand on --continue, mirroring
// handleScopedSyncContinue's/runScopedSync's own "config today, frozen
// henceforth" rule (§7.7).
func externalValidationIdentity(payload *internal.SyncRunState, sentinel *internal.GuardedLegacySentinel, isContinue bool) internal.PlanValidationIdentity {
	command := internal.LoadConfig().TestCommand
	source := "config"
	switch {
	case isContinue && payload != nil:
		command = payload.TestCommand
		source = "persisted-transaction"
	case isContinue && sentinel != nil:
		// §19.2's recovery arm: the frozen validation command is the
		// sentinel's own intent block, never today's config.
		command = sentinel.TestCommand
		source = "persisted-transaction"
	}
	if command == "" {
		return internal.PlanValidationIdentity{Applies: false, Source: "none"}
	}
	return internal.PlanValidationIdentity{Applies: true, Command: command, Source: source, Digest: internal.ValidationDigest(command)}
}

// externalContinuationGate is RebasePlanRequest.ContinuationGate (§13.7a): a
// read-only projection of handleScopedSyncContinue's own dispatch gates,
// never a second implementation of them — the detail sentence comes from
// calling the shipped syncContinueMismatches directly.
func externalContinuationGate(req ExternalPlanInspectionRequest, state internal.ExternalPlanState, payload *internal.SyncRunState, sentinel *internal.GuardedLegacySentinel, stack internal.Stack) internal.PlanContinuationGate {
	policy, changed, push := req.Policy, req.Changed, req.Push
	if payload == nil {
		if !req.Continue {
			return internal.PlanContinuationGate{}
		}
		if sentinel == nil {
			// A continuation with no persisted subject at all: the gate
			// publishes the SHIPPED refusal its executing twin raises, so the
			// rows-less document always names its own cause (§13.7a rule 4).
			// The cell ladder answers first, exactly as the dispatch consults
			// it first; where it stays silent — cells 1 and 7, whose legacy
			// state this route has no payload for — the shipped continuation
			// handler's own sentence is the cause.
			if err := syncCellRefusal(syncVerbContinue, req.Feature, req.Layout, req.Classified); err != nil {
				return internal.PlanContinuationGate{Applies: true, Failed: true, Axis: "state", Detail: err.Error()}
			}
			if !internal.HasSyncState(req.Layout.FeaturePath) {
				return internal.PlanContinuationGate{
					Applies: true, Failed: true, Axis: "state",
					Detail: "nothing to continue — no sync in progress",
				}
			}
			// A `.sync-state.yaml` the classifier decoded but this
			// invocation's own inspector could NOT establish as a resumable
			// subject — a symlinked artefact, one past the read cap, an
			// empty or undecodable document, a non-regular file — leaves the
			// continuation with nothing to filter its remaining work
			// against. RowsAvailable already answers "no" there, so the gate
			// must answer "no" too and say exactly what it saw: a rows-less
			// document that named no cause is the one shape §13.7a rule 4
			// forbids.
			if !externalLegacySubject(state) {
				return internal.PlanContinuationGate{
					Applies: true, Failed: true, Axis: "state",
					Detail: legacySubjectUnavailableDetail(req.Layout, state),
				}
			}
			return internal.PlanContinuationGate{Applies: true}
		}
		// §12.8b: the cell-4 interception owns this document's flag
		// validation, because I20 can no longer see it. The projection
		// raises the SHIPPED I20 sentence its executing twin would raise —
		// composed here, exactly as there, and never a new sentence.
		if syncTriggerFlagSupplied(changed) {
			return internal.PlanContinuationGate{
				Applies: true, Failed: true, Axis: "mismatch", Detail: errSyncModeFlagsNeedV2,
			}
		}
		return internal.PlanContinuationGate{Applies: true}
	}
	if err := syncContinueMismatches(payload, policy, changed, push); err != nil {
		return internal.PlanContinuationGate{Applies: true, Failed: true, Axis: "mismatch", Detail: err.Error()}
	}
	for _, name := range payload.Selected {
		if !internal.HasBranch(stack, name) {
			return internal.PlanContinuationGate{
				Applies: true, Failed: true, Axis: "selection",
				Detail: fmt.Sprintf("selected stack entry %q no longer exists in stack; use --abort", name),
			}
		}
	}
	return internal.PlanContinuationGate{Applies: true}
}

// externalRowsAvailable is RebasePlanRequest.RowsAvailable for this route
// (§13.7a rule 4): the fresh arm needs stack/order/selection resolved; a
// continuation additionally needs a persisted subject to filter its
// remaining work against — the v2/v3 payload of cells 5/7, or the VALID
// guarded-legacy sentinel of the cell-4 recovery arm, whose intent block is
// the payload the interrupted setup had already committed to (§12.8b,
// §19.2). A continuation with neither is the one rows-less continuation
// shape, and its cause is published by the state gate above.
func externalRowsAvailable(insp ExternalPlanInspection, payload *internal.SyncRunState, sentinel *internal.GuardedLegacySentinel) bool {
	resolved := insp.StackErr == nil && insp.SortErr == nil && insp.SelectionErr == nil
	if !resolved {
		return false
	}
	if insp.Continue {
		return payload != nil || sentinel != nil || externalLegacySubject(insp.State)
	}
	return true
}

// legacySubjectUnavailableDetail names, precisely, why the legacy artefact
// beside this continuation is not a resumable subject: the path, the
// presence token this invocation measured, the unreadable reason where the
// presence has one, and the underlying error verbatim where the inspector
// captured one. It invents no verdict — every field is a value
// InspectExternalPlanState already published in state.files — so an operator
// reading blockers[] and state.files sees the same fact twice, never two
// different stories.
func legacySubjectUnavailableDetail(layout externalSyncLayout, state internal.ExternalPlanState) string {
	legacy := state.Files.LegacyState
	path := internal.SyncStatePath(layout.FeaturePath)
	detail := fmt.Sprintf("sync state at %s cannot be resumed: it is %s", path, legacyPresenceWord(legacy))
	if legacy.Err != nil {
		detail += fmt.Sprintf(": %v", legacy.Err)
	}
	return detail + "; inspect it and use --abort to discard it"
}

// legacyPresenceWord renders one presence/reason pair as the phrase the
// detail sentence needs, including the marker case — a backup sentinel this
// invocation could not verify is not a legacy subject either.
func legacyPresenceWord(legacy internal.PlanLegacySyncStateFile) string {
	switch legacy.Presence {
	case internal.PlanPresenceSymlink:
		return "a symlink, not a regular state document"
	case internal.PlanPresenceAbsent:
		return "absent"
	case internal.PlanPresenceNotApplicable:
		return "not applicable to this route"
	case internal.PlanPresenceUnreadable:
		if legacy.UnreadableReason != nil {
			return fmt.Sprintf("unreadable (%s)", *legacy.UnreadableReason)
		}
		return "unreadable"
	default:
		if legacy.MarkerPresent {
			return "an interrupted guarded setup's marker rather than a resumable legacy state"
		}
		return "not a resumable legacy state"
	}
}

// externalLegacySubject reports whether this continuation's subject is a real
// (non-sentinel) legacy `.sync-state.yaml` — the cell-7 arm of §19.2, whose
// resumed subject is the value the classifier already decoded. Its Completed
// list is exactly what RemainingRebaseEntries reads on the legacy route, so
// such a continuation has real remaining rows to publish and is never
// rows-less.
func externalLegacySubject(state internal.ExternalPlanState) bool {
	legacy := state.Files.LegacyState
	return state.Applicable && legacy.Presence == internal.PlanPresenceReadable &&
		legacy.State != nil && !legacy.MarkerPresent
}

// externalFetchPlan enumerates every repo the described route's own fetch
// loop would touch — the whole stack's repos on a legacy route, the
// selection's own repos on a new-mode route — and, per context, its measured
// fetch effect before any fetch runs. It then runs the SAME shared
// suppression ladder internal.checkoutFetchPlan runs
// (internal.ResolveFetchSuppression), so both modes model every §11.2 cause
// with identical row shapes and identical freshness tokens: cause 4
// (fetch-context-indeterminate, reachable here because an external run can
// enumerate several contexts), cause 5 (submodule-reach-indeterminate) and
// cause 6 (local-branch-checked-out). A context whose effect could not be
// established leaves Effect nil, which is disclosure — never a measured
// hazard — but does make a multi-context plan indeterminate, exactly as
// §11.4 requires.
func externalFetchPlan(layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection, newMode bool, caps internal.GitCapabilities) internal.PlanFetchPlan {
	var repos map[string]string
	if newMode {
		sub := internal.Stack{Branches: selectedRealEntries(stack, sel)}
		repos = internal.UniqueRepos(sub, layout.FeaturePath)
	} else {
		repos = internal.UniqueRepos(stack, layout.FeaturePath)
	}
	tokens := make([]string, 0, len(repos))
	for token := range repos {
		tokens = append(tokens, token)
	}
	sort.Strings(tokens)

	plan := internal.PlanFetchPlan{Applies: true}

	// Pass one: establish every context's roots, so the holder inventories
	// below can be built ONCE PER CANONICAL COMMON DIR through
	// internal.BuildPlanHolderIndex — the single holder-index producer — and
	// never once per repo token. Two tokens that are two linked worktrees of
	// one repository share one `git worktree list`.
	type fetchContext struct {
		ctx       internal.PlanFetchContext
		root      string
		commonDir string
		measured  bool
	}
	contexts := make([]fetchContext, 0, len(tokens))
	ids := internal.PlanContextIdentities{}
	need := make([]string, 0, len(tokens))
	for _, token := range tokens {
		root := token
		source := "entry-repo"
		if root == "" {
			root = repos[token]
			source = "worktree"
			if root == "" {
				root = layout.WorktreesRoot
				source = "workspace-repo-root"
			}
		}
		fc := fetchContext{
			ctx: internal.PlanFetchContext{
				RepoToken: token, Root: root, Source: source,
				Candidates: []internal.PlanFetchCandidate{{ContextRoot: root, ContextSource: source}},
			},
			root: root,
		}
		if _, commonDir, err := internal.MeasureContextRoots(root); err == nil {
			fc.ctx.CommonDir = commonDir
			fc.commonDir, fc.measured = commonDir, true
			if _, seen := ids[root]; !seen {
				ids[root] = internal.PlanContextIdentity{ContextID: root, RepoRoot: root, CommonDir: commonDir}
				need = append(need, root)
			}
		}
		contexts = append(contexts, fc)
	}
	holderIndex := internal.BuildPlanHolderIndex(ids, need)

	for _, fc := range contexts {
		if fc.measured {
			// §16 rule 3a: a host below 2.26 cannot produce the ordered
			// inventory at all, so it is never asked for — the capability
			// gate has already refused the document above this point.
			var inv internal.GitConfigInventory
			if caps.CapConfigShowScope {
				inv = internal.ProbeGitConfigInventory(fc.root)
			}
			effect := internal.ResolveFetchEffect(inv, fc.root, fc.commonDir, caps, holderIndex.ByContext[fc.root])
			fc.ctx.Effect = &effect
		}
		plan.Contexts = append(plan.Contexts, fc.ctx)
	}
	sup := internal.ResolveFetchSuppression(plan.Contexts)
	plan.Suppressed, plan.Controlled, plan.Blockers = sup.Suppressed, sup.Controlled, sup.Blockers
	return plan
}

// externalPushFacts is RebasePlanRequest.PushFacts for the external route,
// generalizing internal.checkoutPushFacts (exactly one repo) into N
// contexts, one per repo the selection's own materialized entries touch. It
// is a complete no-op, never touching Git, whenever this invocation does not
// intend to push at all.
func externalPushFacts(push bool, layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection) internal.PlanPushFacts {
	if !push {
		return internal.PlanPushFacts{}
	}
	sub := internal.Stack{Branches: selectedRealEntries(stack, sel)}
	repos := internal.UniqueRepos(sub, layout.FeaturePath)
	if len(repos) == 0 {
		return internal.PlanPushFacts{}
	}
	tokens := make([]string, 0, len(repos))
	for token := range repos {
		tokens = append(tokens, token)
	}
	sort.Strings(tokens)

	caps, _, _ := internal.ProbeGitCapabilities()
	facts := internal.PlanPushFacts{
		Applies: true, Phase: "plan-point",
		Identities:      internal.PlanContextIdentities{},
		Materialization: map[string]string{},
		Remotes:         map[string]internal.PlanPushRemoteFacts{},
	}
	for _, token := range tokens {
		root := token
		if root == "" {
			root = repos[token]
		}
		if root == "" {
			continue
		}
		// The ONE ordered inventory this push context reads (§14.1a rule 7,
		// §22.27a): ResolvePushContext's remote ladder and the mapping read
		// below both consume this single value, and MeasurePushRemoteFacts
		// never probes again. A host below 2.26 asks for nothing.
		var inv internal.GitConfigInventory
		if caps.CapConfigShowScope {
			inv = internal.ProbeGitConfigInventory(root)
		}
		_, commonDir, measureErr := internal.MeasureContextRoots(root)
		if measureErr != nil {
			continue
		}
		ctx, identity, remoteName, err := internal.ResolvePushContext(root, "workspace-repo-root", "materialized", inv, caps)
		if err != nil {
			continue
		}
		remoteFacts := internal.MeasurePushRemoteFacts(ctx.ContextID, commonDir, remoteName, inv, caps)
		facts.Contexts = append(facts.Contexts, ctx)
		facts.Identities[identity.ContextID] = identity
		facts.Materialization[token] = ctx.Materialization
		facts.Remotes[token] = remoteFacts
	}
	return facts
}

// externalPlanRequest is the shared assembly step runExternalPlan needs:
// every RebasePlanRequest member InspectExternalPlan's own measurement pass
// already settled, mirroring internal.checkoutPlanRequest's own assembly
// field-for-field for the external route.
func externalPlanRequest(req ExternalPlanInspectionRequest, insp ExternalPlanInspection, fetchOutcome internal.PlanFetchOutcome) internal.RebasePlanRequest {
	payload := req.Classified.Payload
	sentinel := req.resumableSentinel()
	route := externalEffectiveRoute(req, payload)
	rowsAvailable := externalRowsAvailable(insp, payload, sentinel)

	var stackPtr *internal.Stack
	if rowsAvailable {
		s := insp.Stack
		stackPtr = &s
	}

	push := req.Push
	pushSource := "flag"
	switch {
	case req.Continue && payload != nil:
		push = payload.Push
		pushSource = "persisted-transaction"
	case req.Continue && sentinel != nil:
		// The recovery arm's intent block is the run's own committed
		// provenance, exactly as a payload is on the envelope arm.
		push = sentinel.Push
		pushSource = "persisted-transaction"
	}

	return internal.RebasePlanRequest{
		Layout:                    planLayout(req.Layout, req.Ws.RepoRoot),
		Mode:                      internal.ModeExternal,
		Feature:                   req.Feature,
		Workspace:                 externalWorkspace(req.Ws),
		Route:                     route,
		RequestedRoute:            externalRequestedRoute(req.NewMode, route),
		RouteTriggers:             externalRouteTriggers(req.Changed),
		Invocation:                "plan-only",
		Policy:                    req.Policy,
		PolicyFetchDefaultApplied: !req.Changed["fetch"] && !req.Changed["no-fetch"],
		Push:                      push,
		PushSource:                pushSource,
		Guard:                     req.checkoutGuard(),
		Limits:                    insp.Limits,
		LimitConflicts:            insp.LimitConflicts,
		Validation:                externalValidationIdentity(payload, sentinel, req.Continue),
		Approve:                   req.Opts.Approve,
		Stack:                     stackPtr,
		Order:                     insp.Order,
		SortErr:                   insp.SortErr,
		StackErr:                  insp.StackErr,
		Selection:                 insp.Selection,
		SelectionResolved:         insp.SelectionResolved,
		SelectionErr:              insp.SelectionErr,
		RowsAvailable:             rowsAvailable,
		Continue:                  req.Continue,
		Remaining:                 insp.Remaining,
		StageFacts:                insp.StageFacts,
		Changed:                   req.Changed,
		ContinuationGate:          externalContinuationGate(req, insp.State, payload, sentinel, insp.Stack),
		Fetch:                     fetchOutcome,
		FetchPlan:                 insp.FetchPlan,
		PushFacts:                 internal.RefreshPushTrackingRefs(externalPushFacts(push, req.Layout, insp.Stack, insp.Selection), fetchOutcome),
		BasePreflight:             externalPreflightWithCompletionGate(req, insp, push, rowsAvailable),
		Version:                   insp.Version,
		Capabilities:              insp.Capabilities,
		ExternalState:             insp.State,
		Gates:                     insp.Gates,
	}
}

// externalBasePreflight is insp.BasePreflight, plus the ONE cell §7.1's rank-4
// rule 2 adds for the external completion gate (§13.5, §13.7a rule 15,
// §22.12b (iii)).
//
// The gate `Sync incomplete; stale stack edges remain:` is a POSTCONDITION:
// it runs AFTER the executor's rebases, so on any document that still has a
// rebase row the answer this invocation would give is not yet decided and the
// stale edge is published as the row's own `ancestry` and nothing more. In
// exactly one cell — a ROWS-LESS PUSH-ONLY continuation, where no rebase of
// this invocation can change the answer — the projection is total, and the
// document publishes it as rank 4 `preflight-refused` with the shipped
// sentences byte for byte.
//
// staleStackEdgesFiltered is evaluated in no other cell of this route.
func externalPreflightWithCompletionGate(req ExternalPlanInspectionRequest, insp ExternalPlanInspection, push, rowsAvailable bool) internal.PlanBasePreflight {
	if insp.BasePreflight.Failed || !req.Continue || !push {
		return insp.BasePreflight
	}
	if rowsAvailable && len(insp.Remaining) > 0 {
		return insp.BasePreflight // a rebase row remains: the postcondition is not yet decided
	}
	stale := staleStackEdgesFiltered(req.Layout.WorktreesRoot, insp.Stack, nil)
	if len(stale) == 0 {
		return insp.BasePreflight
	}
	detail := "Sync incomplete; stale stack edges remain:"
	for _, edge := range stale {
		detail += "\n  [!] " + edge
	}
	return internal.PlanBasePreflight{Applies: true, Failed: true, Detail: detail}
}

// externalPlanArgs bundles the measurement inputs both runExternalPlan and
// buildGuardedExternalPlan share, so a guarded execution's own admission
// plan (built to feed internal.EvaluatePlanGuard) and its --plan twin are
// always the product of the identical pipeline.
type externalPlanArgs struct {
	Feature  string
	Layout   externalSyncLayout
	Ws       internal.Workspace
	Policy   internal.SyncRunPolicy
	NewMode  bool
	Push     bool
	Verbose  bool
	Changed  map[string]bool
	Opts     planGuardOptions
	State    internal.SyncExternalState
	Continue bool

	// Sentinel is the §19.2 dispatch's own cell-4 sentinel view, threaded
	// straight into ExternalPlanInspectionRequest.Sentinel. It is the zero
	// value everywhere else.
	Sentinel internal.GuardedLegacySentinelView

	// PersistedGuarded is threaded straight into
	// ExternalPlanInspectionRequest.PersistedGuarded (§13.6 rule 4d). It is
	// false on every fresh route and on the plan-only route's own
	// measurement (a --plan never adjudicates; it only describes), and true
	// only when a guarded executor is resuming an already-guarded persisted
	// run.
	PersistedGuarded bool
}

// buildExternalPlan runs InspectExternalPlan, fetches wherever the described
// route's own policy would (writing every prose/child byte to prose, which
// callers already route to cmd.ErrOrStderr() on the plan-only route or to
// the shipped stdout/stderr pair on a guarded execution's own admission
// pass), and returns the fully built document. It never renders and never
// evaluates the guard: both are the caller's own responsibility.
func externalPlanInspectionRequest(args externalPlanArgs) ExternalPlanInspectionRequest {
	return ExternalPlanInspectionRequest{
		Feature: args.Feature, Layout: args.Layout, Ws: args.Ws, Opts: args.Opts, Policy: args.Policy,
		NewMode: args.NewMode, Push: args.Push, Verbose: args.Verbose, Changed: args.Changed,
		Continue: args.Continue, Classified: args.State, PersistedGuarded: args.PersistedGuarded,
		Sentinel: args.Sentinel,
	}
}

// inspectExternalPlanFor is the ONE InspectExternalPlan call an invocation
// makes (§10.7 rule 1a, §16.1): every consumer below — the shipped I14
// refusal composer, the guard seam, the document build and the executor —
// reads the value it returns instead of re-probing. It is the reason a
// guarded route's own prelude no longer re-loads the stack or re-sorts it.
func inspectExternalPlanFor(args externalPlanArgs) ExternalPlanInspection {
	return InspectExternalPlan(externalPlanInspectionRequest(args))
}

// buildExternalPlanFrom performs the fetch (where the described route
// fetches) and the document build over an ALREADY-produced inspection, so
// no caller inspects twice.
func buildExternalPlanFrom(args externalPlanArgs, insp ExternalPlanInspection, prose io.Writer) (internal.RebasePlan, internal.RebasePlanRequest, error) {
	req := externalPlanInspectionRequest(args)

	var fetchOutcome internal.PlanFetchOutcome
	if !args.Continue && args.Policy.Fetch == internal.SyncFetchEnabled && insp.FetchPlan.Applies &&
		len(insp.FetchPlan.Blockers) == 0 && externalRowsAvailable(insp, args.State.Payload, req.resumableSentinel()) &&
		!externalGatesFailed(insp.Gates) && !insp.BasePreflight.Failed {
		if args.NewMode {
			fetchOutcome = fetchScopedReposTo(prose, prose, args.Layout, insp.Stack, insp.Selection, args.Verbose, insp.FetchPlan)
		} else {
			fetchOutcome = fetchStackReposTo(prose, prose, args.Layout, insp.Stack, args.Verbose, insp.FetchPlan)
		}
	}

	planReq := externalPlanRequest(req, insp, fetchOutcome)
	plan, err := internal.BuildRebasePlan(planReq)
	return plan, planReq, err
}

// buildExternalPlan is the plan-only route's one-shot inspect-then-build.
func buildExternalPlan(args externalPlanArgs, prose io.Writer) (internal.RebasePlan, internal.RebasePlanRequest, ExternalPlanInspection, error) {
	insp := inspectExternalPlanFor(args)
	plan, planReq, err := buildExternalPlanFrom(args, insp, prose)
	return plan, planReq, insp, err
}

// runExternalPlan is the external route's plan-only dispatch (spec §13.7a):
// it never mutates, describes either the fresh or the --continue route
// depending on cont, and fetches wherever that described route's own policy
// would fetch — writing every fetch/prose byte to cmd.ErrOrStderr(), never
// cmd.OutOrStdout(), so stdout carries the document alone.
func runExternalPlan(cmd *cobra.Command, feature string, layout externalSyncLayout, ws internal.Workspace, policy internal.SyncRunPolicy, newMode, push, verbose bool, changed map[string]bool, opts planGuardOptions, state internal.SyncExternalState, cont bool) error {
	prose := cmd.ErrOrStderr()
	printSyncModeHeaderTo(prose, policy)

	plan, _, _, err := buildExternalPlan(externalPlanArgs{
		Feature: feature, Layout: layout, Ws: ws, Policy: policy, NewMode: newMode,
		Push: push, Verbose: verbose, Changed: changed, Opts: opts, State: state, Continue: cont,
		Sentinel: externalPlanSentinelView(layout, feature, state),
	}, prose)
	if err != nil {
		return err
	}
	return renderPlanDocument(cmd, plan, opts.JSON)
}

// externalPlanSentinelView is the plan route's own ONE read of the §13.6
// rule 2c sentinel view, taken only on cell 4 — the single cell §19.2 lets
// anything consult it — so a --plan describes the same subject its executing
// twin would resume. It adjudicates nothing: the value is threaded into the
// inspection exactly as the executing dispatch threads its own already-read
// view, and no other cell reads a sentinel at all.
func externalPlanSentinelView(layout externalSyncLayout, feature string, state internal.SyncExternalState) internal.GuardedLegacySentinelView {
	if state.Cell != 4 {
		return internal.GuardedLegacySentinelView{}
	}
	return internal.InspectGuardedLegacySentinel(layout.FeaturePath, feature)
}

// buildGuardedExternalPlan is a guarded execution's own pre-mutation
// admission pass (spec §4.6, §7): the identical InspectExternalPlan +
// externalPlanRequest + BuildRebasePlan pipeline runExternalPlan itself
// uses, so a guarded execution is refused by exactly the verdict its own
// --plan twin would report, followed by internal.EvaluatePlanGuard's own
// admission predicate. Unlike the plan-only route it writes its prose
// straight to the shipped stdout/stderr pair (out/errw), since a guarded
// execution that passes admission goes on to print the identical shipped
// bytes an unguarded run would. The returned RebasePlanRequest is
// newPlanGuardRun's own frozen-at-birth request: a guarded executor never
// rebuilds it a second time.
func buildGuardedExternalPlan(out, errw io.Writer, args externalPlanArgs, insp ExternalPlanInspection) (internal.RebasePlan, internal.RebasePlanRequest, error) {
	plan, planReq, err := buildExternalPlanFrom(args, insp, errw)
	if err != nil {
		return internal.RebasePlan{}, planReq, err
	}
	if err := syncSnapshotBarrier(args.Layout.FeaturePath); err != nil {
		return plan, planReq, err
	}
	if err := internal.EvaluatePlanGuard(plan, args.Opts.checkoutGuardPersisted(args.PersistedGuarded)); err != nil {
		return plan, planReq, err
	}
	return plan, planReq, nil
}

// legacySelectionFromOrder is the FULL-STACK legacy universe of §13.3: every
// entry of the current stack, in this invocation's one TopoSort order. It is
// the selection the cell-4 recovery arm resumes, because a legacy run never
// narrowed its universe in the first place — the shipped legacy executor
// selects every name — and the sentinel's own intent block is a full-stack
// universe by construction (§13.6 rule 2c).
func legacySelectionFromOrder(stack internal.Stack, order []internal.StackEntry, policy internal.SyncRunPolicy, feature string, mode internal.WorkspaceMode) (internal.SyncSelection, error) {
	return internal.ResolveSyncSelectionFromOrder(stack, order, policy, internal.SyncSelectionOpts{
		Mode:    mode,
		NewMode: false,
		Feature: feature,
	})
}

// sentinelRemaining projects the cell-4 recovery arm's remaining work: the
// sentinel's own PendingIntent, in the selection's execution order, keeping
// only names the current stack still carries. A name the operator removed
// from stack.yaml between the crash and the resume is silently absent from
// the remaining set — it is not a rebase this invocation can perform — and
// is never invented back into the plan.
func sentinelRemaining(sentinel *internal.GuardedLegacySentinel, sel internal.SyncSelection) []string {
	pending := make(map[string]bool, len(sentinel.PendingIntent))
	for _, name := range sentinel.PendingIntent {
		pending[name] = true
	}
	out := make([]string, 0, len(sentinel.PendingIntent))
	for _, e := range sel.Entries {
		if pending[e.Name] {
			out = append(out, e.Name)
		}
	}
	return out
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

// ---------------------------------------------------------------------------
// runSyncExecute drives the REAL package-level cli.Execute() entrypoint
// (root.go) — the one place a returned RunE error reaches stderr exactly as
// shipped: cobra's own "Error: " line plus its full Usage/Flags dump (syncCmd
// never sets SilenceUsage), followed by root.go's own trailing duplicate
// message line (its hardcoded fmt.Fprintln(os.Stderr, err)). syncExecute
// (sync_golden_test.go) is NOT a substitute here: it builds syncCmd()
// directly (skipping the "sync" subcommand lookup a real "tws sync ..."
// invocation performs) and forces SilenceErrors/SilenceUsage=true, so its
// stderr shape never matches production's. Every test in this file that
// asserts the plan-guard marker's exact form or position uses this helper.
func runSyncExecute(t *testing.T, args ...string) (stdout, stderr string, exit int) {
	t.Helper()
	oldArgs := os.Args
	t.Cleanup(func() { os.Args = oldArgs })
	os.Args = append([]string{"tws", "sync"}, args...)
	stdout, stderr = syncCaptureStreams(t, func() {
		exit = Execute()
	})
	return stdout, stderr, exit
}

// planGuardMarkerRe is spec.md §6.4's marker grammar:
// "^plan-guard: <kind>: <sanitized-detail>$", anchored to one physical line.
var planGuardMarkerRe = regexp.MustCompile(`(?m)^plan-guard: [a-z][a-z-]*: .*$`)

// ---------------------------------------------------------------------------
// §3.4 incompatibility matrix
// ---------------------------------------------------------------------------

// TestSyncPlanGuard_IncompatibilityMatrix exercises every row of spec §3.4 in
// its documented evaluation order, with the exact byte-for-byte message each
// row requires: exit 1, no stdout, and (per the row) the "--json"/"--abort"/
// "--max-replay-*"/"--approve-plan" wording verbatim. Row 6 additionally
// proves the --json rule is evaluated strictly before the --abort rows,
// exactly as the row's own annotation states.
func TestSyncPlanGuard_IncompatibilityMatrix(t *testing.T) {
	fortoken := strings.Repeat("a", 64)
	for _, tc := range []struct {
		name string
		args []string
		want string
	}{
		{"row1-json-without-plan", []string{"feature", "--json"}, "--json requires --plan"},
		{"row2-plan-with-abort", []string{"feature", "--plan", "--abort"}, "--plan cannot be combined with --abort"},
		{"row3-max-per-entry-with-abort", []string{"feature", "--max-replay-per-entry", "5", "--abort"}, "--max-replay-per-entry cannot be combined with --abort"},
		{"row4-max-total-with-abort", []string{"feature", "--max-replay-total", "5", "--abort"}, "--max-replay-total cannot be combined with --abort"},
		{"row5-approve-plan-with-abort", []string{"feature", "--approve-plan", fortoken, "--abort"}, "--approve-plan cannot be combined with --abort"},
		{"row6-json-with-abort-json-checked-first", []string{"feature", "--json", "--abort"}, "--json requires --plan"},
		{"row7-max-per-entry-negative", []string{"feature", "--max-replay-per-entry", "-1"}, "--max-replay-per-entry must be zero or greater"},
