func testSyncTransactionArchivedEntryRollsBackAfterLoad(t *testing.T, f *scopedFixture, stack internal.Stack) {
	for i := range stack.Branches {
		if stack.Branches[i].Name == "child" {
			stack.Branches[i].Archived = true
		}
	}
	if err := internal.SaveStack(f.featurePath, stack); err != nil {
		t.Fatal(err)
	}
	beforeRefs := gitOutput(t, f.repo, "for-each-ref", "--format=%(refname) %(objectname)", "refs/heads")
	beforeStack, err := os.ReadFile(internal.StackPath(f.featurePath))
	if err != nil {
		t.Fatal(err)
	}
	reached := false
	internal.SyncTransactionStepHook = func(step string) error {
		if step == "action-observed:rebase:child" {
			reached = true
			return errors.New("stop after archived row")
		}
		return nil
	}
	t.Cleanup(func() { internal.SyncTransactionStepHook = nil })
	stdout, stderr, exit := runSync(t, f.feature, "--no-fetch")
	if exit == 0 || !reached {
		t.Fatalf("archived row did not execute: %d\n%s\n%s", exit, stdout, stderr)
	}
	internal.SyncTransactionStepHook = nil
	f.detachGuard(t)
	stdout, stderr, exit = runSync(t, f.feature, "--abort")
	if exit != 0 {
		t.Fatalf("abort archived row: %d\n%s\n%s", exit, stdout, stderr)
	}
	if after := gitOutput(t, f.repo, "for-each-ref", "--format=%(refname) %(objectname)", "refs/heads"); after != beforeRefs {
		t.Fatal("archived and materialized refs were not restored")
	}
	afterStack, err := os.ReadFile(internal.StackPath(f.featurePath))
	if err != nil || string(afterStack) != string(beforeStack) {
		t.Fatalf("archived metadata was not restored exactly: %v", err)
	}
	if got := gitOutput(t, f.repo, "symbolic-ref", "--short", "HEAD"); got != "master" {
		t.Fatalf("archived computation context remained on %s", got)
	}
}

package internal

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

type HealthIssue struct {
	Branch   string
	Problem  string
	Hint     string
	Severity CheckoutSeverity // "" is treated as a warning
}

// EffectiveSeverity resolves the zero value to a warning, so every producer
// that predates the Severity field renders and counts exactly as before.
func (h HealthIssue) EffectiveSeverity() CheckoutSeverity {
	if h.Severity == "" {
		return SeverityWarning
	}
	return h.Severity
}

func (h HealthIssue) String() string {
	s := fmt.Sprintf("  %s %s: %s", severityIcon(h.EffectiveSeverity()), h.Branch, h.Problem)
	if h.Hint != "" {
		s += fmt.Sprintf("\n      %s", h.Hint)
	}
	return s
}

// CountHealthIssues counts only issues that need attention. Informational
// findings print but never change a total or an exit status.
func CountHealthIssues(issues []HealthIssue) int {
	n := 0
	for _, issue := range issues {
		switch issue.EffectiveSeverity() {
		case SeverityWarning, SeverityError:
			n++
		}
	}
	return n
}

func cutoffEvidenceValue(value, absent string) string {
	if value == "" {
		return absent
	}
	lower := strings.ToLower(value)
	if (len(lower) == 40 || len(lower) == 64) && validLowerHexOID(lower, len(lower)) {
		return shortSHA(lower)
	}
	return ancestrySanitize(value, ancestrySanitizeLimit)
}

func cutoffEvidenceLine(raw, effective string, source SyncCutoffSource, validity SyncCutoffValidity, reason SyncCutoffReason) string {
	raw = cutoffEvidenceValue(raw, "<absent>")
	if validity == "" {
		return ""
	}
	return fmt.Sprintf(
		"cutoff evidence: raw=%q effective=%q source=%s validity=%s reason=%s",
		raw,
		cutoffEvidenceValue(effective, "<none>"),
		ancestrySanitize(string(source), ancestrySanitizeLimit),
		ancestrySanitize(string(validity), ancestrySanitizeLimit),
		ancestrySanitize(string(reason), ancestrySanitizeLimit),
	)
}

// AncestryHealthIssues projects evaluated stack edges into external doctor
// issues. Repository-unavailable edges collapse to a single feature-scoped
// issue so an unresolvable repository cannot flood the output. Per-edge notes
// are projected too — including for `current` edges, whose base a sync path
// may still resolve differently — always as informational and never counted.
func AncestryHealthIssues(res StackRepoResolution, edges []StackEdge) []HealthIssue {
	var issues []HealthIssue
	repoUnavailableReported := false
	for _, edge := range edges {
		if edge.Status != AncestryStatusCurrent {
			problem := fmt.Sprintf("ancestry %s: %s", ancestryDisplayStatus(edge.Status), edge.Reason)
			if edge.Reason == ReasonRepoUnavailable {
				if !repoUnavailableReported {
					repoUnavailableReported = true
					issues = append(issues, HealthIssue{
						Branch:   "stack",
						Problem:  problem,
						Hint:     edge.Guidance,
						Severity: edge.Severity,
					})
				}
			} else {
				issues = append(issues, HealthIssue{
					Branch:   edge.Name,
					Problem:  problem,
					Hint:     edge.Guidance,
					Severity: edge.Severity,
				})
			}
		}
		if evidence := cutoffEvidenceLine(
			edge.LastBaseSHA, edge.EffectiveCutoff,
			edge.CutoffSource, edge.CutoffValidity, edge.CutoffReason,
		); evidence != "" {
			issues = append(issues, HealthIssue{
				Branch: edge.Name, Problem: evidence, Severity: SeverityInfo,
			})
		}
		for _, note := range edge.Notes {
			issues = append(issues, HealthIssue{
				Branch:   edge.Name,
				Problem:  fmt.Sprintf("ancestry note: %s", note.Kind),
				Hint:     note.Detail,
				Severity: SeverityInfo,
			})
		}
	}
	if res.Alternate != "" {
		issues = append(issues, HealthIssue{
			Branch: "stack",
			Problem: fmt.Sprintf("%s: ancestry evaluated against %s (source: %s)",
				RepoSourceMismatchLabel, ancestrySanitize(res.RepoDir, ancestryPathLimit), res.Source),
			Hint: fmt.Sprintf("the workspace also resolves to %s; check TWS_ROOT or the configured workspace path",
				ancestrySanitize(res.Alternate, ancestryPathLimit)),
			Severity: SeverityInfo,
		})
	}
	return issues
}

// CheckWorktreeBranch verifies the worktree is on the expected branch.
func CheckWorktreeBranch(worktreePath, expectedBranch string) *HealthIssue {
	out, err := exec.Command("git", "-C", worktreePath, "rev-parse", "--abbrev-ref", "HEAD").Output()
	if err != nil {
		return &HealthIssue{
			Branch:  expectedBranch,
			Problem: "could not determine current branch",
			Hint:    fmt.Sprintf("check worktree at %s", worktreePath),
		}
	}

	actual := strings.TrimSpace(string(out))
	if actual != expectedBranch {
		return &HealthIssue{
			Branch:  expectedBranch,
			Problem: fmt.Sprintf("on branch %q, expected %q", actual, expectedBranch),
			Hint:    fmt.Sprintf("run: cd %s && git checkout %s", worktreePath, expectedBranch),
		}
	}
	return nil
}

// CheckWorktreeDirty checks if the worktree has uncommitted changes.
func CheckWorktreeDirty(worktreePath, branch string) *HealthIssue {
	out, err := exec.Command("git", "-C", worktreePath, "status", "--porcelain").Output()
	if err != nil {
		return nil
	}
	if len(strings.TrimSpace(string(out))) > 0 {
		return &HealthIssue{
			Branch:  branch,
			Problem: "has uncommitted changes",
			Hint:    "commit or stash changes before syncing",
		}
	}
	return nil
}

// CheckWorktreeInjectLinks checks if inject symlinks are present.
// Respects the configured inject_into target path.
func CheckWorktreeInjectLinks(featurePath, worktreePath, branch string) *HealthIssue {
	injectDir := InjectPath(featurePath)
	if _, err := os.Stat(injectDir); os.IsNotExist(err) {
		return nil // no inject dir, nothing to check
	}

	// Resolve inject target (respects inject_into config)
	targetBase := worktreePath
	injectInto := ResolveInjectInto("")
	if injectInto != "" && injectInto != "." {
		targetBase = filepath.Join(worktreePath, injectInto)
	}

	missing := 0
	_ = filepath.Walk(injectDir, func(srcPath string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		relPath, err := filepath.Rel(injectDir, srcPath)
		if err != nil {
			return nil
		}
		destPath := filepath.Join(targetBase, relPath)
		if _, err := os.Lstat(destPath); os.IsNotExist(err) {
			missing++
		}
		return nil
	})

	if missing > 0 {
		return &HealthIssue{
			Branch:  branch,
			Problem: fmt.Sprintf("%d inject file(s) missing", missing),
			Hint:    fmt.Sprintf("run: tws inject <feature> %s", branch),
		}
	}
	return nil
}

// CheckFeatureHealth runs all health checks for a feature and returns issues.
func CheckFeatureHealth(featurePath string) []HealthIssue {
	var issues []HealthIssue

	stack, err := LoadStack(featurePath)
	if err != nil {
		return issues
	}

	for _, entry := range stack.Branches {
		wtPath := filepath.Join(featurePath, "worktrees", entry.Name)
		if _, err := os.Stat(wtPath); os.IsNotExist(err) {
			continue // archived, skip
		}

		if issue := CheckWorktreeBranch(wtPath, entry.GitBranch()); issue != nil {
			issues = append(issues, *issue)
		}
		if issue := CheckWorktreeDirty(wtPath, entry.Name); issue != nil {
			issues = append(issues, *issue)
		}
		if issue := CheckWorktreeInjectLinks(featurePath, wtPath, entry.Name); issue != nil {
			issues = append(issues, *issue)
		}
	}

	return issues
}

// ExternalSyncRecoveryHealthIssues projects only transactional external sync
// recovery. Legacy/no-state doctor output remains unchanged.
func ExternalSyncRecoveryHealthIssues(feature, featurePath string, suppressCompatibility bool) []HealthIssue {
	state := ClassifyExternalSyncState(featurePath, SyncClassifyOpts{AlwaysReadGuard: true})
	if state.PayloadErr != nil || state.PayloadSymlink {
		if suppressCompatibility {
			return nil
		}
		return []HealthIssue{{
			Branch:   "sync",
			Problem:  "sync recovery evidence is unreadable, corrupt, or unsupported",
			Hint:     "preserve and inspect " + state.PayloadPath,
			Severity: SeverityError,
		}}
	}
	if state.Payload == nil || state.Payload.Transaction == nil {
		return nil
	}
	recovery := projectTransactionalSyncRecovery(feature, state.Payload.Transaction)
	issue := HealthIssue{
		Branch:   "sync",
		Problem:  recovery.message,
		Hint:     recovery.guidance,
		Severity: SeverityWarning,
	}
	if state.GuardLive {
		if recovery.kind == "validator-mutated" {
			issue.Severity = SeverityWarning
		} else {
			issue.Severity = SeverityInfo
		}
		issue.Hint = liveTransactionalSyncGuidance(recovery)
	}
	return []HealthIssue{issue}
}

func ExternalSyncValidatorMutationPresent(featurePath string) bool {
	state := ClassifyExternalSyncState(featurePath, SyncClassifyOpts{AlwaysReadGuard: true})
	if state.Payload == nil {
		return false
	}
	_, mutated := SyncTransactionValidatorMutated(state.Payload.Transaction)
	return mutated
}

