func TestRebasePlanner_ResolvePushContext(t *testing.T) {
	t.Run("ResolvesIdentityHeadBranchAndRemoteOverARealRepo", func(t *testing.T) {
		repo := rppRepo(t)
		gitInTest(t, repo, "remote", "add", "origin", "https://example.invalid/repo.git")
		inv := ProbeGitConfigInventory(repo)

		ctx, identity, remoteName, err := ResolvePushContext(repo, "cli-flag", "materialized", inv, rpnCaps())
		if err != nil {
			t.Fatalf("ResolvePushContext: %v", err)
		}
		if identity.ContextID == "" || identity.RepoRoot == "" {
			t.Fatalf("identity = %+v, want populated ContextID/RepoRoot", identity)
		}
		if ctx.ContextID == nil || *ctx.ContextID != identity.ContextID {
			t.Fatalf("ctx.ContextID = %v, want %q", ctx.ContextID, identity.ContextID)
		}
		if ctx.RepoRoot != identity.RepoRoot {
			t.Fatalf("ctx.RepoRoot = %q, want %q", ctx.RepoRoot, identity.RepoRoot)
		}
		if ctx.Source != "cli-flag" {
			t.Fatalf("ctx.Source = %q, want the passed-through cli-flag", ctx.Source)
		}
		if ctx.Materialization != "materialized" {
			t.Fatalf("ctx.Materialization = %q, want the passed-through materialized", ctx.Materialization)
		}
		if remoteName != "origin" {
			t.Fatalf("remoteName = %q, want origin", remoteName)
		}
	})

	t.Run("PropagatesEstablishContextIdentityErrorWithZeroResults", func(t *testing.T) {
		notRepo := rppNotARepo(t)
		ctx, identity, remoteName, err := ResolvePushContext(notRepo, "cli-flag", "materialized", GitConfigInventory{}, rpnCaps())
		if err == nil {
			t.Fatal("expected an error outside any repository")
		}
		if ctx != (PlanPushContext{}) || identity != (PlanContextIdentity{}) || remoteName != "" {
			t.Fatalf("expected every result zeroed on error, got ctx=%+v identity=%+v remoteName=%q", ctx, identity, remoteName)
		}
	})
}

func TestRebasePlanner_MeasurePushRemoteFacts(t *testing.T) {
	t.Run("RemoteFoundPopulatesRefspecsAndLeavesTrackingFieldsAtZeroValue", func(t *testing.T) {
		repo := rppRepo(t)
		gitInTest(t, repo, "remote", "add", "origin", "https://example.invalid/repo.git")
		contextID := "ctx-1"
		inv := ProbeGitConfigInventory(repo)

		facts := MeasurePushRemoteFacts(&contextID, repo, "origin", inv, rpnCaps())
		if facts.ContextID != &contextID {
			t.Fatal("expected the same *string pointer to be threaded through verbatim")
		}
		if facts.CommonDir != repo {
			t.Fatalf("CommonDir = %q, want %q", facts.CommonDir, repo)
		}
		if facts.RemoteName != "origin" {
			t.Fatalf("RemoteName = %q, want origin", facts.RemoteName)
		}
		if !facts.MappingReadOK {
			t.Fatal("expected MappingReadOK=true")
		}
		if !facts.RemoteExists {
			t.Fatal("expected RemoteExists=true")
		}
		if len(facts.FetchRefspecs) == 0 {
			t.Fatal("expected at least one default fetch refspec for a newly added remote")
		}
		if facts.TrackingPhase != "not-applicable" {
			t.Fatalf("TrackingPhase = %q, want not-applicable (RefreshPushTrackingRefs alone sets it further)", facts.TrackingPhase)
		}
		if facts.TrackingReadOK {
			t.Fatal("expected TrackingReadOK to stay false: only RefreshPushTrackingRefs ever sets it")
		}
		if facts.TrackingRefs != nil {
			t.Fatal("expected TrackingRefs to stay nil until RefreshPushTrackingRefs runs")
		}
		if facts.FetchedThisRun {
			t.Fatal("expected FetchedThisRun to stay false")
		}
	})

	t.Run("RemoteNotFoundStillReportsMappingReadOK", func(t *testing.T) {
		repo := rppRepo(t)
		contextID := "ctx-1"
		facts := MeasurePushRemoteFacts(&contextID, repo, "ghost", ProbeGitConfigInventory(repo), rpnCaps())
		if !facts.MappingReadOK {
			t.Fatal("expected MappingReadOK=true even when the remote itself does not exist")
		}
		if facts.RemoteExists {
			t.Fatal("expected RemoteExists=false")
		}
		if facts.FetchRefspecs == nil || len(facts.FetchRefspecs) != 0 {
			t.Fatalf("FetchRefspecs = %v, want a non-nil empty slice when the remote was not found", facts.FetchRefspecs)
		}
	})

	// §22.24-adjacent, §14.1a rule 5a: MappingReadOK is a claim about TWO
	// halves — an established context identity and a READABLE ordered config
	// inventory. Either one missing is the `unknown` lease cell, never the
	// null-OID `absent` one.
	t.Run("UnreadableInventoryIsNotAReadMapping", func(t *testing.T) {
		repo := rppRepo(t)
		contextID := "ctx-1"
		facts := MeasurePushRemoteFacts(&contextID, repo, "origin", GitConfigInventory{Available: false}, rpnCaps())
		if facts.MappingReadOK {
			t.Fatal("MappingReadOK = true over an UNREADABLE inventory: nothing was read")
		}
		if facts.RemoteExists {
			t.Fatal("RemoteExists = true over an unreadable inventory")
		}
		if facts.FetchRefspecs == nil || len(facts.FetchRefspecs) != 0 {
			t.Fatalf("FetchRefspecs = %v, want a non-nil empty slice", facts.FetchRefspecs)
		}
		// Round trip: those facts really do produce §14.2's `unknown` cell.
		lease := ResolvePushLease(facts, "main")
		want := PlanLease{Mode: "implicit-remote-tracking", Expectation: "unknown", ExpectedSHAFreshness: "possibly-stale"}
		if lease != want {
			t.Fatalf("lease = %+v, want the cell-5 unknown lease %+v", lease, want)
		}
	})

	t.Run("UnestablishedContextIdentityIsNotAReadMapping", func(t *testing.T) {
		repo := rppRepo(t)
		gitInTest(t, repo, "remote", "add", "origin", "https://example.invalid/repo.git")
		facts := MeasurePushRemoteFacts(nil, repo, "origin", ProbeGitConfigInventory(repo), rpnCaps())
		if facts.MappingReadOK {
			t.Fatal("MappingReadOK = true with a nil ContextID: the context was never established")
		}
		if lease := ResolvePushLease(facts, "main"); lease.Expectation != "unknown" {
			t.Fatalf("lease.Expectation = %q, want unknown", lease.Expectation)
		}
	})

	// A REAL probe failure, not an injected struct: the inventory is read
	// from a directory that is not a repository at all.
	t.Run("RealInventoryProbeFailureRoundTripsToTheUnknownCell", func(t *testing.T) {
		// A directory that does not exist at all: `git -C <path> config
		// --list --show-scope -z` cannot run there, so the ordered read
		// really fails rather than being injected as failed.
		missing := filepath.Join(rppNotARepo(t), "no-such-directory")
		inv := ProbeGitConfigInventory(missing)
		if inv.Available {
			t.Fatalf("the ordered inventory must fail for a nonexistent directory, got %+v", inv)
		}
		notRepo := missing
		contextID := "ctx-1"
		facts := MeasurePushRemoteFacts(&contextID, notRepo, "origin", inv, rpnCaps())
		if facts.MappingReadOK {
			t.Fatalf("MappingReadOK = true over a REAL failed inventory read: %+v", facts)
		}
		lease := ResolvePushLease(facts, "main")
		if lease.Expectation != "unknown" || lease.ExpectedRef != nil || lease.ExpectedSHA != nil {
			t.Fatalf("lease = %+v, want the unknown cell with null ref and sha", lease)
		}
		if lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("freshness = %q, want possibly-stale", lease.ExpectedSHAFreshness)
		}
	})
}

func TestRebasePlanner_RefreshPushTrackingRefs(t *testing.T) {
	// fetchedOK builds a PlanFetchOutcome describing one attempted, successful
	// fetch that contacted `origin` in commonDir.
	fetchedOK := func(commonDir string) PlanFetchOutcome {
		return PlanFetchOutcome{
			Applies: true, Attempted: true,
			Repos: []PlanFetchRepoResult{{
				Attempted: true, OK: true, ContextCommonDir: commonDir,
				Effect: &PlanFetchEffect{Contacted: true, Remotes: []PlanFetchRemote{{Name: "origin"}}},
			}},
		}
	}

	t.Run("NonApplicableFactsAreNeverMeasuredOrRefreshed", func(t *testing.T) {
		in := PlanPushFacts{Applies: false, Phase: "not-applicable"}
		got := RefreshPushTrackingRefs(in, fetchedOK("anything"))
		if got.Applies || got.Phase != "not-applicable" || got.Remotes != nil {
			t.Fatalf("facts = %+v, want the not-applicable value passed through unchanged", got)
		}
	})

	t.Run("PostFetchReadOfAFetchedContextIsFreshAndCarriesTheRefs", func(t *testing.T) {
		repo := rppRepo(t)
		commonDir := rppCommonDir(t, repo)
		sha := rppHeadSHA(t, repo)
		gitInTest(t, repo, "update-ref", "refs/remotes/origin/main", sha)

		id := "ctx"
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{id: {ContextID: id, RepoRoot: repo, CommonDir: commonDir}},
			Remotes: map[string]PlanPushRemoteFacts{"": {
				ContextID: &id, CommonDir: commonDir, RemoteName: "origin",
				MappingReadOK: true, TrackingPhase: "not-applicable",
			}},
		}
		got := RefreshPushTrackingRefs(in, fetchedOK(commonDir))
		if got.Phase != "post-fetch" {
			t.Fatalf("PlanPushFacts.Phase = %q, want post-fetch", got.Phase)
		}
		rf := got.Remotes[""]
		if !rf.TrackingReadOK {
			t.Fatal("expected TrackingReadOK=true")
		}
		if rf.TrackingPhase != "post-fetch" {
			t.Fatalf("TrackingPhase = %q, want post-fetch", rf.TrackingPhase)
		}
		if !rf.FetchedThisRun {
			t.Fatal("expected FetchedThisRun=true: mapping read, inventory read, post-fetch, and origin was contacted in this common dir")
		}
		if rf.TrackingRefs["main"] != sha {
			t.Fatalf("TrackingRefs[main] = %q, want %q", rf.TrackingRefs["main"], sha)
		}
	})

	t.Run("TwoLinkedWorktreesOfOneRepositoryAreBothFreshAfterOneFetch", func(t *testing.T) {
		repo := rppRepo(t)
		commonDir := rppCommonDir(t, repo)
		sha := rppHeadSHA(t, repo)
		gitInTest(t, repo, "update-ref", "refs/remotes/origin/main", sha)
		linked := filepath.Join(t.TempDir(), "linked")
		gitInTest(t, repo, "worktree", "add", "-b", "linked", linked)

		// Two DIFFERENT context ids (they hash different top levels) sharing
		// ONE canonical common dir: §14.1a rule 8's conjunct iv is exactly
		// why both are refreshed by the single collapsed fetch.
		a, b := "ctx-main", "ctx-linked"
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{
				a: {ContextID: a, RepoRoot: repo, CommonDir: commonDir},
				b: {ContextID: b, RepoRoot: linked, CommonDir: commonDir},
			},
			Remotes: map[string]PlanPushRemoteFacts{
				"a": {ContextID: &a, CommonDir: commonDir, RemoteName: "origin", MappingReadOK: true},
				"b": {ContextID: &b, CommonDir: commonDir, RemoteName: "origin", MappingReadOK: true},
			},
		}
		got := RefreshPushTrackingRefs(in, fetchedOK(commonDir))
		for _, token := range []string{"a", "b"} {
			rf := got.Remotes[token]
			if !rf.FetchedThisRun || rf.TrackingPhase != "post-fetch" || rf.TrackingRefs["main"] != sha {
				t.Fatalf("token %q: %+v, want post-fetch/fresh with the shared origin/main baseline", token, rf)
			}
		}
	})

	t.Run("AContextWhoseRemoteIsUpstreamStaysPossiblyStaleEvenAfterItsOwnFetch", func(t *testing.T) {
		repo := rppRepo(t)
		commonDir := rppCommonDir(t, repo)
		id := "ctx"
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{id: {ContextID: id, RepoRoot: repo, CommonDir: commonDir}},
			Remotes: map[string]PlanPushRemoteFacts{"": {
				ContextID: &id, CommonDir: commonDir, RemoteName: "upstream", MappingReadOK: true,
			}},
		}
		upstreamOnly := PlanFetchOutcome{
			Applies: true, Attempted: true,
			Repos: []PlanFetchRepoResult{{
				Attempted: true, OK: true, ContextCommonDir: commonDir,
				Effect: &PlanFetchEffect{Contacted: true, Remotes: []PlanFetchRemote{{Name: "upstream"}}},
			}},
		}
		got := RefreshPushTrackingRefs(in, upstreamOnly)
		rf := got.Remotes[""]
		if rf.TrackingPhase != "post-fetch" {
			t.Fatalf("TrackingPhase = %q, want post-fetch (a child really ran)", rf.TrackingPhase)
		}
		if rf.FetchedThisRun {
			t.Fatal("expected FetchedThisRun=false: origin's baseline was never refreshed, only upstream's")
		}
	})

	t.Run("NoFetchChildStampsPlanPointAndNeverFresh", func(t *testing.T) {
		repo := rppRepo(t)
		commonDir := rppCommonDir(t, repo)
		id := "ctx"
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{id: {ContextID: id, RepoRoot: repo, CommonDir: commonDir}},
			Remotes: map[string]PlanPushRemoteFacts{"": {
				ContextID: &id, CommonDir: commonDir, RemoteName: "origin", MappingReadOK: true,
			}},
		}
		got := RefreshPushTrackingRefs(in, PlanFetchOutcome{Applies: true})
		if got.Phase != "plan-point" {
			t.Fatalf("PlanPushFacts.Phase = %q, want plan-point", got.Phase)
		}
		rf := got.Remotes[""]
		if rf.TrackingPhase != "plan-point" || rf.FetchedThisRun {
			t.Fatalf("remote facts = %+v, want a plan-point read that is never fresh", rf)
		}
		if !rf.TrackingReadOK {
			t.Fatal("a plan-point read is still a REAL read of the current refs")
		}
	})

	t.Run("UnreadableInventoryStampsUnreadAndNeverFresh", func(t *testing.T) {
		notRepo := rppNotARepo(t)
		id := "ctx"
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{id: {ContextID: id, RepoRoot: notRepo, CommonDir: "common"}},
			Remotes: map[string]PlanPushRemoteFacts{"": {
				ContextID: &id, CommonDir: "common", RemoteName: "origin", MappingReadOK: true,
			}},
		}
		got := RefreshPushTrackingRefs(in, fetchedOK("common"))
		rf := got.Remotes[""]
		if rf.TrackingReadOK {
			t.Fatal("expected TrackingReadOK=false outside any repository")
		}
		if rf.TrackingPhase != "unread" {
			t.Fatalf("TrackingPhase = %q, want unread (first rung of the ladder)", rf.TrackingPhase)
		}
		if rf.FetchedThisRun {
			t.Fatal("expected FetchedThisRun=false: an unread inventory can never be fresh")
		}
		if rf.TrackingRefs != nil {
			t.Fatalf("TrackingRefs = %v, want nil on a failed read", rf.TrackingRefs)
		}
	})

	t.Run("ANilContextIDReadsNothingAndKeepsTheUnknownCell", func(t *testing.T) {
		in := PlanPushFacts{
			Applies: true, Phase: "plan-point",
			Identities: PlanContextIdentities{},
			Remotes: map[string]PlanPushRemoteFacts{"": {
				CommonDir: "common", RemoteName: "origin", MappingReadOK: false,
			}},
		}
		got := RefreshPushTrackingRefs(in, fetchedOK("common"))
		rf := got.Remotes[""]
		if rf.TrackingReadOK || rf.TrackingRefs != nil || rf.FetchedThisRun {
			t.Fatalf("remote facts = %+v, want a context that read NOTHING", rf)
		}
		if rf.TrackingPhase != "unread" {
			t.Fatalf("TrackingPhase = %q, want unread", rf.TrackingPhase)
		}
	})
}

func TestRebasePlanner_PushContextRefreshed(t *testing.T) {
	baseEffect := func(contacted bool, remotes ...string) *PlanFetchEffect {
		var rs []PlanFetchRemote
		for _, r := range remotes {
			rs = append(rs, PlanFetchRemote{Name: r})
		}
		return &PlanFetchEffect{Contacted: contacted, Remotes: rs}
	}
	row := func(attempted, ok bool, commonDir string, effect *PlanFetchEffect) PlanFetchOutcome {
		return PlanFetchOutcome{Applies: true, Attempted: attempted, Repos: []PlanFetchRepoResult{
			{Attempted: attempted, OK: ok, ContextCommonDir: commonDir, Effect: effect},
		}}
	}

	t.Run("EmptyCommonDirIsFalse", func(t *testing.T) {
		if PushContextRefreshed(row(true, true, "common", baseEffect(true, "origin")), "") {
			t.Fatal("expected false: an unmeasured common dir can never join")
		}
	})

	t.Run("NotAttemptedIsFalse", func(t *testing.T) {
		if PushContextRefreshed(PlanFetchOutcome{Applies: true}, "common") {
			t.Fatal("expected false when fetch was never attempted")
		}
	})

	t.Run("MatchingContactedOriginRowIsTrue", func(t *testing.T) {
		if !PushContextRefreshed(row(true, true, "common", baseEffect(true, "origin")), "common") {
			t.Fatal("expected true for a matching, contacted, OK origin row")
		}
	})

	t.Run("DifferentCommonDirIsFalse", func(t *testing.T) {
		if PushContextRefreshed(row(true, true, "other", baseEffect(true, "origin")), "common") {
			t.Fatal("expected false: common dir does not match")
		}
	})

	t.Run("NotContactedIsFalse", func(t *testing.T) {
		if PushContextRefreshed(row(true, true, "common", baseEffect(false, "origin")), "common") {
			t.Fatal("expected false: effect was not Contacted")
		}
	})

	t.Run("OriginNotAmongEffectRemotesIsFalse", func(t *testing.T) {
		if PushContextRefreshed(row(true, true, "common", baseEffect(true, "upstream")), "common") {
			t.Fatal("expected false: origin is not among the effect's remotes")
		}
	})

	t.Run("RepoAttemptedButNotOKIsSkipped", func(t *testing.T) {
		if PushContextRefreshed(row(true, false, "common", baseEffect(true, "origin")), "common") {
			t.Fatal("expected false: repo row was not OK")
		}
	})

	t.Run("NilEffectIsSkipped", func(t *testing.T) {
		if PushContextRefreshed(row(true, true, "common", nil), "common") {
			t.Fatal("expected false: nil Effect")
		}
	})

	t.Run("JoinIsOnTheCANONICALCommonDirNotTheRawString", func(t *testing.T) {
		dir := t.TempDir()
		nested := filepath.Join(dir, "a", "..", "a")
		if err := os.MkdirAll(filepath.Join(dir, "a"), 0o755); err != nil {
			t.Fatal(err)
		}
		fetched := row(true, true, nested, baseEffect(true, "origin"))
		if !PushContextRefreshed(fetched, filepath.Join(dir, "a")) {
			t.Fatal("expected true: the two spellings canonicalize to the same directory")
		}
	})
}

func TestRebasePlanner_MapThroughRefspec(t *testing.T) {
	t.Run("NonMatchingSrcFails", func(t *testing.T) {
		_, ok := mapThroughRefspec(PlanRefspec{Src: "refs/heads/release/*", Dst: "refs/remotes/origin/*"}, "refs/heads/main")
		if ok {
			t.Fatal("expected no match")
		}
	})

	t.Run("ExactNonWildcardPatternMapsToTheLiteralDst", func(t *testing.T) {
		dst, ok := mapThroughRefspec(PlanRefspec{Src: "refs/heads/main", Dst: "refs/remotes/origin/main"}, "refs/heads/main")
		if !ok || dst != "refs/remotes/origin/main" {
			t.Fatalf("dst=%q ok=%v, want refs/remotes/origin/main/true", dst, ok)
		}
	})

	t.Run("WildcardPatternSubstitutesTheMatchedSuffix", func(t *testing.T) {
		dst, ok := mapThroughRefspec(PlanRefspec{Src: "refs/heads/*", Dst: "refs/remotes/origin/*"}, "refs/heads/feature-x")
		if !ok || dst != "refs/remotes/origin/feature-x" {
			t.Fatalf("dst=%q ok=%v, want refs/remotes/origin/feature-x/true", dst, ok)
		}
	})

	t.Run("WildcardSrcWithNonWildcardDstUsesTheLiteralDst", func(t *testing.T) {
		dst, ok := mapThroughRefspec(PlanRefspec{Src: "refs/heads/*", Dst: "refs/remotes/origin/pinned"}, "refs/heads/anything")
		if !ok || dst != "refs/remotes/origin/pinned" {
			t.Fatalf("dst=%q ok=%v, want refs/remotes/origin/pinned/true (dst has no trailing * to substitute into)", dst, ok)
		}
	})
}

// TestRebasePlanner_ResolvePushLease drives §14.2's five closed cells, one
// subtest per cell, asserting the WHOLE PlanLease value (all five members) so
// no cell can be satisfied by a partially-correct projection.
func TestRebasePlanner_ResolvePushLease(t *testing.T) {
	wildcardRefspec := PlanRefspec{Src: "refs/heads/*", Dst: "refs/remotes/origin/*"}
	ref := func(s string) *string { return &s }

	t.Run("Cell5MappingUnreadableIsTheOnlyUnknownCell", func(t *testing.T) {
		lease := ResolvePushLease(PlanPushRemoteFacts{MappingReadOK: false}, "main")
		want := PlanLease{Mode: "implicit-remote-tracking", Expectation: "unknown", ExpectedSHAFreshness: "possibly-stale"}
		if lease != want {
			t.Fatalf("lease = %+v, want %+v", lease, want)
		}
	})

	t.Run("Cell4MappingReadButNoPositiveMappingIsAbsentAndFresh", func(t *testing.T) {
		lease := ResolvePushLease(PlanPushRemoteFacts{MappingReadOK: true, FetchRefspecs: nil}, "main")
		want := PlanLease{Mode: "implicit-remote-tracking", Expectation: "absent", ExpectedSHAFreshness: "fresh"}
		if lease != want {
			t.Fatalf("lease = %+v, want %+v: a configuration that WAS read and really maps nothing is Git's null-OID expectation, never `unknown`", lease, want)
		}
	})

	t.Run("Cell3MappedButTrackingInventoryUnreadIsAbsentAndPossiblyStale", func(t *testing.T) {
		facts := PlanPushRemoteFacts{
			MappingReadOK: true, RemoteName: "origin", FetchRefspecs: []PlanRefspec{wildcardRefspec},
			TrackingReadOK: false, TrackingPhase: "unread",
		}
		lease := ResolvePushLease(facts, "main")
		if lease.ExpectedRef == nil || *lease.ExpectedRef != "refs/remotes/origin/main" {
			t.Fatalf("ExpectedRef = %v, want refs/remotes/origin/main (the mapping survives an unread inventory)", lease.ExpectedRef)
		}
		want := PlanLease{
			Mode: "implicit-remote-tracking", Expectation: "absent",
			ExpectedRef: lease.ExpectedRef, ExpectedSHAFreshness: "possibly-stale",
		}
		if lease != want {
			t.Fatalf("lease = %+v, want %+v: Git falls back to the null OID when it cannot read the mapped ref, and nothing read may be called fresh", lease, want)
		}
	})

	t.Run("Cell2MappedAndReadWithTheMappedRefAbsentIsAbsentAndFresh", func(t *testing.T) {
		facts := PlanPushRemoteFacts{
			MappingReadOK: true, RemoteName: "origin", FetchRefspecs: []PlanRefspec{wildcardRefspec},
			TrackingReadOK: true, TrackingPhase: "plan-point", TrackingRefs: map[string]string{},
		}
		lease := ResolvePushLease(facts, "main")
		want := PlanLease{
			Mode: "implicit-remote-tracking", Expectation: "absent",
			ExpectedRef: ref("refs/remotes/origin/main"), ExpectedSHAFreshness: "fresh",
		}
		if lease.ExpectedRef == nil || *lease.ExpectedRef != *want.ExpectedRef {
			t.Fatalf("ExpectedRef = %v, want %v (it is the ref that must not exist)", lease.ExpectedRef, want.ExpectedRef)
		}
		if lease.Expectation != want.Expectation || lease.ExpectedSHA != nil || lease.ExpectedSHAFreshness != want.ExpectedSHAFreshness {
			t.Fatalf("lease = %+v, want expectation=absent expected_sha=nil freshness=fresh: this invocation READ the absence", lease)
		}
	})

	t.Run("Cell1MappedAndReadWithAShaPresentIsShaCarryingTheCurrentValue", func(t *testing.T) {
		facts := PlanPushRemoteFacts{
			MappingReadOK: true, RemoteName: "origin", FetchRefspecs: []PlanRefspec{wildcardRefspec},
			TrackingReadOK: true, TrackingPhase: "plan-point", TrackingRefs: map[string]string{"main": "deadbeef"},
		}
		lease := ResolvePushLease(facts, "main")
		if lease.Expectation != "sha" {
			t.Fatalf("Expectation = %q, want sha", lease.Expectation)
		}
		if lease.ExpectedSHA == nil || *lease.ExpectedSHA != "deadbeef" {
			t.Fatalf("ExpectedSHA = %v, want deadbeef", lease.ExpectedSHA)
		}
		if lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("Freshness = %q, want possibly-stale: a plan-point read refreshed nothing", lease.ExpectedSHAFreshness)
		}
	})

	t.Run("FreshnessIsFreshOnlyWhenAllThreeConditionsHold", func(t *testing.T) {
		full := PlanPushRemoteFacts{
			MappingReadOK: true, RemoteName: "origin", FetchRefspecs: []PlanRefspec{wildcardRefspec},
			TrackingReadOK: true, TrackingPhase: "post-fetch", FetchedThisRun: true,
			TrackingRefs: map[string]string{"main": "sha"},
		}
		if lease := ResolvePushLease(full, "main"); lease.ExpectedSHAFreshness != "fresh" {
			t.Fatalf("Freshness = %q, want fresh when TrackingReadOK && phase=post-fetch && FetchedThisRun", lease.ExpectedSHAFreshness)
		}

		notFetched := full
		notFetched.FetchedThisRun = false
		if lease := ResolvePushLease(notFetched, "main"); lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("Freshness = %q, want possibly-stale when FetchedThisRun is false", lease.ExpectedSHAFreshness)
		}

		wrongPhase := full
		wrongPhase.TrackingPhase = "pre-fetch"
		if lease := ResolvePushLease(wrongPhase, "main"); lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("Freshness = %q, want possibly-stale when phase is not post-fetch", lease.ExpectedSHAFreshness)
		}

		// A tracking read that did not happen is cell 3, whose OWN freshness
		// is possibly-stale — and whose expectation is `absent`, never the
		// `sha` the (unread) map still nominally contains.
		notRead := full
		notRead.TrackingReadOK = false
		notRead.TrackingPhase = "unread"
		lease := ResolvePushLease(notRead, "main")
		if lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("Freshness = %q, want possibly-stale when TrackingReadOK is false", lease.ExpectedSHAFreshness)
		}
		if lease.Expectation != "absent" || lease.ExpectedSHA != nil {
			t.Fatalf("lease = %+v, want the cell-3 absent/null pair", lease)
		}
	})

	t.Run("NegativeRefspecMatchForcesPossiblyStaleEvenWhenEveryFreshnessConditionOtherwiseHolds", func(t *testing.T) {
		facts := PlanPushRemoteFacts{
			MappingReadOK: true,
			RemoteName:    "origin",
			FetchRefspecs: []PlanRefspec{
				{Src: "refs/heads/main", Negative: true},
				wildcardRefspec,
			},
			TrackingReadOK: true, TrackingPhase: "post-fetch", FetchedThisRun: true,
			TrackingRefs: map[string]string{"main": "sha"},
		}
		lease := ResolvePushLease(facts, "main")
		if lease.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("Freshness = %q, want possibly-stale: a negative refspec match must override every fresh condition", lease.ExpectedSHAFreshness)
		}
		// The negative refspec must not itself prevent the positive
		// wildcard rung below it from still mapping the branch, and the
		// mapped ref and its current value both survive.
		if lease.Expectation != "sha" {
			t.Fatalf("Expectation = %q, want sha (the negative match only affects freshness, not the mapping/expectation itself)", lease.Expectation)
		}
		if lease.ExpectedRef == nil || *lease.ExpectedRef != "refs/remotes/origin/main" {
			t.Fatalf("ExpectedRef = %v, want the mapped ref refs/remotes/origin/main", lease.ExpectedRef)
		}
		if lease.ExpectedSHA == nil || *lease.ExpectedSHA != "sha" {
			t.Fatalf("ExpectedSHA = %v, want the tracking ref's current value", lease.ExpectedSHA)
		}
	})

	t.Run("NegativeRefspecAlsoForcesPossiblyStaleOnTheUnmappedAndAbsentCells", func(t *testing.T) {
		// Cell 4 under a negative match: nothing maps, so the expectation is
		// still `absent`, but no fetch can ever refresh what it names.
		unmapped := ResolvePushLease(PlanPushRemoteFacts{
			MappingReadOK: true,
			FetchRefspecs: []PlanRefspec{{Src: "refs/heads/main", Negative: true}},
		}, "main")
		if unmapped.Expectation != "absent" || unmapped.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("lease = %+v, want absent/possibly-stale", unmapped)
		}

		// Cell 2 under a negative match.
		absent := ResolvePushLease(PlanPushRemoteFacts{
			MappingReadOK: true, RemoteName: "origin",
			FetchRefspecs:  []PlanRefspec{{Src: "refs/heads/main", Negative: true}, wildcardRefspec},
			TrackingReadOK: true, TrackingPhase: "post-fetch", FetchedThisRun: true,
			TrackingRefs: map[string]string{},
		}, "main")
		if absent.Expectation != "absent" || absent.ExpectedSHAFreshness != "possibly-stale" {
			t.Fatalf("lease = %+v, want absent/possibly-stale", absent)
		}
	})

	t.Run("FirstPositiveMatchWinsWhenMultiplePositiveRefspecsCouldMap", func(t *testing.T) {
		facts := PlanPushRemoteFacts{
			MappingReadOK: true,
			FetchRefspecs: []PlanRefspec{
				{Src: "refs/heads/main", Dst: "refs/remotes/origin/pinned-main"},
				wildcardRefspec,
			},
		}
		lease := ResolvePushLease(facts, "main")
		if lease.ExpectedRef == nil || *lease.ExpectedRef != "refs/remotes/origin/pinned-main" {
			t.Fatalf("ExpectedRef = %v, want the FIRST positive match's mapping, refs/remotes/origin/pinned-main", lease.ExpectedRef)
		}
	})
}

func TestRebasePlanner_PushTargets(t *testing.T) {
	t.Run("NoIntentYieldsANonNilEmptySlice", func(t *testing.T) {
		got := PushTargets(PlanPushRequest{Intent: false})
		if got == nil || len(got) != 0 {
			t.Fatalf("got = %v, want a non-nil empty slice", got)
		}
	})

	t.Run("FiltersToRemainingAndNotYetPushed", func(t *testing.T) {
		req := PlanPushRequest{
			Intent: true,
			Selection: SyncSelection{Entries: []SyncSelectedEntry{
				{Name: "a", GitBranch: "a"},
				{Name: "b", GitBranch: "b"},
				{Name: "c", GitBranch: "c"},
			}},
			Remaining:     []string{"a", "b"}, // c is not remaining
			AlreadyPushed: map[string]bool{"b": true},
		}
		got := PushTargets(req)
		if len(got) != 1 || got[0].GitBranch != "a" {
			t.Fatalf("got = %+v, want exactly one target for entry a", got)
		}
	})

	t.Run("FixedFieldsAndRefShapeAndCheckoutModeClearsRepo", func(t *testing.T) {
		req := PlanPushRequest{
			Mode:      ModeCheckout,
			Scope:     "one",
			Intent:    true,
			Selection: SyncSelection{Entries: []SyncSelectedEntry{{Name: "a", GitBranch: "feature-a", Repo: "sub"}}},
			Remaining: []string{"a"},
		}
		got := PushTargets(req)
		if len(got) != 1 {
			t.Fatalf("len = %d, want 1", len(got))
		}
		tgt := got[0]
		if tgt.Repo != "" {
			t.Fatalf("Repo = %q, want empty: checkout mode always clears push.targets[].repo", tgt.Repo)
		}
		if tgt.Remote != "origin" || tgt.Ref != "refs/heads/feature-a" || tgt.Force != "with-lease" {
			t.Fatalf("tgt = %+v, want Remote=origin Ref=refs/heads/feature-a Force=with-lease", tgt)
		}
		if tgt.Scope != "one" {
			t.Fatalf("Scope = %q, want one (passed through from the request)", tgt.Scope)
		}
	})

	t.Run("ExternalModePreservesTheEntryRepoToken", func(t *testing.T) {
		req := PlanPushRequest{
			Mode:      ModeExternal,
			Intent:    true,
			Selection: SyncSelection{Entries: []SyncSelectedEntry{{Name: "a", GitBranch: "feature-a", Repo: "sub"}}},
			Remaining: []string{"a"},
		}
		got := PushTargets(req)
		if len(got) != 1 || got[0].Repo != "sub" {
			t.Fatalf("got = %+v, want Repo=sub preserved for external mode", got)
		}
	})

	t.Run("ContextIDAndRepoRootResolveOnlyWhenBothLookupsSucceed", func(t *testing.T) {
		cid := "context-1"
		req := PlanPushRequest{
			Intent:    true,
			Selection: SyncSelection{Entries: []SyncSelectedEntry{{Name: "a", GitBranch: "a", Repo: ""}, {Name: "b", GitBranch: "b", Repo: "missing-remote-entry"}, {Name: "c", GitBranch: "c", Repo: "dangling-context"}}},
			Remaining: []string{"a", "b", "c"},
			Facts: PlanPushFacts{
				Remotes: map[string]PlanPushRemoteFacts{
					"":                 {ContextID: &cid},
					"dangling-context": {ContextID: strp("no-such-identity")},
				},
				Identities:      PlanContextIdentities{cid: {ContextID: cid, RepoRoot: "/repo/root"}},
				Materialization: map[string]string{"": "materialized"},
			},
		}
		got := PushTargets(req)
		byName := map[string]PlanPushTarget{}
		for _, tgt := range got {
			byName[tgt.GitBranch] = tgt
		}
		if a := byName["a"]; a.ContextID == nil || *a.ContextID != cid || a.RepoRoot == nil || *a.RepoRoot != "/repo/root" {
			t.Fatalf("a = %+v, want a resolved ContextID/RepoRoot", a)
		}
		if a := byName["a"]; a.Materialization != "materialized" {
			t.Fatalf("a.Materialization = %q, want materialized", a.Materialization)
		}
		if b := byName["b"]; b.ContextID != nil || b.RepoRoot != nil {
			t.Fatalf("b = %+v, want nil ContextID/RepoRoot: repo token has no Remotes entry at all", b)
		}
		if c := byName["c"]; c.ContextID != nil || c.RepoRoot != nil {
			t.Fatalf("c = %+v, want nil ContextID/RepoRoot: the ContextID it names has no Identities entry", c)
		}
	})

	t.Run("SortsByContextIDNilFirstThenAscendingThenGitBranchAscendingWithinTies", func(t *testing.T) {
		cidZ, cidA := "zzz", "aaa"
		req := PlanPushRequest{
			Intent: true,
			Selection: SyncSelection{Entries: []SyncSelectedEntry{
				{Name: "1", GitBranch: "b-branch", Repo: "z"},
				{Name: "2", GitBranch: "a-branch", Repo: "z"}, // same ContextID as 1: tie-break by GitBranch
				{Name: "3", GitBranch: "c-branch", Repo: "a"},
				{Name: "4", GitBranch: "d-branch", Repo: "no-remote-entry"}, // nil ContextID: sorts first
			}},
			Remaining: []string{"1", "2", "3", "4"},
			Facts: PlanPushFacts{
				Remotes: map[string]PlanPushRemoteFacts{
					"z": {ContextID: &cidZ},
					"a": {ContextID: &cidA},
				},
				Identities: PlanContextIdentities{
					cidZ: {ContextID: cidZ},
					cidA: {ContextID: cidA},
				},
			},
		}
		got := PushTargets(req)
		var order []string
		for _, tgt := range got {
			order = append(order, tgt.GitBranch)
		}
		want := []string{"d-branch", "c-branch", "a-branch", "b-branch"}
		if !stringSlicesEqual(order, want) {
			t.Fatalf("order = %v, want %v (nil ContextID first, then ascending ContextID, then ascending GitBranch within a tie)", order, want)
		}
	})
}

// ---------------------------------------------------------------------------
// §23.3 — TopoSort's 20,000-iteration randomized ordering test.
// ---------------------------------------------------------------------------

// topoComponents is the fixture the randomized test sorts: THREE disjoint
// linear chains (components). Each chain forces its own internal order by
// dependency alone — no siblings, so no intra-component ambiguity exists —
// which is what makes "only INTER-component interleaving may vary" an exact,
// checkable claim rather than a hedge.
func topoComponents() [][]string {
	return [][]string{
		{"a0", "a1", "a2", "a3"},
		{"b0", "b1", "b2"},
		{"c0", "c1", "c2", "c3", "c4"},
	}
}

// topoFixtureEntries builds the flat StackEntry list for topoComponents,
// where each chain's first element is rooted on an UNTRACKED base (so it has
// in-degree 0) and every later element is based on its predecessor.
func topoFixtureEntries() []StackEntry {
	var out []StackEntry
	for _, chain := range topoComponents() {
		for i, name := range chain {
			base := "main"
			if i > 0 {
				base = chain[i-1]
			}
			out = append(out, StackEntry{Name: name, Base: base})
		}
	}
	return out
}

// TestRebasePlanner_TopoSortRandomizedOrderingIsComponentStable is §23.3's
// 20,000-iteration randomized ordering test. Every iteration shuffles the
// INPUT order and asserts four things about the result:
//
//  1. it is a real topological order — every entry whose base is tracked
//     appears strictly after that base;
//  2. it is a permutation of the input — same names, same count, no
//     duplicates and no invention;
//  3. the relative order WITHIN each component is exactly the chain order,
//     invariant across every iteration; and
//  4. the ONLY thing that varies is how the components interleave, which is
//     asserted to really vary (at least two distinct interleavings are
//     observed) so the test cannot pass by the sort being accidentally
//     input-order-stable.
func TestRebasePlanner_TopoSortRandomizedOrderingIsComponentStable(t *testing.T) {
	const iterations = 20000

	entries := topoFixtureEntries()
	componentOf := map[string]int{}
	indexInComponent := map[string]int{}
	for c, chain := range topoComponents() {
		for i, name := range chain {
			componentOf[name] = c
			indexInComponent[name] = i
		}
	}

	rng := rand.New(rand.NewSource(20000))
	interleavings := map[string]bool{}

	for iter := 0; iter < iterations; iter++ {
		shuffled := append([]StackEntry(nil), entries...)
		rng.Shuffle(len(shuffled), func(i, j int) { shuffled[i], shuffled[j] = shuffled[j], shuffled[i] })

		sorted, err := TopoSort(Stack{Branches: shuffled})
		if err != nil {
			t.Fatalf("iteration %d: TopoSort: %v", iter, err)
		}
		if len(sorted) != len(entries) {
			t.Fatalf("iteration %d: sorted %d entries, want %d", iter, len(sorted), len(entries))
		}

		position := make(map[string]int, len(sorted))
		lastSeen := map[int]int{}
		var signature []byte
		for pos, e := range sorted {
			if _, dup := position[e.Name]; dup {
				t.Fatalf("iteration %d: %q appears twice", iter, e.Name)
			}
			position[e.Name] = pos

			c, known := componentOf[e.Name]
			if !known {
				t.Fatalf("iteration %d: TopoSort invented the entry %q", iter, e.Name)
			}
			// (3) intra-component order: this entry must be exactly the next
			// one of its own chain.
			want := 0
			if seen, ok := lastSeen[c]; ok {
				want = seen + 1
			}
			if got := indexInComponent[e.Name]; got != want {
				t.Fatalf("iteration %d: %q is index %d of component %d but appeared where index %d was due — intra-component order must never vary",
					iter, e.Name, got, c, want)
			}
			lastSeen[c] = want
			signature = append(signature, byte('0'+c))
		}
		if len(position) != len(entries) {
			t.Fatalf("iteration %d: result is not a permutation of the input", iter)
		}
		// (1) the dependency order itself.
		for _, e := range entries {
			if basePos, tracked := position[e.Base]; tracked && basePos >= position[e.Name] {
				t.Fatalf("iteration %d: %q at %d does not follow its base %q at %d",
					iter, e.Name, position[e.Name], e.Base, basePos)
			}
		}
		interleavings[string(signature)] = true
	}

	// (4) inter-component interleaving really is the varying dimension.
	if len(interleavings) < 2 {
		t.Fatalf("observed %d distinct component interleavings over %d iterations, want at least 2: the randomization is not reaching TopoSort's own queue seeding",
			len(interleavings), iterations)
	}
}

// TestRebasePlanner_TopoSortNeverInventsAnOrderForACycle is the companion
// negative: a cyclic stack has no topological order at all, so every
// iteration of the same randomized loop must refuse rather than emit a
// partial one.
func TestRebasePlanner_TopoSortNeverInventsAnOrderForACycle(t *testing.T) {
	cyclic := []StackEntry{
		{Name: "x", Base: "z"},
		{Name: "y", Base: "x"},
		{Name: "z", Base: "y"},
	}
	rng := rand.New(rand.NewSource(3))
	for iter := 0; iter < 1000; iter++ {
		shuffled := append([]StackEntry(nil), cyclic...)
		rng.Shuffle(len(shuffled), func(i, j int) { shuffled[i], shuffled[j] = shuffled[j], shuffled[i] })
		if _, err := TopoSort(Stack{Branches: shuffled}); err == nil {
			t.Fatalf("iteration %d: a cyclic stack must refuse, never sort", iter)
		}
	}
}

package internal

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

type StackEntry struct {
	Name        string `yaml:"name"`
	Branch      string `yaml:"branch,omitempty"`   // git branch name (defaults to Name if empty)
	Archived    bool   `yaml:"archived,omitempty"` // true when branch is archived (metadata only)
	Base        string `yaml:"base"`
	Repo        string `yaml:"repo,omitempty"`          // source repo path (empty = default/current repo)
	LastBaseSHA string `yaml:"last_base_sha,omitempty"` // SHA of base branch at last sync
}

// GitBranch returns the actual git branch name for this entry.
func (e StackEntry) GitBranch() string {
	if e.Branch != "" {
		return e.Branch
	}
	return e.Name
}

type Stack struct {
	Branches []StackEntry `yaml:"branches"`
}

// UniqueRepos returns a set of unique repo paths referenced in the stack.
// Empty string represents the default repo. Returns worktree paths for
// each repo (to use as git context) alongside the repo path.
func UniqueRepos(s Stack, featurePath string) map[string]string {
	repos := make(map[string]string)
	for _, e := range s.Branches {
		repo := e.Repo
		if _, ok := repos[repo]; !ok {
			// Find an active worktree from this repo to use as git context
			wtPath := filepath.Join(featurePath, "worktrees", e.Name)
			if _, err := os.Stat(wtPath); err == nil {
				repos[repo] = wtPath
			} else {
				repos[repo] = "" // no active worktree, will need fallback
			}
		}
	}
	return repos
}

// HasBranch checks if a branch name already exists in the stack.
func HasBranch(s Stack, name string) bool {
	for _, e := range s.Branches {
		if e.Name == name {
			return true
		}
	}
	return false
}

// GetBranch returns the StackEntry for a branch name. Returns empty entry if not found.
func GetBranch(s Stack, name string) StackEntry {
	for _, e := range s.Branches {
		if e.Name == name {
			return e
		}
	}
	return StackEntry{}
}

// UpdateBaseSHA updates the last_base_sha for a branch in the stack.
func UpdateBaseSHA(s *Stack, branchName, sha string) {
	for i := range s.Branches {
		if s.Branches[i].Name == branchName {
			s.Branches[i].LastBaseSHA = sha
			return
		}
	}
}

// GetBranchSHA returns the current HEAD SHA of a branch using git.
func GetBranchSHA(gitContext, branch string) string {
	args := []string{"rev-parse", branch}
	if gitContext != "" {
		args = []string{"-C", gitContext, "rev-parse", branch}
	}
	out, err := exec.Command("git", args...).Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

// RenameBranch renames a branch in the stack, updating both Name and Base references.
func RenameBranch(s *Stack, oldName, newName string) bool {
	found := false
	for i := range s.Branches {
		if s.Branches[i].Name == oldName {
			s.Branches[i].Name = newName
			found = true
		}
		if s.Branches[i].Base == oldName {
			s.Branches[i].Base = newName
		}
	}
	return found
}

func StackPath(featurePath string) string {
	return filepath.Join(featurePath, "stack.yaml")
}

func LoadStack(featurePath string) (Stack, error) {
	data, err := os.ReadFile(StackPath(featurePath))
	if err != nil {
		return Stack{}, err
	}
	var s Stack
	if err := yaml.Unmarshal(data, &s); err != nil {
		return Stack{}, err
	}
	return s, nil
}

func SaveStack(featurePath string, s Stack) error {
	data, err := yaml.Marshal(&s)
	if err != nil {
		return err
	}
	return os.WriteFile(StackPath(featurePath), data, 0644)
}

// ============================================================================
// Byte-exact durable stack writers (safe-reparent §10.3, §10.3a)
//
// SaveStack above is deliberately untouched: it is not atomic, not durable,
// and every one of its callers keeps it. The three functions below are the
// reparent boundary's only metadata writers.
// ============================================================================

// WriteStackBytesAtomic writes exactly these bytes to the feature's
// stack.yaml, atomically and durably. It is the primitive both the forward
// metadata write and the abort restore use, because a pre-image restored by
// re-marshalling a decoded struct is not a restore: YAML round-tripping can
// reorder keys, drop comments and change quoting, so only the captured bytes
// are ever written back.
func WriteStackBytesAtomic(featurePath string, data []byte) error {
	return durableWriteFileFault(SyncIOWriteStack, StackPath(featurePath), data, 0644)
}

// SaveStackAtomic marshals s exactly as SaveStack does and delegates to
// WriteStackBytesAtomic, so a caller that holds a struct rather than bytes
// still gets the atomic, durable writer.
func SaveStackAtomic(featurePath string, s Stack) error {
	data, err := yaml.Marshal(&s)
	if err != nil {
		return err
	}
	return WriteStackBytesAtomic(featurePath, data)
}

// durableWriteFile writes data to path through a same-directory temp file
// that is fsynced, closed and renamed over the destination, after which the
// PARENT DIRECTORY is opened and fsynced too. The shipped atomicWriteFile
// (internal/checkout_sync.go) fsyncs the temp file but never the directory,
// so the renamed directory entry it produces is outside a machine-crash
// durability claim; this helper is added beside it, never inside it, and
// atomicWriteFile keeps every one of its callers.
//
// Every artifact whose loss would strip a reparent run of its only record of
// what it did is written through this helper: stack.yaml (via
// WriteStackBytesAtomic), the reparent state artifact, the compatibility
// artifacts, and the remote follow-up record.
func durableWriteFile(path string, data []byte, mode os.FileMode) error {
	return durableWriteFileFault("", path, data, mode)
}

// durableWriteFileFault is durableWriteFile with the §10.3b fault token
// bound. It consults syncIOFault(op, path) at exactly two points — before
// the rename, and after the rename but before the parent-directory fsync —
// so a test can assert that the previous file survives the first window and
// that a run stays recoverable after the second. op == "" disables the seam
// entirely, which is what the tokenless durableWriteFile passes.
func durableWriteFileFault(op, path string, data []byte, mode os.FileMode) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0700); err != nil {
		return fmt.Errorf("create state directory: %w", err)
	}
	tmp, err := os.CreateTemp(dir, ".tws-durable-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName) //nolint:errcheck
	if err := tmp.Chmod(mode); err != nil {
		_ = tmp.Close()
		return err
	}
	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if op != "" {
		// Window 1: the destination still holds its previous bytes.
		if err := syncIOFault(op, path); err != nil {
			return err
		}
	}
	if err := os.Rename(tmpName, path); err != nil {
		return err
	}
	if op != "" {
		// Window 2: the rename landed but the directory entry is not yet
		// durable. The caller MUST treat this as "may or may not have been
		// written", never as "not written".
		if err := syncIOFault(op, path); err != nil {
			return err
		}
	}
	return syncDir(dir)
}

// syncDir opens dir read-only and fsyncs it, which is what makes a completed
// rename durable across a machine crash. A directory that cannot be opened
// or synced is reported, never ignored.
func syncDir(dir string) error {
	handle, err := os.Open(dir)
	if err != nil {
		return err
	}
	syncErr := handle.Sync()
	closeErr := handle.Close()
	if syncErr != nil {
		return syncErr
	}
	return closeErr
}

var reparentRecoverySyncDir = syncDir

func confirmReparentRenameDurable(path string) error {
	return reparentRecoverySyncDir(filepath.Dir(path))
}

// TopoSort returns branches in dependency order (parents before children).
// Returns an error if the graph contains a cycle.
func TopoSort(s Stack) ([]StackEntry, error) {
	// Build adjacency: base → children
	entryMap := make(map[string]StackEntry)
	children := make(map[string][]string)
	inDegree := make(map[string]int)

	for _, e := range s.Branches {
		entryMap[e.Name] = e
		inDegree[e.Name] = 0
	}

	for _, e := range s.Branches {
		// Only count edges where the base is also a tracked branch
		if _, ok := entryMap[e.Base]; ok {
			children[e.Base] = append(children[e.Base], e.Name)
			inDegree[e.Name]++
		}
	}

	// Kahn's algorithm
	var queue []string
	for _, entry := range s.Branches {
		if inDegree[entry.Name] == 0 {
			queue = append(queue, entry.Name)
		}
	}

	var sorted []StackEntry
	for len(queue) > 0 {
		name := queue[0]
		queue = queue[1:]
		sorted = append(sorted, entryMap[name])
		for _, child := range children[name] {
			inDegree[child]--
			if inDegree[child] == 0 {
				queue = append(queue, child)
			}
		}
	}

	if len(sorted) != len(s.Branches) {
		return nil, fmt.Errorf("cycle detected in stack.yaml")
	}
	return sorted, nil
}

// ReparentClosureOrder returns the target and its transitive logical
// descendants in the stable order safe-reparent replays them (§6.1a).
//
// It is deliberately NOT TopoSort, is never called by it, and never modifies
// it. Two differences are load-bearing:
//
//  1. TopoSort orders the whole graph with stack.yaml declaration order as
//     its sibling tie-break. This function applies that same stable,
//     operator-visible ordering only inside the target's reachable closure.
//  2. An edge exists only where child.Base == parent.Name AND the two entries
//     share a repository (SameStackRepo). TopoSort ignores Repo entirely, so
//     an unrelated stack in another repository whose Base merely spells the
//     same name would be pulled in; here it is not a child at all.
//
// The function is pure: it reads only stack, issues no Git command and
// touches no filesystem. An unknown target returns an error, as does a cycle
// among the reachable vertices — callers surface the latter as
// stack-unsortable (current stack) or destination-cycle (post-image graph).
// The target is always element 0.
func ReparentClosureOrder(stack Stack, target string) ([]StackEntry, error) {
	return reparentClosureOrder(stack, target, func(child, parent StackEntry) bool {
		return SameStackRepo(child.Repo, parent.Repo)
	})
}

// ReparentClosureOrderByRepoIdentity is the production reparent graph. The
// identity map is keyed by entry name and contains canonical Git common-dir
// identities measured before graph construction. Missing identities fall back
// to the raw comparison so an unreadable same-token row remains in scope and
// can surface its repo-unavailable blocker instead of disappearing.
func ReparentClosureOrderByRepoIdentity(stack Stack, target string, identities map[string]string) ([]StackEntry, error) {
	return reparentClosureOrder(stack, target, func(child, parent StackEntry) bool {
		if SameStackRepo(child.Repo, parent.Repo) {
			return true
		}
		childID, childOK := identities[child.Name]
		parentID, parentOK := identities[parent.Name]
		if childOK && parentOK && childID != "" && parentID != "" {
			return childID == parentID
		}
		return false
	})
}

func reparentClosureOrder(stack Stack, target string, sameRepo func(StackEntry, StackEntry) bool) ([]StackEntry, error) {
	index := make(map[string]int, len(stack.Branches))
	for i, e := range stack.Branches {
		if _, dup := index[e.Name]; dup {
			return nil, fmt.Errorf("duplicate stack entry %q", e.Name)
		}
		index[e.Name] = i
	}
	if _, ok := index[target]; !ok {
		return nil, fmt.Errorf("entry %q is not in stack.yaml", target)
	}

	children := make(map[string][]string, len(stack.Branches))
	for _, child := range stack.Branches {
		parentIdx, ok := index[child.Base]
		if !ok {
			continue
		}
		parent := stack.Branches[parentIdx]
		if !sameRepo(child, parent) {
			continue
		}
		children[parent.Name] = append(children[parent.Name], child.Name)
	}

	// Vertex set: the target plus everything reachable from it through those
	// edges. The closure is computed first so in-degrees count only edges
	// inside it — an ancestor of the target is not part of the replay.
	member := map[string]bool{target: true}
	stackQueue := []string{target}
	for len(stackQueue) > 0 {
		name := stackQueue[len(stackQueue)-1]
		stackQueue = stackQueue[:len(stackQueue)-1]
		for _, child := range children[name] {
			if member[child] {
				continue
			}
			member[child] = true
			stackQueue = append(stackQueue, child)
		}
	}

	inDegree := make(map[string]int, len(member))
	for name := range member {
		inDegree[name] = 0
	}
	for name := range member {
		for _, child := range children[name] {
			if member[child] {
				inDegree[child]++
			}
		}
	}

	ready := &stackIndexHeap{}
	for name := range member {
		if inDegree[name] == 0 {
			ready.push(index[name])
		}
	}

	ordered := make([]StackEntry, 0, len(member))
	for ready.len() > 0 {
		idx := ready.pop()
		entry := stack.Branches[idx]
		ordered = append(ordered, entry)
		for _, child := range children[entry.Name] {
			if !member[child] {
				continue
			}
			inDegree[child]--
			if inDegree[child] == 0 {
				ready.push(index[child])
			}
		}
	}

	if len(ordered) != len(member) {
		return nil, fmt.Errorf("cycle detected in stack.yaml")
	}
	if ordered[0].Name != target {
		// Unreachable while the closure is rooted at the target, which has
		// in-degree zero inside it; guarded so a future edge rule change can
		// never silently demote the target from row 0.
		return nil, fmt.Errorf("closure order did not start at %q", target)
	}
	return ordered, nil
}

// stackIndexHeap is ReparentClosureOrder's ready set: a min-heap of
// Stack.Branches indices, so the smallest declaration index is always emitted
// first. It is a local, dependency-free binary heap rather than container/heap
// so the ordering rule reads in one place.
type stackIndexHeap struct {
	items []int
}

func (h *stackIndexHeap) len() int { return len(h.items) }

func (h *stackIndexHeap) push(v int) {
	h.items = append(h.items, v)
	i := len(h.items) - 1
	for i > 0 {
		parent := (i - 1) / 2
		if h.items[parent] <= h.items[i] {
			break
		}
		h.items[parent], h.items[i] = h.items[i], h.items[parent]
		i = parent
	}
}

func (h *stackIndexHeap) pop() int {
	top := h.items[0]
	last := len(h.items) - 1
	h.items[0] = h.items[last]
	h.items = h.items[:last]
	i := 0
	for {
		left, right := 2*i+1, 2*i+2
		smallest := i
		if left < len(h.items) && h.items[left] < h.items[smallest] {
			smallest = left
		}
		if right < len(h.items) && h.items[right] < h.items[smallest] {
			smallest = right
		}
		if smallest == i {
			break
		}
		h.items[i], h.items[smallest] = h.items[smallest], h.items[i]
		i = smallest
	}
	return top
}

// Descendants returns all transitive children of the given branch.
func Descendants(s Stack, branch string) map[string]bool {
	children := make(map[string][]string)
	for _, e := range s.Branches {
		children[e.Base] = append(children[e.Base], e.Name)
	}

	result := make(map[string]bool)
	queue := []string{branch}
	for len(queue) > 0 {
		name := queue[0]
		queue = queue[1:]
		for _, child := range children[name] {
			if !result[child] {
				result[child] = true
				queue = append(queue, child)
			}
		}
	}
	return result
}

// PrintTree prints the stack as an indented dependency tree.
func PrintTree(s Stack) {
	children := make(map[string][]string)
	roots := make(map[string]bool)

	for _, e := range s.Branches {
		roots[e.Name] = true
	}
	for _, e := range s.Branches {
		children[e.Base] = append(children[e.Base], e.Name)
		// If base is a tracked branch, this entry is not a root
		for _, other := range s.Branches {
			if other.Name == e.Base {
				delete(roots, e.Name)
				break
			}
		}
	}

	var printNode func(name, prefix string, isLast bool)
	printNode = func(name, prefix string, isLast bool) {
		connector := "├── "
		if isLast {
			connector = "└── "
		}
		fmt.Println(prefix + connector + name)

		childPrefix := prefix
		if isLast {
			childPrefix += "    "
		} else {
			childPrefix += "│   "
		}

		kids := children[name]
		for i, child := range kids {
			printNode(child, childPrefix, i == len(kids)-1)
		}
	}

	// Print from each root's base (usually "main")
	bases := make(map[string]bool)
	for _, e := range s.Branches {
		if roots[e.Name] {
			bases[e.Base] = true
		}
	}

	for base := range bases {
		fmt.Printf("(%s)\n", base)
		kids := children[base]
		for i, child := range kids {
			printNode(child, "", i == len(kids)-1)
		}
	}

	if len(s.Branches) == 0 {
		fmt.Println("No branches tracked. Use 'ts new <feature> <branch>' to add branches.")
	}
}

// FormatBranchStatus formats a branch sync result for display.
func FormatBranchStatus(name, status string) string {
	symbols := map[string]string{
		"synced":  "+",
		"failed":  "x",
		"skipped": "-",
	}
	sym := symbols[status]
	if sym == "" {
		sym = "?"
	}
	return fmt.Sprintf("  [%s] %s", sym, name)
}

// DescendantsList returns Descendants as a sorted display string.
func DescendantsList(s Stack, branch string) string {
	descs := Descendants(s, branch)
	var names []string
	for name := range descs {
		names = append(names, name)
	}
	return strings.Join(names, ", ")
}

package internal

import (
	"errors"
	"fmt"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"unicode"
)

// ---------- Enums ----------

// StackBaseKind describes how a stack entry's base was resolved to a Git ref.
type StackBaseKind string

// StackBaseRecord describes the state of the recorded LastBaseSHA.
type StackBaseRecord string

// StackRepoSource records which candidate produced the evaluated repository.
type StackRepoSource string

// StackAncestryReason is the precise cause behind a StackEdge status.
type StackAncestryReason string

// StackNoteKind enumerates informational per-edge notes.
type StackNoteKind string

// StackBasePolicy names the sync path whose base resolution the evaluator
// compares its own probe against when emitting identity notes. It is selected
// explicitly by the caller because the two sync implementations resolve a
// configured base differently, and reporting the wrong one is a false claim.
type StackBasePolicy string

const (
	StackBaseStackEntry StackBaseKind = "stack-entry"
	StackBaseLiteralRef StackBaseKind = "literal-ref"
	StackBaseNone       StackBaseKind = "none"
)

const (
	// StackBasePolicyNone makes no claim about any sync path and therefore
	// emits no identity note at all.
	StackBasePolicyNone StackBasePolicy = ""
	// StackBasePolicyRemoteDefault mirrors external sync, which maps a base
	// equal to the repository default branch to `origin/<default>`.
	StackBasePolicyRemoteDefault StackBasePolicy = "remote-default"
	// StackBasePolicyLiteralEntry mirrors checkout sync, which resolves
	// `entry.Base` literally instead of through the parent's GitBranch().
	StackBasePolicyLiteralEntry StackBasePolicy = "literal-entry"
)

// StackAncestryOptions carries the evaluator behaviour that depends on which
// sync path the caller's workspace mode would actually run. The zero value is
// safe: it emits no identity notes.
type StackAncestryOptions struct {
	BasePolicy StackBasePolicy
}

// StackBasePolicyForMode maps a workspace mode to the base resolution its sync
// path actually performs. External sync resolves the default branch through
// `origin/<default>`; checkout sync resolves `entry.Base` literally.
func StackBasePolicyForMode(mode WorkspaceMode) StackBasePolicy {
	if mode == ModeCheckout {
		return StackBasePolicyLiteralEntry
	}
	return StackBasePolicyRemoteDefault
}

const (
	StackBaseRecordAbsent       StackBaseRecord = "absent"
	StackBaseRecordPresent      StackBaseRecord = "present"
	StackBaseRecordUnresolvable StackBaseRecord = "unresolvable"
)

const (
	StackRepoWorkspace   StackRepoSource = "workspace"
	StackRepoWorktree    StackRepoSource = "worktree"
	StackRepoInferred    StackRepoSource = "inferred"
	StackRepoUnavailable StackRepoSource = "unavailable"
)

const (
	ReasonParentContained            StackAncestryReason = "parent-contained"
	ReasonParentAdvanced             StackAncestryReason = "parent-advanced"
	ReasonParentAdvancedNoBaseRecord StackAncestryReason = "parent-advanced-no-base-record"
	ReasonBaseRecordUnresolvable     StackAncestryReason = "base-record-unresolvable"
	ReasonBaseRewritten              StackAncestryReason = "base-rewritten"
	ReasonUnrelatedHistories         StackAncestryReason = "unrelated-histories"
	ReasonChildRefMissing            StackAncestryReason = "child-ref-missing"
	ReasonBaseRefMissing             StackAncestryReason = "base-ref-missing"
	ReasonCrossRepo                  StackAncestryReason = "cross-repo"
	ReasonBaseUnset                  StackAncestryReason = "base-unset"
	ReasonRepoUnavailable            StackAncestryReason = "repo-unavailable"
	ReasonAncestryProbeFailed        StackAncestryReason = "ancestry-probe-failed"
)

const (
	NoteBaseIdentityRemoteMismatch  StackNoteKind = "base-identity-remote-mismatch"
	NoteBaseIdentityLiteralMismatch StackNoteKind = "base-identity-literal-mismatch"
	NoteCutoffInvalid               StackNoteKind = "cutoff-invalid"
)

// RepoSourceMismatchLabel names the feature-level condition raised when the
// workspace and the feature's own worktree evidence resolve to two different
// main repository roots. It is derived from StackRepoResolution.Alternate and
// is never stored on a StackEdge.
const RepoSourceMismatchLabel = "repo-source-mismatch"

// ancestryUnevaluatedToken is the single source of the human display token for
// an edge that reached no ancestry conclusion. It is never an AncestryStatus.
const ancestryUnevaluatedToken = "unevaluated"

// ancestrySanitizeLimit bounds recorded metadata echoed back to the user.
const ancestrySanitizeLimit = 40

// ancestryPathLimit bounds filesystem paths echoed back to the user. Paths are
// routinely longer than a ref name and a 40-rune prefix identifies nothing.
const ancestryPathLimit = 200

// ancestryDetailLimit bounds error text echoed back to the user.
const ancestryDetailLimit = 200

// ancestryFullSHA matches a peeled object name exactly. rev-parse output is
// validated against it so a malformed or ambiguous answer is never carried
// into a comparison or into a command shown to the user.
var ancestryFullSHA = regexp.MustCompile(`^[0-9a-f]{40}$`)

// ancestryPlainCommandToken matches the tokens that need no shell quoting when
// interpolated into a runnable command.
var ancestryPlainCommandToken = regexp.MustCompile(`^[A-Za-z0-9._/@+-]+$`)

// ErrRepoUnavailable is returned when ancestry evaluation cannot start because
// the source repository directory is empty or is not a Git repository.
var ErrRepoUnavailable = errors.New("stack ancestry: source repository unavailable")

// ---------- Structs ----------

// StackEdgeNote is an informational observation attached to one edge. It never
// changes status, severity, or any issue count.
type StackEdgeNote struct {
	Kind   StackNoteKind `json:"kind"`
	Detail string        `json:"detail"`
}

// StackEdge is the read-only projection of one configured parent-child edge.
type StackEdge struct {
	Feature   string `json:"feature"`
	Name      string `json:"name"`
	GitBranch string `json:"git_branch"`
	Archived  bool   `json:"archived"`
	Repo      string `json:"repo,omitempty"`

	BaseName string        `json:"base_name"`
	BaseKind StackBaseKind `json:"base_kind"`
	BaseRef  string        `json:"base_ref,omitempty"`

	ChildRef  string `json:"child_ref,omitempty"`
	RefExists bool   `json:"ref_exists"`
	RefProbed bool   `json:"ref_probed"`

	LocalHead       string  `json:"local_head,omitempty"`
	LocalHeadShort  string  `json:"local_head_short,omitempty"`
	ParentHead      string  `json:"parent_head,omitempty"`
	ParentHeadShort string  `json:"parent_head_short,omitempty"`
	MergeBase       *string `json:"merge_base"`
	MergeBaseShort  string  `json:"merge_base_short,omitempty"`

	LastBaseSHA     string             `json:"last_base_sha,omitempty"`
	LastBaseCommit  string             `json:"last_base_commit,omitempty"`
	LastBaseShort   string             `json:"last_base_short,omitempty"`
	BaseRecord      StackBaseRecord    `json:"base_record"`
	EffectiveCutoff string             `json:"effective_cutoff,omitempty"`
	CutoffSource    SyncCutoffSource   `json:"cutoff_source,omitempty"`
	CutoffValidity  SyncCutoffValidity `json:"cutoff_validity,omitempty"`
	CutoffReason    SyncCutoffReason   `json:"cutoff_reason,omitempty"`

	Status   AncestryStatus      `json:"status"`
	Reason   StackAncestryReason `json:"reason"`
	Severity CheckoutSeverity    `json:"severity"`
	Guidance string              `json:"guidance,omitempty"`
	Notes    []StackEdgeNote     `json:"notes,omitempty"`

	RepoSource StackRepoSource `json:"repo_source"`
}

// StackRepoResolution is the outcome of mode-aware repository selection.
type StackRepoResolution struct {
	RepoDir   string
	Source    StackRepoSource
	Alternate string
	Reason    string
}

type refResolution struct {
	full  string
	short string
	ok    bool
}

// ancestryEvaluator holds the per-evaluation caches. It is never global, never
// persisted, and never shared between calls.
type ancestryEvaluator struct {
	repoDir       string
	basePolicy    StackBasePolicy
	refs          map[string]refResolution
	shorts        map[string]string
	defaultBranch string
	defaultDone   bool
}

// ---------- Git runner ----------

// ancestryGit builds a read-only Git invocation rooted at a pre-validated,
// non-empty repository directory. cmd.Dir is used rather than -C so results
// never depend on the caller's working directory.
func ancestryGit(repoDir string, args ...string) *exec.Cmd {
	cmd := exec.Command("git", args...)
	cmd.Dir = repoDir
	cmd.Stderr = nil
	return cmd
}

// ---------- Primitives ----------

func newAncestryEvaluator(repoDir string, opts StackAncestryOptions) (*ancestryEvaluator, error) {
	if repoDir == "" {
		return nil, fmt.Errorf("%w: %s", ErrRepoUnavailable, "empty repository directory")
	}
	if _, err := MainRepoRootIn(repoDir); err != nil {
		return nil, fmt.Errorf("%w: %s is not a git repository", ErrRepoUnavailable, ancestrySanitize(repoDir, ancestryPathLimit))
	}
	return &ancestryEvaluator{
		repoDir:    repoDir,
		basePolicy: opts.BasePolicy,
		refs:       make(map[string]refResolution),
		shorts:     make(map[string]string),
	}, nil
}

// resolveCommit peels ref to a commit. Negative results are cached, so a
// repeated unresolvable ref costs one process for the whole evaluation. Output
// that is not structurally a full object name is treated as no answer at all.
func (ev *ancestryEvaluator) resolveCommit(ref string) (string, string, bool) {
	if cached, ok := ev.refs[ref]; ok {
		return cached.full, cached.short, cached.ok
	}
	var res refResolution
	out, err := ancestryGit(ev.repoDir, "rev-parse", "--verify", "--quiet", "--end-of-options", ref+"^{commit}").Output()
	if err == nil {
		if full := strings.TrimSpace(string(out)); ancestryFullSHA.MatchString(full) {
			res.full = full
			res.ok = true
		}
	}
	if res.ok {
		res.short = ev.abbrev(res.full)
	}
	ev.refs[ref] = res
	return res.full, res.short, res.ok
}

func (ev *ancestryEvaluator) abbrev(full string) string {
	if full == "" {
		return ""
	}
	if cached, ok := ev.shorts[full]; ok {
		return cached
	}
	short := ""
	if out, err := ancestryGit(ev.repoDir, "rev-parse", "--short", full).Output(); err == nil {
		short = strings.TrimSpace(string(out))
	}
	if short == "" {
		if len(full) > 12 {
			short = full[:12]
		} else {
			short = full
		}
	}
	ev.shorts[full] = short
	return short
}

func (ev *ancestryEvaluator) defaultBranchName() string {
	if ev.defaultDone {
		return ev.defaultBranch
	}
	ev.defaultDone = true
	branch, err := DefaultBranchIn(ev.repoDir)
	if err != nil {
		branch = ""
	}
	ev.defaultBranch = branch
	return branch
}

// ancestryMergeBase reports the merge base of two peeled commits. Exit 1 with
// empty stdout means "no merge base"; any other non-zero exit is an error and
// is never read as a normal answer.
func ancestryMergeBase(repoDir, a, b string) (string, bool, error) {
	out, err := ancestryGit(repoDir, "merge-base", a, b).Output()
	trimmed := strings.TrimSpace(string(out))
	if err == nil {
		if trimmed == "" {
			return "", false, nil
		}
		return trimmed, true, nil
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 && trimmed == "" {
		return "", false, nil
	}
	return "", false, err
}

// ---------- Classification ----------

// stackBaseRef selects the ref actually probed for an entry's base. A logical
// stack-entry name wins over a literal ref, matching GetBranch's first-match
// order.
func stackBaseRef(stack Stack, se StackEntry) (string, StackBaseKind) {
	if se.Base == "" {
		return "", StackBaseNone
	}
	for _, parent := range stack.Branches {
		if parent.Name == se.Base {
			return "refs/heads/" + parent.GitBranch(), StackBaseStackEntry
		}
	}
	return se.Base, StackBaseLiteralRef
}

func ancestrySeverity(status AncestryStatus, archived bool) CheckoutSeverity {
	switch status {
	case AncestryStatusCurrent:
		return SeverityOK
	case AncestryStatusStale, AncestryStatusDivergent, AncestryStatusMissing:
		if archived {
			return SeverityInfo
		}
		return SeverityWarning
	default:
		return SeverityInfo
	}
}

// newStackEdge fills the identity and base-selection fields that every edge
// carries, whatever happens afterwards. BaseRecord is deliberately left at its
// zero value: it is a statement about an evaluation that has not run yet, and
// claiming `absent` here would be a claim the evaluator cannot support.
func newStackEdge(feature string, se StackEntry, stack Stack) StackEdge {
	baseRef, baseKind := stackBaseRef(stack, se)
	return StackEdge{
		Feature:     feature,
		Name:        se.Name,
		GitBranch:   se.GitBranch(),
		Archived:    se.Archived,
		Repo:        se.Repo,
		BaseName:    se.Base,
		BaseKind:    baseKind,
		BaseRef:     baseRef,
		LastBaseSHA: se.LastBaseSHA,
	}
}

func finishStackEdge(e StackEdge, status AncestryStatus, reason StackAncestryReason, detail string) StackEdge {
	e.Status = status
	e.Reason = reason
	e.Severity = ancestrySeverity(status, e.Archived)
	e.Guidance = ancestryGuidance(e, detail)
	return e
}

func (ev *ancestryEvaluator) edge(feature string, se StackEntry, stack Stack) StackEdge {
	e := newStackEdge(feature, se, stack)

	// Rule 1: a cross-repo entry is a metadata-only decision. No Git process
	// is started for it, against any path.
	if se.Repo != "" {
		return finishStackEdge(e, AncestryStatusCrossRepo, ReasonCrossRepo, "")
	}
	// Rule 2: nothing to compare against.
	if se.Base == "" {
		return finishStackEdge(e, "", ReasonBaseUnset, "")
	}

	// Rule 3: the child ref, always through refs/heads/ so a same-named tag
	// can never win.
	e.ChildRef = "refs/heads/" + e.GitBranch
	e.RefProbed = true
	childFull, childShort, childOK := ev.resolveCommit(e.ChildRef)
	if !childOK {
		return finishStackEdge(e, AncestryStatusMissing, ReasonChildRefMissing, "")
	}
	e.RefExists = true
	e.LocalHead = childFull
	e.LocalHeadShort = childShort

	// Rule 5: the base ref, exactly as selected above.
	parentFull, parentShort, parentOK := ev.resolveCommit(e.BaseRef)
	if !parentOK {
		return finishStackEdge(e, AncestryStatusMissing, ReasonBaseRefMissing, "")
	}
	e.ParentHead = parentFull
	e.ParentHeadShort = parentShort

	// Rule 6: the recorded base commit, peeled because both writers record an
	// unpeeled rev-parse result. This is the first point at which the record
	// is actually consulted, so it is also the first point at which any
	// BaseRecord verdict — including `absent` — can be stated truthfully.
	if se.LastBaseSHA == "" {
		e.BaseRecord = StackBaseRecordAbsent
	} else if lastFull, lastShort, ok := ev.resolveCommit(se.LastBaseSHA); ok {
		e.BaseRecord = StackBaseRecordPresent
		e.LastBaseCommit = lastFull
		e.LastBaseShort = lastShort
	} else {
		e.BaseRecord = StackBaseRecordUnresolvable
	}

	decision, cutoffErr := ResolveSyncCutoff(SyncCutoffResolveInput{
		RepoDir: ev.repoDir, Entry: se.Name, GitBranch: se.GitBranch(),
		ParentRef: e.BaseRef, ParentSHA: e.ParentHead, ChildSHA: e.LocalHead,
		Recorded: se.LastBaseSHA, Applicable: true,
	})
	e.EffectiveCutoff = decision.EffectiveSHA
	e.CutoffSource = decision.Source
	e.CutoffValidity = decision.Validity
	e.CutoffReason = decision.Reason
	if cutoffErr != nil {
		recorded := "<absent>"
		if se.LastBaseSHA != "" {
			recorded = ancestrySanitize(se.LastBaseSHA, ancestrySanitizeLimit)
		}
		e.Notes = append(e.Notes, StackEdgeNote{
			Kind: NoteCutoffInvalid,
			Detail: fmt.Sprintf("sync cutoff is invalid (%s; recorded %s); inspect stack.yaml and known parent history before syncing — tws will not infer a replacement boundary",
				decision.Reason, recorded),
		})
	}

	e = ev.classify(e)
	if e.Status != "" && e.Status != AncestryStatusCrossRepo {
		e.Notes = append(e.Notes, ev.identityNotes(e)...)
	}
	return e
}

// classify applies the first-match classification table. Order is normative.
func (ev *ancestryEvaluator) classify(e StackEdge) StackEdge {
	// 1. The parent is already contained in the child: nothing to replay,
	// whichever way the parent moved.
	contained, err := gitIsAncestor(ev.repoDir, e.ParentHead, e.LocalHead)
	if err != nil {
		return finishStackEdge(e, "", ReasonAncestryProbeFailed, err.Error())
	}
	if contained {
		merge := e.ParentHead
		e.MergeBase = &merge
		e.MergeBaseShort = ev.abbrev(merge)
		return finishStackEdge(e, AncestryStatusCurrent, ReasonParentContained, "")
	}

	// 2. Unrelated histories get their own reason instead of a rewrite claim.
	mergeBase, exists, mbErr := ancestryMergeBase(ev.repoDir, e.LocalHead, e.ParentHead)
	if mbErr != nil {
		return finishStackEdge(e, "", ReasonAncestryProbeFailed, mbErr.Error())
	}
	if !exists {
		return finishStackEdge(e, AncestryStatusDivergent, ReasonUnrelatedHistories, "")
	}
	merge := mergeBase
	e.MergeBase = &merge
	e.MergeBaseShort = ev.abbrev(merge)

	// 4/5. A resolvable record separates "the parent advanced" from "the
	// parent's history was rewritten".
	if e.BaseRecord == StackBaseRecordPresent {
		recorded, recErr := gitIsAncestor(ev.repoDir, e.LastBaseCommit, e.ParentHead)
		switch {
		case recErr != nil:
			// Degrade to rule 3 rather than reading a fatal exit as "no".
			e.BaseRecord = StackBaseRecordUnresolvable
			e.LastBaseCommit = ""
			e.LastBaseShort = ""
		case !recorded:
			return finishStackEdge(e, AncestryStatusDivergent, ReasonBaseRewritten, "")
		default:
			return finishStackEdge(e, AncestryStatusStale, ReasonParentAdvanced, "")
		}
	}

	// 3. A recorded base that is not in this repository can support no claim.
	if e.BaseRecord == StackBaseRecordUnresolvable {
		return finishStackEdge(e, AncestryStatusStale, ReasonBaseRecordUnresolvable, "")
	}

	// 6. Nothing was ever recorded.
	return finishStackEdge(e, AncestryStatusStale, ReasonParentAdvancedNoBaseRecord, "")
}

// identityNotes reports, without acting on it, that the caller's sync path
// would resolve this edge's base to a different commit than the one doctor
// probed. Only the policy the caller selected can be reported: emitting the
// other mode's note would describe a sync path that will never run here.
func (ev *ancestryEvaluator) identityNotes(e StackEdge) []StackEdgeNote {
	if e.ParentHead == "" {
		return nil
	}
	switch ev.basePolicy {
	case StackBasePolicyRemoteDefault:
		return ev.remoteMismatchNotes(e)
	case StackBasePolicyLiteralEntry:
		return ev.literalMismatchNotes(e)
	default:
		return nil
	}
}

// remoteMismatchNotes mirrors external sync, which maps a base equal to the
// default branch to origin/<default> and records that SHA.
func (ev *ancestryEvaluator) remoteMismatchNotes(e StackEdge) []StackEdgeNote {
	if e.BaseKind != StackBaseLiteralRef {
		return nil
	}
	if e.BaseName == "" || e.BaseName != ev.defaultBranchName() {
		return nil
	}
	altFull, altShort, ok := ev.resolveCommit("refs/remotes/origin/" + e.BaseName)
	if !ok || altFull == e.ParentHead {
		return nil
	}
	return []StackEdgeNote{{
		Kind: NoteBaseIdentityRemoteMismatch,
		Detail: fmt.Sprintf("base %q is probed as %s, but tws sync resolves it as origin/%s (%s)",
			ancestrySanitize(e.BaseName, ancestrySanitizeLimit), e.ParentHeadShort,
			ancestrySanitize(e.BaseName, ancestrySanitizeLimit), altShort),
	}}
}

// literalMismatchNotes mirrors checkout sync, which resolves entry.Base
// literally instead of through the parent entry's GitBranch().
func (ev *ancestryEvaluator) literalMismatchNotes(e StackEdge) []StackEdgeNote {
	if e.BaseKind != StackBaseStackEntry {
		return nil
	}
	parentBranch := strings.TrimPrefix(e.BaseRef, "refs/heads/")
	if parentBranch == e.BaseName {
		return nil
	}
	altFull, altShort, ok := ev.resolveCommit(e.BaseName)
	if !ok || altFull == e.ParentHead {
		return nil
	}
	return []StackEdgeNote{{
		Kind: NoteBaseIdentityLiteralMismatch,
		Detail: fmt.Sprintf("base name %q also resolves as a literal ref to %s, which differs from parent branch %q (%s); checkout sync resolves the literal name",
			ancestrySanitize(e.BaseName, ancestrySanitizeLimit), altShort,
			ancestrySanitize(parentBranch, ancestrySanitizeLimit), e.ParentHeadShort),
	}}
}

// ---------- Presentation ----------

// ancestryDisplayStatus is the only producer of the unevaluated display token.
func ancestryDisplayStatus(s AncestryStatus) string {
	if s == "" {
		return ancestryUnevaluatedToken
	}
	return string(s)
}

// ancestrySanitize replaces non-printable runes and bounds length. It is a
// display rule only; classification always uses raw values.
func ancestrySanitize(s string, limit int) string {
	var b strings.Builder
	count := 0
	truncated := false
	for _, r := range s {
		if count >= limit {
			truncated = true
			break
		}
		if unicode.IsPrint(r) {
			b.WriteRune(r)
		} else {
			b.WriteRune('?')
		}
		count++
	}
	if truncated {
		b.WriteRune('…')
	}
	return b.String()
}

// ancestryCommandToken renders a Git-validated ref or object name for
// interpolation into a runnable command. Control characters are replaced, but
// the token is never truncated: a shortened ref or SHA yields a command that
// silently targets the wrong thing or does not run at all. Anything outside
// the portable unquoted set is single-quoted so the command stays pasteable.
func ancestryCommandToken(s string) string {
	if s == "" {
		return ""
	}
	var b strings.Builder
	for _, r := range s {
		if unicode.IsPrint(r) {
			b.WriteRune(r)
		} else {
			b.WriteRune('?')
		}
	}
	token := b.String()
	if ancestryPlainCommandToken.MatchString(token) {
		return token
	}
	return "'" + strings.ReplaceAll(token, "'", `'\''`) + "'"
}

// ancestryChildCommandToken is the child branch the repair command must name
// explicitly, so the rebase can never take whatever happens to be checked out
// as its target.
//
// It is the bare branch name, not `refs/heads/<branch>`: `git rebase`'s third
// argument is checked out, and a fully-qualified ref does not resolve to a
// branch there — Git would detach HEAD, replay onto the detached HEAD, and
// leave the child branch untouched. A bare name resolves to the branch even
// when a tag shares the name, which is exactly the target intended here.
func ancestryChildCommandToken(e StackEdge) string {
	if e.GitBranch == "" {
		return ""
	}
	return ancestryCommandToken(e.GitBranch)
}

// ancestryDetail reduces arbitrary error text to a single sanitized line.
func ancestryDetail(detail string) string {
	line := detail
	if idx := strings.IndexAny(line, "\r\n"); idx >= 0 {
		line = line[:idx]
	}
	return ancestrySanitize(strings.TrimSpace(line), ancestryDetailLimit)
}

// ancestryGuidance is pure and total over every reason. It never returns a
// string containing a newline. Prose interpolations stay abbreviated for
// readability; every token inside a backticked command is complete.
func ancestryGuidance(e StackEdge, detail string) string {
	feature := ancestrySanitize(e.Feature, ancestrySanitizeLimit)
	name := ancestrySanitize(e.Name, ancestrySanitizeLimit)
	branch := ancestrySanitize(e.GitBranch, ancestrySanitizeLimit)
	baseRef := ancestrySanitize(e.BaseRef, ancestrySanitizeLimit)
	parent := e.ParentHeadShort

	recorded := e.LastBaseShort
	if e.BaseRecord != StackBaseRecordPresent {
		recorded = fmt.Sprintf("%q", ancestrySanitize(e.LastBaseSHA, ancestrySanitizeLimit))
	}

	switch e.Reason {
	case ReasonParentContained:
		return ""
	case ReasonParentAdvanced:
		return fmt.Sprintf("parent `%s` advanced to %s; run: tws sync %s", baseRef, parent, feature)
	case ReasonParentAdvancedNoBaseRecord:
		return fmt.Sprintf("parent `%s` advanced to %s, but no recorded cutoff exists and sync will refuse rather than guess the child-owned range; inspect known creation or last-sync history, then repair last_base_sha from a proven commit before retrying feature %s", baseRef, parent, feature)
	case ReasonBaseRecordUnresolvable:
		return fmt.Sprintf("recorded base commit %s is not present in this repository; the replay strategy cannot be verified — inspect before running: tws sync %s", recorded, feature)
	case ReasonBaseRewritten:
		return fmt.Sprintf("recorded base commit %s is no longer in `%s` history;%s run: tws sync %s",
			recorded, baseRef, ancestryRebaseRepair(e), feature)
	case ReasonUnrelatedHistories:
		return fmt.Sprintf("`%s` and `%s` share no common history; check the configured base — a rebase would replay every commit", branch, baseRef)
	case ReasonChildRefMissing:
		if e.Archived {
			return fmt.Sprintf("archived branch `%s` has no git ref", branch)
		}
		// The stack entry already exists, so no creation command applies here.
		// The only honest recoveries are restoring the Git branch or
		// deliberately changing the recorded stack.
		return fmt.Sprintf("git branch `%s` does not exist while stack entry %q of feature %s is still configured; restore the branch from its remote or from a known commit, for example `git branch %s <known-commit>`, or deliberately remove and recreate the stack entry if no work must be preserved",
			branch, name, feature, ancestryCommandToken(e.GitBranch))
	case ReasonBaseRefMissing:
		return fmt.Sprintf("base ref `%s` does not exist; restore it or update `base` in stack.yaml", baseRef)
	case ReasonCrossRepo:
		return fmt.Sprintf("entry targets another repository (%s); cross-repo ancestry is not evaluated, so this edge is reported as cross-repo-unsupported", ancestrySanitize(e.Repo, ancestryPathLimit))
	case ReasonBaseUnset:
		return "no base configured for this entry; ancestry is not evaluated"
	case ReasonRepoUnavailable:
		return fmt.Sprintf("source repository could not be determined; ancestry is not evaluated (%s)", ancestryDetail(detail))
	case ReasonAncestryProbeFailed:
		return fmt.Sprintf("ancestry probe failed (%s); refs may have changed during evaluation — the recorded base was not consulted; re-run: tws doctor %s", ancestryDetail(detail), feature)
	default:
		return ""
	}
}

// ancestryRebaseRepair renders the complete `--onto` repair command, including
// the explicit target child branch. It is emitted only when every token is a
// value the evaluator itself resolved, so the command is always complete and
// pasteable, never a truncated fragment; otherwise the guidance simply omits
// it. It carries the same precondition tws sync's own `--onto` invocation
// carries — the recorded base is used as `<upstream>` in both — so it is
// offered as an equivalent repair, not as a guarantee about the child's own
// history.
//
// The wording deliberately stops at "an --onto rebase": the two sync paths do
// not run the same command. External sync adds `--update-refs` and rebases the
// checked-out worktree branch; checkout sync adds `--no-fork-point` and rebases
// onto the resolved new base SHA. Promising an identical strategy would be a
// claim this evaluator cannot support.
func ancestryRebaseRepair(e StackEdge) string {
	child := ancestryChildCommandToken(e)
	base := ancestryCommandToken(e.BaseRef)
	if child == "" || base == "" || !ancestryFullSHA.MatchString(e.LastBaseCommit) {
		return ""
	}
	return fmt.Sprintf(" an equivalent manual repair is `git rebase --onto %s %s %s`; tws sync also replays this edge with an --onto rebase, using the flags its own workspace mode requires;",
		base, e.LastBaseCommit, child)
}

// ---------- Core API ----------

// EvaluateStackAncestry classifies every configured edge of one feature's
// stack against a validated repository directory. It is mode-independent,
// strictly read-only, and never writes Git or metadata state. The caller
// states which sync path's base policy the identity notes should describe;
// the zero options value emits no notes.
func EvaluateStackAncestry(repoDir, feature string, stack Stack, opts StackAncestryOptions) ([]StackEdge, error) {
	ev, err := newAncestryEvaluator(repoDir, opts)
	if err != nil {
		return nil, err
	}
	edges := make([]StackEdge, 0, len(stack.Branches))
	for _, se := range stack.Branches {
		edges = append(edges, ev.edge(feature, se, stack))
	}
	return edges, nil
}

// EvaluateStackEdge is the single-edge form. It allocates a fresh cache and
// applies the same repository validation and base policy.
func EvaluateStackEdge(repoDir, feature string, se StackEntry, stack Stack, opts StackAncestryOptions) (StackEdge, error) {
	ev, err := newAncestryEvaluator(repoDir, opts)
	if err != nil {
		return StackEdge{}, err
	}
	return ev.edge(feature, se, stack), nil
}

// UnevaluatedStackEdges projects a stack without starting any Git process.
// Cross-repo and base-less entries keep their own meaning so an entry never
// changes classification merely because the repository was unresolvable.
func UnevaluatedStackEdges(feature string, stack Stack, reason StackAncestryReason, detail string) []StackEdge {
	edges := make([]StackEdge, 0, len(stack.Branches))
	for _, se := range stack.Branches {
		e := newStackEdge(feature, se, stack)
		e.RepoSource = StackRepoUnavailable
		switch {
		case se.Repo != "":
			e = finishStackEdge(e, AncestryStatusCrossRepo, ReasonCrossRepo, "")
		case se.Base == "":
			e = finishStackEdge(e, "", ReasonBaseUnset, "")
		default:
			e = finishStackEdge(e, "", reason, detail)
		}
		edges = append(edges, e)
	}
	return edges
}

// ---------- Mode-aware adapter ----------

// ancestryRepoCandidate normalises a filesystem path to a canonical main
// repository root, or reports that it is not usable. It never runs Git on an
// empty path.
func ancestryRepoCandidate(path string) (string, bool) {
	if path == "" {
		return "", false
	}
	root, err := MainRepoRootIn(path)
	if err != nil {
		return "", false
	}
	return canonicalize(root), true
}

// ancestryWorktreeCandidatePath contains an untrusted logical entry name below
// the feature's worktrees directory before any Git process is started.
func ancestryWorktreeCandidatePath(featurePath, name string) (string, error) {
	if name == "" || !filepath.IsLocal(name) || filepath.Clean(name) == "." {
		return "", fmt.Errorf("unsafe stack entry name %q", ancestrySanitize(name, ancestrySanitizeLimit))
	}
	worktreesRoot := filepath.Join(featurePath, "worktrees")
	candidate := filepath.Join(worktreesRoot, name)
	canonRoot := canonicalize(worktreesRoot)
	canonCandidate := canonicalize(candidate)
	rel, err := filepath.Rel(canonRoot, canonCandidate)
	if err != nil || rel == "." || !filepath.IsLocal(rel) {
		return "", fmt.Errorf("stack entry %q resolves outside the feature worktrees directory", ancestrySanitize(name, ancestrySanitizeLimit))
	}
	return candidate, nil
}

// ResolveStackAncestryRepo is the only mode-aware code in this feature. It
// returns a canonical main repository root, never a linked-worktree path.
func ResolveStackAncestryRepo(ws Workspace, cfg Config, featurePath string, stack Stack) StackRepoResolution {
	if ws.Mode == ModeCheckout {
		if root, ok := ancestryRepoCandidate(ws.RepoRoot); ok {
			return StackRepoResolution{RepoDir: root, Source: StackRepoWorkspace}
		}
		return StackRepoResolution{
			Source: StackRepoUnavailable,
			Reason: "checkout workspace repository root is not a git repository",
		}
	}

	// Candidate 1 — feature-scoped worktree evidence. It is the only source
	// that stays correct when TWS_ROOT points at another repository.
	for _, se := range stack.Branches {
		if se.Repo != "" || se.Archived {
			continue
		}
		candidate, err := ancestryWorktreeCandidatePath(featurePath, se.Name)
		if err != nil {
			return StackRepoResolution{Source: StackRepoUnavailable, Reason: err.Error()}
		}
		root, ok := ancestryRepoCandidate(candidate)
		if !ok {
			continue
		}
		res := StackRepoResolution{RepoDir: root, Source: StackRepoWorktree}
		if alt, altOK := ancestryRepoCandidate(ws.RepoRoot); altOK && alt != root {
			res.Alternate = alt
		}
		return res
	}

	// Candidate 2 — the resolved workspace repository root.
	if root, ok := ancestryRepoCandidate(ws.RepoRoot); ok {
		return StackRepoResolution{RepoDir: root, Source: StackRepoWorkspace}
	}

	// Candidate 3 — inference from the metadata root.
	metadataRoot := ws.MetadataRoot
	if metadataRoot == "" {
		metadataRoot = filepath.Dir(featurePath)
	}
	if metadataRoot != "" {
		inferred, err := inferExternalRepoRoot(metadataRoot, cfg)
		if err == nil && inferred != "" {
			return StackRepoResolution{RepoDir: canonicalize(inferred), Source: StackRepoInferred}
		}
		if err != nil {
			return StackRepoResolution{Source: StackRepoUnavailable, Reason: err.Error()}
		}
	}
	return StackRepoResolution{
		Source: StackRepoUnavailable,
		Reason: fmt.Sprintf("no source repository for feature %s", ancestrySanitize(filepath.Base(featurePath), ancestrySanitizeLimit)),
	}
}

// FeatureStackEdges resolves the repository for one feature and evaluates its
// stack. It fails soft: an unusable repository yields unevaluated edges, never
// an error and never a false ancestry claim. The identity-note base policy is
// selected from the workspace mode, so an edge only ever reports the base
// resolution the sync path that would actually run performs.
func FeatureStackEdges(ws Workspace, cfg Config, feature, featurePath string, stack Stack) ([]StackEdge, StackRepoResolution) {
	res := ResolveStackAncestryRepo(ws, cfg, featurePath, stack)
	if res.RepoDir == "" {
		return UnevaluatedStackEdges(feature, stack, ReasonRepoUnavailable, res.Reason), res
	}
	opts := StackAncestryOptions{BasePolicy: StackBasePolicyForMode(ws.Mode)}
	edges, err := EvaluateStackAncestry(res.RepoDir, feature, stack, opts)
	if err != nil {
		failed := StackRepoResolution{Source: StackRepoUnavailable, Reason: err.Error()}
		return UnevaluatedStackEdges(feature, stack, ReasonRepoUnavailable, err.Error()), failed
	}
	for i := range edges {
		edges[i].RepoSource = res.Source
	}
	return edges, res
}

// ---------------------------------------------------------------------------
// §11.10 rule 2 — the ancestry guidance suppression seam
//
// This is a SEAM ONLY: no ancestry decision changes. EvaluateStackAncestry,
// FeatureStackEdges, stackBaseRef and ancestryMergeBase are untouched, every
// edge keeps its Status, Reason, Severity and Notes, and only the repair
// GUIDANCE — the `tws sync <feature>` / manual `git rebase --onto` advice — is
// withheld while a reparent artifact exists. Following that advice mid-reparent
// would bypass the transaction, and the sync verbs it names are refused by
// §11.2 anyway.
// ---------------------------------------------------------------------------

// SuppressReparentAncestryGuidance returns a copy of edges with every
// Guidance string cleared. Notes keep their own details: a note is an
// observation, never an instruction to run a refused verb.
func SuppressReparentAncestryGuidance(edges []StackEdge) []StackEdge {
	out := make([]StackEdge, len(edges))
	copy(out, edges)
	for i := range out {
		out[i].Guidance = ""
	}
	return out
}

// ReparentGuidanceSuppressed answers whether a surface must apply the seam for
// one feature of one workspace. It is a bare os.Stat through
// HasReparentState: strictly read-only, no decode, no Git child, and it never
// evaluates the §12.3 remote follow-up record.
func ReparentGuidanceSuppressed(ws Workspace, feature, featurePath string) bool {
	return HasReparentState(ReparentLocationFor(ws, feature, featurePath))
}

