	if edges[0].Status != AncestryStatusCurrent || edges[0].RepoSource != StackRepoInferred {
		t.Errorf("edge = %+v, want a current edge stamped inferred", edges[0])
	}
}

// TestAncestryHealthIssues_MismatchPathsSanitized pins that the feature-level
// mismatch issue never echoes a raw control character from a recorded path.
func TestAncestryHealthIssues_MismatchPathsSanitized(t *testing.T) {
	res := StackRepoResolution{
		RepoDir:   "/srv/repo\x1b[31m",
		Source:    StackRepoWorktree,
		Alternate: "/srv/other\nrepo",
	}
	issues := AncestryHealthIssues(res, nil)
	if len(issues) != 1 {
		t.Fatalf("expected one mismatch issue, got %+v", issues)
	}
	if strings.ContainsAny(issues[0].Problem, "\n\r\t\x1b") || strings.ContainsAny(issues[0].Hint, "\n\r\t\x1b") {
		t.Errorf("mismatch issue is not sanitized: %+v", issues[0])
	}
	if !strings.Contains(issues[0].Problem, "/srv/repo") || !strings.Contains(issues[0].Hint, "/srv/other") {
		t.Errorf("mismatch issue lost the identifying path: %+v", issues[0])
	}
}

// TestAncestryHealthIssues_NotesProjected pins that notes reach external doctor
// for every edge, including `current` ones, and never change the count.
func TestAncestryHealthIssues_NotesProjected(t *testing.T) {
	edges := []StackEdge{
		{
			Name: "ok", Status: AncestryStatusCurrent, Reason: ReasonParentContained, Severity: SeverityOK,
			Notes: []StackEdgeNote{{Kind: NoteBaseIdentityRemoteMismatch, Detail: "remote detail"}},
		},
		{
			Name: "stale", Status: AncestryStatusStale, Reason: ReasonParentAdvanced, Severity: SeverityWarning,
			Guidance: "run sync",
			Notes:    []StackEdgeNote{{Kind: NoteBaseIdentityLiteralMismatch, Detail: "literal detail"}},
		},
	}
	issues := AncestryHealthIssues(StackRepoResolution{RepoDir: "/repo", Source: StackRepoWorkspace}, edges)
	if len(issues) != 3 {
		t.Fatalf("expected one note issue per edge plus the stale warning, got %+v", issues)
	}
	if issues[0].Branch != "ok" || issues[0].Problem != "ancestry note: base-identity-remote-mismatch" {
		t.Errorf("a current edge must still project its note: %+v", issues[0])
	}
	if issues[0].Hint != "remote detail" || issues[0].Severity != SeverityInfo {
		t.Errorf("note issue = %+v, want the detail as an info hint", issues[0])
	}
	if issues[1].Problem != "ancestry stale: parent-advanced" {
		t.Errorf("the edge issue must precede its note: %+v", issues[1])
	}
	if issues[2].Problem != "ancestry note: base-identity-literal-mismatch" {
		t.Errorf("unexpected third issue: %+v", issues[2])
	}
	if got := CountHealthIssues(issues); got != 1 {
		t.Errorf("counted %d, want 1 — notes are never counted", got)
	}
}

// ---------- Revision: probe failure reaches the surface end to end ----------

// TestStackAncestry_ProbeFailedEndToEnd replaces `git merge-base` with a shim
// that fails fatally, so the evaluator's degraded path is exercised through the
// real classifier and the real formatter rather than a synthetic edge.
func TestStackAncestry_ProbeFailedEndToEnd(t *testing.T) {
	realGit, err := exec.LookPath("git")
	if err != nil {
		t.Fatalf("git not found: %v", err)
	}
	dir, ws := setupHealthTestRepo(t)
	forkChild(t, dir, "parent", "main", 1)
	forkChild(t, dir, "child", "parent", 1)
	advance(t, dir, "parent", 1)
	addStackEntries(t, ws, "myfeat", []StackEntry{
		{Name: "parent", Base: "main"},
		{Name: "child", Base: "parent"},
	})

	binDir := t.TempDir()
	script := "#!/bin/sh\nfor a in \"$@\"; do\n  if [ \"$a\" = \"merge-base\" ]; then\n    echo 'fatal: simulated merge-base failure' >&2\n    exit 128\n  fi\ndone\nexec '" + realGit + "' \"$@\"\n"
	if err := os.WriteFile(filepath.Join(binDir, "git"), []byte(script), 0755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", binDir+string(os.PathListSeparator)+os.Getenv("PATH"))

	edge := edgeNamed(t, evalEdges(t, dir,
		StackEntry{Name: "parent", Base: "main"},
		StackEntry{Name: "child", Base: "parent"},
	), "child")
	if edge.Reason != ReasonAncestryProbeFailed {
		t.Fatalf("reason = %q, want ancestry-probe-failed", edge.Reason)
	}
	if edge.Status != "" {
		t.Errorf("status = %q, want the empty (not evaluated) status", edge.Status)
	}
	if edge.Severity != SeverityInfo {
		t.Errorf("severity = %q, want info", edge.Severity)
	}
	if edge.MergeBase != nil {
		t.Error("a failed probe must publish no merge base")
	}
	if !strings.Contains(edge.Guidance, "ancestry probe failed") || !strings.Contains(edge.Guidance, "re-run: tws doctor myfeat") {
		t.Errorf("guidance = %q", edge.Guidance)
	}
	assertSanitizedLine(t, edge.Guidance)

	report, err := BuildCheckoutHealthReport(ws, &CheckoutHealthOpts{Proc: fakeProcessChecker{}, Tmux: fakeTmuxChecker{}})
	if err != nil {
		t.Fatalf("a failed probe must never fail the report: %v", err)
	}
	out := FormatCheckoutHealth(report)
	if !strings.Contains(out, "ancestry=unevaluated") || !strings.Contains(out, "reason: ancestry-probe-failed") {
		t.Errorf("expected the unevaluated rendering in:\n%s", out)
	}
	if report.HasErrors() {
		t.Error("a failed ancestry probe must never produce an error exit")
	}
}

func TestDoctorCutoffEvidenceRendering(t *testing.T) {
	cases := []struct {
		name string
		edge StackEdge
		want string
	}{
		{
			name: "valid-recorded",
			edge: StackEdge{Name: "recorded", LastBaseSHA: "aaa", EffectiveCutoff: "aaa",
				CutoffSource: SyncCutoffSourceRecorded, CutoffValidity: SyncCutoffValid,
				CutoffReason: SyncCutoffReasonValidRecorded},
			want: `cutoff evidence: raw="aaa" effective="aaa" source=recorded-metadata validity=valid reason=recorded-cutoff-valid`,
		},
		{
			name: "valid-parent-tip-fallback",
			edge: StackEdge{Name: "fallback", EffectiveCutoff: "bbb",
				CutoffSource: SyncCutoffSourceParentTip, CutoffValidity: SyncCutoffValid,
				CutoffReason: SyncCutoffReasonValidParentTip},
			want: `cutoff evidence: raw="<absent>" effective="bbb" source=parent-tip-ancestor validity=valid reason=missing-cutoff-parent-ancestor`,
		},
		{
			name: "sha1-prose-abbreviated",
			edge: StackEdge{Name: "sha1", LastBaseSHA: strings.Repeat("a", 40),
				EffectiveCutoff: strings.Repeat("a", 40),
				CutoffSource:    SyncCutoffSourceRecorded, CutoffValidity: SyncCutoffValid,
				CutoffReason: SyncCutoffReasonValidRecorded},
			want: `cutoff evidence: raw="aaaaaaaaaaaa" effective="aaaaaaaaaaaa" source=recorded-metadata validity=valid reason=recorded-cutoff-valid`,
		},
		{
			name: "sha256-prose-abbreviated",
			edge: StackEdge{Name: "sha256", LastBaseSHA: strings.Repeat("A", 64),
				EffectiveCutoff: strings.Repeat("a", 64),
				CutoffSource:    SyncCutoffSourceRecorded, CutoffValidity: SyncCutoffValid,
				CutoffReason: SyncCutoffReasonValidRecorded},
			want: `cutoff evidence: raw="aaaaaaaaaaaa" effective="aaaaaaaaaaaa" source=recorded-metadata validity=valid reason=recorded-cutoff-valid`,
		},
		{
			name: "raw-ref-preserved",
			edge: StackEdge{Name: "tag", LastBaseSHA: "refs/tags/release-base",
				EffectiveCutoff: strings.Repeat("b", 40),
				CutoffSource:    SyncCutoffSourceRecorded, CutoffValidity: SyncCutoffValid,
				CutoffReason: SyncCutoffReasonValidRecorded},
			want: `cutoff evidence: raw="refs/tags/release-base" effective="bbbbbbbbbbbb" source=recorded-metadata validity=valid reason=recorded-cutoff-valid`,
		},
		{
			name: "invalid-sanitized",
			edge: StackEdge{Name: "invalid", LastBaseSHA: "bad\nraw",
				CutoffSource: SyncCutoffSourceRecorded, CutoffValidity: SyncCutoffInvalid,
				CutoffReason: SyncCutoffReasonRecordedNotAncestor},
			want: `cutoff evidence: raw="bad?raw" effective="<none>" source=recorded-metadata validity=invalid reason=recorded-cutoff-not-ancestor`,
		},
		{
			name: "unevaluated",
			edge: StackEdge{Name: "unknown", LastBaseSHA: "ccc"},
			want: "",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			tc.edge.Status = AncestryStatusCurrent
			tc.edge.Reason = ReasonParentContained
			tc.edge.Severity = SeverityOK
			issues := AncestryHealthIssues(StackRepoResolution{}, []StackEdge{tc.edge})
			if tc.want == "" {
				if len(issues) != 0 {
					t.Fatalf("unevaluated external doctor emitted cutoff evidence: %+v", issues)
				}
			} else if len(issues) != 1 || issues[0].Problem != tc.want || issues[0].Severity != SeverityInfo {
				t.Fatalf("external doctor evidence = %+v, want %q", issues, tc.want)
			}
			entry := CheckoutFeatureEntry{
				LastBaseSHA: tc.edge.LastBaseSHA, EffectiveCutoff: tc.edge.EffectiveCutoff,
				CutoffSource: tc.edge.CutoffSource, CutoffValidity: tc.edge.CutoffValidity,
				CutoffReason: tc.edge.CutoffReason, AncestryStatus: AncestryStatusCurrent,
			}
			lines := checkoutFeatureDetailLines(entry)
			if tc.want == "" {
				if len(lines) != 0 {
					t.Fatalf("unevaluated checkout doctor emitted cutoff evidence: %v", lines)
				}
			} else if len(lines) != 1 || lines[0] != tc.want {
				t.Fatalf("checkout doctor evidence = %v, want %q", lines, tc.want)
			}
		})
	}
}

func TestParentAdvancedWithoutCutoffGuidanceRefusesGuessing(t *testing.T) {
	guidance := ancestryGuidance(StackEdge{
		Feature: "feature", Name: "child", GitBranch: "child",
		BaseRef: "parent", ParentHeadShort: "abc1234",
		Reason: ReasonParentAdvancedNoBaseRecord,
	}, "")
	for _, want := range []string{
		"no recorded cutoff exists", "sync will refuse rather than guess",
		"repair last_base_sha from a proven commit",
	} {
		if !strings.Contains(guidance, want) {
			t.Fatalf("guidance %q lacks %q", guidance, want)
		}
	}
	if strings.Contains(guidance, "plain rebase") || strings.Contains(guidance, "run: tws sync") {
		t.Fatalf("guidance still promises an unsafe sync: %q", guidance)
	}
	assertSanitizedLine(t, guidance)
}

package internal

import (
	"bytes"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// ---------- Constants ----------

// stackStatusSchema versions the stack status document. It is this document's
// own version and is independent of agentStatusSchema. Adding a key or an enum
// value is additive; removing a key, changing a type, or narrowing an enum
// bumps it.
const stackStatusSchema = 1

// stackStatusSanitizeLimit bounds dynamic values echoed into human output.
// Paths, branch names, and upstream displays are routinely longer than a ref
// name, so the ancestry evaluator's 40-rune metadata limit is too small here.
const stackStatusSanitizeLimit = 120

// StackStatusOpNone is the only value that means "the Git directory was
// resolved, verified, and carries no operation marker". A probe failure is
// never reported as this value.
const StackStatusOpNone = "none"

// Materialization kinds.
const (
	StackStatusKindWorktree = "worktree"
	StackStatusKindRef      = "ref"
)

// Materialization states.
const (
	StackStatusMaterializedPresent         = "present"
	StackStatusMaterializedArchived        = "archived"
	StackStatusMaterializedMissing         = "missing"
	StackStatusMaterializedPrunableMissing = "prunable-missing"
	StackStatusMaterializedCrossRepo       = "cross-repo-unsupported"
	StackStatusMaterializedUnknown         = "unknown"
)

// Upstream states.
const (
	StackStatusUpstreamNone     = "none"
	StackStatusUpstreamEqual    = "equal"
	StackStatusUpstreamAhead    = "ahead"
	StackStatusUpstreamBehind   = "behind"
	StackStatusUpstreamDiverged = "diverged"
	StackStatusUpstreamGone     = "gone"
)

// stackStatusRefFormat is the branch-ref inventory format. Fields are
// NUL-separated so no printable delimiter can appear inside a value, and only
// full refs are requested so a same-named tag can never win a lookup.
const stackStatusRefFormat = "%(refname)%00%(objectname)%00%(upstream)%00%(upstream:track)%00%(upstream:trackshort)"

const stackStatusHeadsPrefix = "refs/heads/"

// stackStatusObjectID matches an inventory object ID. It is object-format
// neutral on purpose: a SHA-256 repository prints 64 hex characters where a
// SHA-1 repository prints 40, and neither inventory may invalidate merely
// because the repository's object format is not SHA-1. It is parser validation
// only — it gates no identity claim, comparison, truncation, or derivation.
var stackStatusObjectID = regexp.MustCompile(`^[0-9a-f]+$`)

// stackStatusDecimal matches a non-negative decimal integer with no sign and
// no surrounding whitespace.
var stackStatusDecimal = regexp.MustCompile(`^[0-9]+$`)

// ---------- Report types ----------
//
// No field below is ever omitted when empty: every key is present in every
// document, absent scalars are null, and lists are never null.

// StackStatusReport is one versioned stack status document.
type StackStatusReport struct {
	SchemaVersion int                  `json:"schema_version"`
	Workspace     StackStatusWorkspace `json:"workspace"`
	Feature       string               `json:"feature"`
	Entries       []StackStatusEntry   `json:"entries"`
	Summary       StackStatusSummary   `json:"summary"`

	// Reparent is the §11.10 projection of an in-progress safe reparent. It is
	// the ONE deliberate exception to the "no field is ever omitted" rule
	// above: declaring it omitempty with a POINTER value keeps the key ABSENT
	// — never null — whenever no artifact exists, which is what leaves the
	// no-reparent document byte-identical to today and SchemaVersion at 1.
	Reparent *ReparentProjection `json:"reparent,omitempty"`
}

// StackStatusWorkspace describes the resolved workspace. Exactly one of
// External and Checkout is non-nil, selected by the workspace mode.
type StackStatusWorkspace struct {
	Mode         WorkspaceMode         `json:"mode"`
	StableID     *string               `json:"stable_id"`
	MetadataRoot string                `json:"metadata_root"`
	Repository   StackStatusRepository `json:"repository"`
	External     *StackStatusExternal  `json:"external"`
	Checkout     *StackStatusCheckout  `json:"checkout"`
}

// StackStatusRepository is the single repository resolution the shared
// ancestry evaluator already performed. It is never rediscovered here.
type StackStatusRepository struct {
	Dir       *string         `json:"dir"`
	Source    StackRepoSource `json:"source"`
	Alternate *string         `json:"alternate"`
}

// StackStatusExternal carries only the worktrees root: external mode has many
// linked worktrees and no single current checkout.
type StackStatusExternal struct {
	WorktreesRoot string `json:"worktrees_root"`
}

// StackStatusCheckout describes the single physical checkout of a checkout
// workspace. Every fact that could not be established locally is null.
type StackStatusCheckout struct {
	Path        *string `json:"path"`
	Branch      *string `json:"branch"`
	Detached    *bool   `json:"detached"`
	Dirty       *bool   `json:"dirty"`
	ActiveGitOp *string `json:"active_git_op"`
}

// StackStatusEntry is one row, one per stack.Branches element in slice order.
type StackStatusEntry struct {
	Name              string                     `json:"name"`
	GitBranch         string                     `json:"git_branch"`
	Archived          bool                       `json:"archived"`
	Repo              *string                    `json:"repo"`
	Base              StackStatusBase            `json:"base"`
	RefExists         *bool                      `json:"ref_exists"`
	Heads             StackStatusHeads           `json:"heads"`
	BaseRecord        StackStatusBaseRecord      `json:"base_record"`
	Ancestry          StackStatusAncestry        `json:"ancestry"`
	RepoSource        StackRepoSource            `json:"repo_source"`
	ParentCounts      StackStatusParentCounts    `json:"parent_counts"`
	Materialization   StackStatusMaterialization `json:"materialization"`
	IsCurrentCheckout *bool                      `json:"is_current_checkout"`
	Upstream          StackStatusUpstream        `json:"upstream"`
}

// StackStatusBase projects the evaluator's base selection.
type StackStatusBase struct {
	Name *string       `json:"name"`
	Kind StackBaseKind `json:"kind"`
	Ref  *string       `json:"ref"`
}

// StackStatusHeads projects the evaluator's peeled heads.
type StackStatusHeads struct {
	Local          *string `json:"local"`
	LocalShort     *string `json:"local_short"`
	Parent         *string `json:"parent"`
	ParentShort    *string `json:"parent_short"`
	MergeBase      *string `json:"merge_base"`
	MergeBaseShort *string `json:"merge_base_short"`
}

// StackStatusBaseRecord projects the recorded last_base_sha verdict. State is
// null when the record was never consulted: a verdict never formed is never
// published.
type StackStatusBaseRecord struct {
	SHA       *string `json:"sha"`
	Commit    *string `json:"commit"`
	Short     *string `json:"short"`
	State     *string `json:"state"`
	Effective *string `json:"effective"`
	Source    *string `json:"source"`
	Validity  *string `json:"validity"`
	Reason    *string `json:"reason"`
}

// StackStatusNote projects one informational evaluator note.
type StackStatusNote struct {
	Kind   StackNoteKind `json:"kind"`
	Detail string        `json:"detail"`
}

// StackStatusAncestry projects the shared evaluator's verdict verbatim. This
// command computes no ancestry of its own.
type StackStatusAncestry struct {
	Status   *string             `json:"status"`
	Reason   StackAncestryReason `json:"reason"`
	Severity CheckoutSeverity    `json:"severity"`
	Guidance *string             `json:"guidance"`
	Notes    []StackStatusNote   `json:"notes"`
}

// StackStatusParentCounts holds local commit counts against the parent head.
// It is never a remote-freshness claim.
type StackStatusParentCounts struct {
	Ahead  *int `json:"ahead"`
	Behind *int `json:"behind"`
}

// StackStatusMaterialization describes whether and how the row exists on disk.
type StackStatusMaterialization struct {
	Kind             string  `json:"kind"`
	State            string  `json:"state"`
	Path             *string `json:"path"`
	CheckedOutBranch *string `json:"checked_out_branch"`
	Detached         *bool   `json:"detached"`
	Dirty            *bool   `json:"dirty"`
	ActiveGitOp      *string `json:"active_git_op"`
}

// StackStatusUpstream describes the configured upstream ref exactly as it
// exists in this repository right now.
type StackStatusUpstream struct {
	Configured *bool   `json:"configured"`
	Ref        *string `json:"ref"`
	Display    *string `json:"display"`
	State      *string `json:"state"`
	Ahead      *int    `json:"ahead"`
	Behind     *int    `json:"behind"`
	LocalOnly  bool    `json:"local_only"`
