	})

	t.Run("external empty", func(t *testing.T) {
		fx := ssNewExternalFixture(t, "auth")
		ssAssertReportKeys(t, ssDecode(t, fx.build(Stack{})), ModeExternal)
	})

	t.Run("checkout populated", func(t *testing.T) {
