				t.Fatalf("cross-repo upstream.local_only = %v", up["local_only"])
			}
		}
		if m["ancestry"].(map[string]any)["notes"] == nil {
			t.Fatalf("entry %d notes must be [] and never null", i)
		}
	}
}

