type cutoffFixture struct {
	repo, root, shared, oldParent, newParent, child, currentChild string
}

func cutoffGit(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(),
		"GIT_CONFIG_NOSYSTEM=1",
		"GIT_AUTHOR_NAME=Cutoff Test", "GIT_AUTHOR_EMAIL=cutoff@example.com",
		"GIT_COMMITTER_NAME=Cutoff Test", "GIT_COMMITTER_EMAIL=cutoff@example.com",
	)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %s: %s: %v", strings.Join(args, " "), out, err)
	}
	return strings.TrimSpace(string(out))
}

func cutoffCommit(t *testing.T, repo, file, body, message string) string {
	t.Helper()
	if err := os.WriteFile(filepath.Join(repo, file), []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	cutoffGit(t, repo, "add", file)
	cutoffGit(t, repo, "commit", "-m", message)
	return cutoffGit(t, repo, "rev-parse", "HEAD")
}

func newCutoffFixture(t *testing.T) cutoffFixture {
	t.Helper()
	repo := t.TempDir()
	cutoffGit(t, repo, "init", "-b", "main")
	root := cutoffCommit(t, repo, "history.txt", "root\n", "root")
	shared := cutoffCommit(t, repo, "history.txt", "root\nshared\n", "shared")
	cutoffGit(t, repo, "switch", "-c", "old-parent")
	oldParent := cutoffCommit(t, repo, "parent-old.txt", "old\n", "old parent")
	cutoffGit(t, repo, "switch", "-c", "child")
	child := cutoffCommit(t, repo, "child.txt", "child\n", "child")
	cutoffGit(t, repo, "switch", "main")
	cutoffGit(t, repo, "switch", "-c", "new-parent", shared)
	newParent := cutoffCommit(t, repo, "parent-new.txt", "new\n", "new parent")
	cutoffGit(t, repo, "switch", "-c", "current-child")
	currentChild := cutoffCommit(t, repo, "current-child.txt", "current\n", "current child")
	return cutoffFixture{
		repo: repo, root: root, shared: shared, oldParent: oldParent,
		newParent: newParent, child: child, currentChild: currentChild,
	}
}

func TestResolveSyncCutoffRecordedAndMissingPolicies(t *testing.T) {
	f := newCutoffFixture(t)
	common := cutoffGit(t, f.repo, "rev-parse", "--git-common-dir")
	if !filepath.IsAbs(common) {
		common = filepath.Join(f.repo, common)
	}

	t.Run("correct recorded rewritten parent cutoff", func(t *testing.T) {
		got, err := ResolveSyncCutoff(SyncCutoffResolveInput{
			RepoDir: f.repo, RepoCommonDir: common, Entry: "child", GitBranch: "child",
			ParentRef: "new-parent", ParentSHA: f.newParent, ChildSHA: f.child,
			Recorded: f.oldParent, Applicable: true,
		})
		if err != nil {
			t.Fatal(err)
		}
		if got.Validity != SyncCutoffValid || got.Source != SyncCutoffSourceRecorded ||
			got.EffectiveSHA != f.oldParent || got.RecordedSHA != f.oldParent {
			t.Fatalf("decision = %+v", got)
		}
	})

	t.Run("missing cutoff uses exact ancestor parent", func(t *testing.T) {
		got, err := ResolveSyncCutoff(SyncCutoffResolveInput{
			RepoDir: f.repo, RepoCommonDir: common, Entry: "current-child", GitBranch: "current-child",
			ParentRef: "new-parent", ParentSHA: f.newParent, ChildSHA: f.currentChild,
			Applicable: true,
		})
		if err != nil {
			t.Fatal(err)
		}
		if got.Source != SyncCutoffSourceParentTip || got.EffectiveSHA != f.newParent ||
			got.Reason != SyncCutoffReasonValidParentTip {
			t.Fatalf("decision = %+v", got)
		}
	})

	t.Run("missing cutoff refuses divergent parent", func(t *testing.T) {
		_, err := ResolveSyncCutoff(SyncCutoffResolveInput{
			RepoDir: f.repo, RepoCommonDir: common, Entry: "child", GitBranch: "child",
			ParentRef: "new-parent", ParentSHA: f.newParent, ChildSHA: f.child,
			Applicable: true,
		})
		var refusal *SyncCutoffRefusalError
		if !errors.As(err, &refusal) || refusal.Decision.Reason != SyncCutoffReasonMissingParentNotAncestor {
			t.Fatalf("err = %v", err)
		}
	})

	t.Run("stale ancestor before shared history refuses", func(t *testing.T) {
		_, err := ResolveSyncCutoff(SyncCutoffResolveInput{
			RepoDir: f.repo, RepoCommonDir: common, Entry: "child", GitBranch: "child",
			ParentRef: "new-parent", ParentSHA: f.newParent, ChildSHA: f.child,
			Recorded: f.root, Applicable: true,
		})
		var refusal *SyncCutoffRefusalError
		if !errors.As(err, &refusal) ||
			refusal.Decision.Reason != SyncCutoffReasonRecordedPredatesShared ||
			refusal.Decision.SharedSHA != f.shared {
			t.Fatalf("err = %v decision=%+v", err, refusal)
		}
	})

	t.Run("nonancestor and missing records refuse", func(t *testing.T) {
		for name, recorded := range map[string]string{
			"nonancestor": f.newParent,
			"missing":     strings.Repeat("f", len(f.root)),
		} {
			t.Run(name, func(t *testing.T) {
				_, err := ResolveSyncCutoff(SyncCutoffResolveInput{
					RepoDir: f.repo, RepoCommonDir: common, Entry: "child", GitBranch: "child",
					ParentRef: "new-parent", ParentSHA: f.newParent, ChildSHA: f.child,
					Recorded: recorded, Applicable: true,
				})
				var refusal *SyncCutoffRefusalError
				if !errors.As(err, &refusal) {
					t.Fatalf("err = %v", err)
				}
				if name == "nonancestor" && refusal.Decision.Reason != SyncCutoffReasonRecordedNotAncestor {
					t.Fatalf("reason = %s", refusal.Decision.Reason)
				}
				if name == "missing" && refusal.Decision.Reason != SyncCutoffReasonRecordedUnresolvable {
					t.Fatalf("reason = %s", refusal.Decision.Reason)
				}
			})
		}
	})
}

func TestSyncLatestObservedRefChangesUsesActualImages(t *testing.T) {
	tx := &SyncTransaction{Actions: []SyncTransactionAction{{
		Status: SyncTxnActionObserved, RepoCommonDir: "/repo",
		BeforeRefs: []SyncTransactionRefValue{
			{Ref: "refs/heads/child", SHA: "a"},
			{Ref: "refs/heads/parent", SHA: "b"},
			{Ref: "refs/heads/untouched", SHA: "c"},
		},
		AfterRefs: []SyncTransactionRefValue{
			{Ref: "refs/heads/child", SHA: "d"},
			{Ref: "refs/heads/parent", SHA: "e"},
			{Ref: "refs/heads/untouched", SHA: "c"},
		},
	}}}
	got := SyncLatestObservedRefChanges(tx)
	if len(got) != 2 || got[0].Ref != "refs/heads/child" || got[1].Ref != "refs/heads/parent" {
		t.Fatalf("changes = %+v", got)
	}
}

func TestResolveSyncCutoffExaminesAllBestMergeBases(t *testing.T) {
	repo := t.TempDir()
	cutoffGit(t, repo, "init", "-b", "main")
	tree := cutoffGit(t, repo, "mktree")
	commitTree := func(message string, parents ...string) string {
		t.Helper()
		args := []string{"commit-tree", tree, "-m", message}
		for _, parent := range parents {
			args = append(args, "-p", parent)
		}
		return cutoffGit(t, repo, args...)
	}
	recorded := commitTree("recorded")
	sharedB := commitTree("shared-b", recorded)
	sharedA := commitTree("shared-a")
	parent := commitTree("parent", sharedA, sharedB)
	child := commitTree("child", sharedB, sharedA)
	if recorded == sharedA || sharedA == sharedB {
		t.Fatalf("fixture nodes collapsed: recorded=%s sharedA=%s sharedB=%s", recorded, sharedA, sharedB)
	}
	bases, err := syncCutoffMergeBases(repo, parent, child)
	if err != nil {
		t.Fatal(err)
	}
	if len(bases) != 2 || !slices.Contains(bases, sharedA) || !slices.Contains(bases, sharedB) {
		t.Fatalf("merge bases = %v, want exactly [%s %s]", bases, sharedA, sharedB)
	}

	_, err = ResolveSyncCutoff(SyncCutoffResolveInput{
		RepoDir: repo, Entry: "child", GitBranch: "child",
		ParentRef: "parent", ParentSHA: parent, ChildSHA: child,
		Recorded: recorded, Applicable: true,
	})
	var refusal *SyncCutoffRefusalError
	if !errors.As(err, &refusal) || refusal.Decision.Reason != SyncCutoffReasonRecordedPredatesShared {
		t.Fatalf("criss-cross stale cutoff accepted: err=%v decision=%+v", err, refusal)
	}
	if refusal.Decision.SharedSHA != sharedB {
		t.Fatalf("shared proof = %s, want the best base descended from the record %s", refusal.Decision.SharedSHA, sharedB)
	}
}

func TestSyncCutoffRefusalIncludesSanitizedParentAndRepositoryContext(t *testing.T) {
	err := (&SyncCutoffRefusalError{Decision: SyncCutoffDecision{
		Entry: "logical\nentry", GitBranch: "physical/branch\rname",
		RepoCommonDir: "/repo/\tcommon", ParentRef: "refs/tags/base\n--inject",
		ParentSHA: "parent\nsha", ChildSHA: "child\rsha", Recorded: "recorded\tsha",
		Reason: SyncCutoffReasonRecordedNotAncestor,
	}}).Error()
	if strings.ContainsAny(err, "\n\r\t\x1b") {
		t.Fatalf("refusal is not sanitized: %q", err)
	}
	for _, want := range []string{
		`entry "logical?entry"`,
		`git branch "physical/branch?name"`,
		`repository "/repo/?common"`,
		`parent-ref="refs/tags/base?--inject"`,
		`frozen-parent=parent?sha`,
		`child=child?sha`,
		`recorded=recorded?sha`,
	} {
		if !strings.Contains(err, want) {
			t.Fatalf("refusal %q lacks %q", err, want)
		}
	}
}

package internal

import (
	"fmt"
	"sort"
)

// ---------------------------------------------------------------------------
// sync-modes — the shared selector and plan model (spec §5).
//
// One model, one resolution function, shared by both workspace modes. There is
// no second topological sort, no second descendant walker, no second parent
// lookup, and no second ancestry rule.
// ---------------------------------------------------------------------------

// SyncFetchPolicy is axis F.
type SyncFetchPolicy string

const (
	SyncFetchEnabled  SyncFetchPolicy = "fetch"
	SyncFetchDisabled SyncFetchPolicy = "no-fetch"
)

// SyncPropagationPolicy is axis P.
type SyncPropagationPolicy string

const (
	SyncPropagationFull      SyncPropagationPolicy = "full"
	SyncPropagationLocalOnly SyncPropagationPolicy = "local-only"
)

// SyncScopeKind is axis S.
type SyncScopeKind string

const (
	SyncScopeAll     SyncScopeKind = "all"
	SyncScopeOne     SyncScopeKind = "one"
	SyncScopeSubtree SyncScopeKind = "subtree"
)

// SyncRunPolicy is the frozen decision of one run. It is persisted verbatim.
type SyncRunPolicy struct {
	Fetch       SyncFetchPolicy       `yaml:"fetch_policy"`
	Propagation SyncPropagationPolicy `yaml:"propagation_policy"`
	ScopeKind   SyncScopeKind         `yaml:"scope_kind"`
	Selector    string                `yaml:"scope_selector,omitempty"` // logical StackEntry.Name
}

// SyncSelectionRole classifies one selected entry.
type SyncSelectionRole string

const (
	// SyncRoleAnchor: base is a literal ref, empty, or a stack entry in a
	// different repo. Never rebased under local-only.
	SyncRoleAnchor SyncSelectionRole = "anchor"
	// SyncRolePropagated: base names another stack entry in the same repo.
	SyncRolePropagated SyncSelectionRole = "propagated"
)

// SyncSelectedEntry is one resolved member of the selection, in the order
// TopoSort returned (parent before child; sibling roots retain stack.yaml
// declaration order).
//
// It deliberately carries no LastBaseSHA: no executor may reconstruct
// StackEntry values from the selection, because that would silently drop
// LastBaseSHA and destroy the amend-aware `--onto <base> <LastBaseSHA>` replay.
type SyncSelectedEntry struct {
	Name       string
	GitBranch  string
	Repo       string
	Base       string
	Role       SyncSelectionRole
	ParentName string
	Archived   bool
}

// SyncSelection is the whole resolved plan-independent selection.
type SyncSelection struct {
	Policy  SyncRunPolicy
	Entries []SyncSelectedEntry
	Names   map[string]bool
	Repos   []string
}

// SyncSelectionOpts carries everything the validator needs that the policy does
// not. It is deliberately tiny and value-only: resolution stays pure.
type SyncSelectionOpts struct {
	Mode    WorkspaceMode // ModeExternal or ModeCheckout; selects the checkout-only rules
	NewMode bool          // any trigger flag was Changed; selects the new-mode-only rules
	Feature string        // resolved feature name, interpolated into the I10/I11 messages
}

// SameStackRepo is the single cross-repo predicate. An empty string names the
// default repository.
func SameStackRepo(a, b string) bool {
	if a == "" && b == "" {
		return true
	}
	return a == b
}

// IsAnchorSelection reports whether the selection holds no propagation edge at
// all, which is the local-only no-op condition (D3).
func (s SyncSelection) IsAnchorSelection() bool {
	for _, e := range s.Entries {
		if e.Role == SyncRolePropagated {
			return false
		}
	}
	return true
}

// Anchors returns the selected anchors in selection order.
func (s SyncSelection) Anchors() []SyncSelectedEntry {
	var out []SyncSelectedEntry
	for _, e := range s.Entries {
		if e.Role == SyncRoleAnchor {
			out = append(out, e)
		}
	}
	return out
}

// Role reports the role of one selected entry. Unselected names report the
// zero value, which no executor may treat as a role.
func (s SyncSelection) Role(name string) SyncSelectionRole {
	for _, e := range s.Entries {
		if e.Name == name {
			return e.Role
		}
	}
	return ""
}

// SelectedNames returns the selection's logical names in selection order. It is
// what the v2 payload persists as `selected`.
func (s SyncSelection) SelectedNames() []string {
	out := make([]string, 0, len(s.Entries))
	for _, e := range s.Entries {
		out = append(out, e.Name)
	}
	return out
}

// Scoped reports whether the run restricts the selection below the whole stack.
func (p SyncRunPolicy) Scoped() bool { return p.ScopeKind != SyncScopeAll }

// ScopeLabel renders the scope for the §3.7 header.
func (p SyncRunPolicy) ScopeLabel() string {
	switch p.ScopeKind {
	case SyncScopeOne:
		return "only:" + p.Selector
	case SyncScopeSubtree:
		return "subtree:" + p.Selector
	default:
		return string(SyncScopeAll)
	}
}

// ResolveSyncSelection is the one resolution function. It owns I10, I11, I12,
// and I13 — every selection-validity rule — and no caller re-implements,
// re-checks, or supplements them.
//
// It performs no Git command, no filesystem access, no path resolution, and no
// I/O: opts.Feature is consumed as a message value only.
func ResolveSyncSelection(stack Stack, policy SyncRunPolicy, opts SyncSelectionOpts) (SyncSelection, error) {
	sorted, err := TopoSort(stack)
	if err != nil {
		return SyncSelection{}, err
	}
	return ResolveSyncSelectionFromOrder(stack, sorted, policy, opts)
}

// ResolveSyncSelectionFromOrder is ResolveSyncSelection's body, taking the
// already-sorted order so a caller that already holds this invocation's one
// TopoSort result never sorts a second time. It is otherwise byte-identical
// to ResolveSyncSelection, including every error string.
func ResolveSyncSelectionFromOrder(stack Stack, order []StackEntry, policy SyncRunPolicy, opts SyncSelectionOpts) (SyncSelection, error) {
	members := make(map[string]bool, len(order))
	switch policy.ScopeKind {
	case SyncScopeAll:
		for _, e := range order {
			members[e.Name] = true
		}
	case SyncScopeOne:
		if !HasBranch(stack, policy.Selector) {
			return SyncSelection{}, unknownStackEntryError(policy.Selector, opts.Feature)
		}
		members[policy.Selector] = true
	case SyncScopeSubtree:
		if !HasBranch(stack, policy.Selector) {
			return SyncSelection{}, unknownStackEntryError(policy.Selector, opts.Feature)
		}
		members[policy.Selector] = true
		for name := range Descendants(stack, policy.Selector) {
			members[name] = true
		}
	default:
		return SyncSelection{}, fmt.Errorf("unknown sync scope %q", policy.ScopeKind)
	}

	if policy.ScopeKind != SyncScopeAll {
		if GetBranch(stack, policy.Selector).Archived {
			return SyncSelection{}, archivedStackEntryError(policy.Selector, opts.Feature)
		}
	}

	sel := SyncSelection{Policy: policy, Names: make(map[string]bool, len(members))}
	repoSet := make(map[string]bool)
	for _, entry := range order {
		if !members[entry.Name] {
			continue
		}
		selected := SyncSelectedEntry{
			Name:      entry.Name,
			GitBranch: entry.GitBranch(),
			Repo:      entry.Repo,
			Base:      entry.Base,
			Archived:  entry.Archived,
			Role:      SyncRoleAnchor,
		}
		if parent := GetBranch(stack, entry.Base); parent.Name != "" && SameStackRepo(parent.Repo, entry.Repo) {
			selected.Role = SyncRolePropagated
			selected.ParentName = parent.Name
		}
		sel.Entries = append(sel.Entries, selected)
		sel.Names[entry.Name] = true
		repoSet[entry.Repo] = true
	}

	if opts.Mode == ModeCheckout {
		for _, e := range sel.Entries {
			if !SameStackRepo(e.Repo, "") {
				return SyncSelection{}, fmt.Errorf("stack entry %q belongs to repository %q; checkout sync is single-repository (cross-repo-unsupported)", e.Name, e.Repo)
			}
		}
	}

	if opts.NewMode {
		seen := make(map[string]string, len(sel.Entries))
		for _, e := range sel.Entries {
			if first, ok := seen[e.GitBranch]; ok {
				return SyncSelection{}, fmt.Errorf("stack entries %q and %q share Git branch %q; select one of them with --only", first, e.Name, e.GitBranch)
			}
			seen[e.GitBranch] = e.Name
		}
	}

	for repo := range repoSet {
		sel.Repos = append(sel.Repos, repo)
	}
	sort.Strings(sel.Repos)
	return sel, nil
}

// unknownStackEntryError is the single I10 format string.
func unknownStackEntryError(selector, feature string) error {
	return fmt.Errorf("unknown stack entry %q in feature %q; run: tws stack status %s", selector, feature, feature)
}

// archivedStackEntryError is the single I11 format string.
func archivedStackEntryError(selector, feature string) error {
	return fmt.Errorf("stack entry %q is archived; restore it with: tws new %s %s", selector, feature, selector)
}

